      "path": "src-tauri/src/engine/mod.rs",
      "content": "pub mod agy;\npub mod claude;\nmod claude_channel;\n\n/// Claude 渠道下的实际模型名（opus/sonnet/haiku/fable 别名 → 渠道的槽位模型，\n/// `default` → 渠道默认）。后台复盘直接对渠道发 HTTP，需要和 spawn 用同一份\n/// 解析结果，否则会话里正常的别名到了复盘调用就成了未知模型。\npub(crate) fn resolve_claude_channel_model(\n    selected: Option<&str>,\n    provider: &serde_json::Value,\n    env: &std::collections::HashMap<String, String>,\n) -> Option<String> {\n    claude_channel::resolve_model(selected, Some(provider), env)\n}\npub mod codex;\npub mod codebuddy;\nmod codex_app;\nmod codex_provider_env;\nmod codex_read_only;\nmod codex_usage;\npub mod dsh;\nmod dsh_images;\nmod dsh_session;\nmod events;\npub mod fork;\nmod fork_dsh;\npub mod grok;\nmod grok_acp;\npub mod images;\n#[cfg(windows)]\npub(crate) mod job;\npub mod kimi;\nmod kimi_acp;\npub mod minimax;\nmod minimax_acp;\npub mod models;\npub mod opencode;\npub mod opencode_server;\nmod opencode_session;\npub mod pi_family;\npub mod pi_family_auth;\nmod pi_family_env;\npub mod plan_review;\npub mod qoder;\nmod qoder_session;\nmod reader;\nmod registry;\npub mod resolve;\nmod shell_env;\npub mod wsl_transport;\n\npub(crate) use resolve::command_for_binary;\n\n// Event types and tool-call/todo payload helpers (events.rs).\npub(crate) use events::{\n    assistant_message, parse_todo_args, parse_todo_result, parse_tool_args_value, push_session_id, safe_prompt_arg,\n    tool_call_message, tool_call_message_with_id, tool_call_patch_with_id,\n    tool_path_arg, tool_result_patch, tool_result_patch_with_id,\n};\npub use events::{EngineEvent, TodoItem, TodosPayload};\npub use plan_review::{PlanApproval, PlanReview, PlanReviewKind};\n// Live child-process registry (registry.rs).\npub(crate) use registry::{kill_process_group, next_virtual_pid};\npub use registry::{ChildEntry, ProcessRegistry};\n// Stdout reader / per-turn streaming plumbing (reader.rs).\npub use reader::sweep_staging_dirs;\npub(crate) use reader::{\n    cleanup_staged_files, read_line_capped, run_reader, spawn_stderr_capture, spawn_stdin_writer,\n    LineRead, RunContext, TurnCore, TurnState, VirtualRunGuard, MAX_LINE_BYTES,\n};\n\nuse crate::event_sink;\nuse serde::{Deserialize, Serialize};\nuse serde_json::Value;\nuse std::collections::HashMap;\nuse std::path::{Path, PathBuf};\nuse std::sync::{Arc, Mutex};\nuse tokio::process::Command;\nuse tokio::sync::Mutex as TokioMutex;\n\n/// Windows pops a visible console window for every console-subsystem child a\n/// GUI process spawns (engine CLIs are node/.cmd shims, so every probe and\n/// run flashes one). Suppress it — the child's stdio is piped, the console\n/// would be useless anyway.\n#[cfg(windows)]\npub(crate) fn hide_console(command: &mut Command) {\n    const CREATE_NO_WINDOW: u32 = 0x0800_0000;\n    command.creation_flags(CREATE_NO_WINDOW);\n}\n\n#[derive(Clone, Deserialize)]\n#[serde(rename_all = \"kebab-case\")]\npub enum PromptPlacement {\n    SystemTail,\n    RequestTail,\n}\n\n#[derive(Clone, Deserialize)]\n#[serde(rename_all = \"camelCase\")]\npub struct PromptContribution {\n    pub id: String,\n    pub content: String,\n    pub placement: PromptPlacement,\n    pub visibility: String,\n    pub persistence: String,\n}\n\nfn effective_prompt(prompt: &str, contributions: Vec<PromptContribution>) -> String {\n    let mut effective = prompt.to_string();\n    for (placement, label) in [\n        (PromptPlacement::SystemTail, \"system-tail\"),\n        (PromptPlacement::RequestTail, \"request-tail\"),\n    ] {\n        for contribution in contributions.iter().filter(|contribution| {\n            matches!(\n                (&contribution.placement, &placement),\n                (PromptPlacement::SystemTail, PromptPlacement::SystemTail)\n                    | (PromptPlacement::RequestTail, PromptPlacement::RequestTail)\n            )\n        }) {\n            if contribution.visibility != \"internal\" || contribution.content.trim().is_empty() {\n                continue;\n            }\n            effective.push_str(\"\\n\\n[CCGUI internal \");\n            effective.push_str(label);\n            effective.push_str(\"]\\n\");\n            effective.push_str(&contribution.content);\n        }\n    }\n    effective\n}\n\n#[derive(Clone)]\npub struct SendRequest {\n    pub session_id: Option<String>,\n    pub workspace: PathBuf,\n    pub prompt: String,\n    pub prompt_contributions: Vec<PromptContribution>,\n    /// True only for ccgui's intercepted `/compact`; a user-defined catalog\n    /// command with the same text remains an ordinary CLI prompt.\n    pub native_compact: bool,\n    pub images: Vec<String>,\n    pub model: Option<String>,\n    /// Reasoning effort (\"low\" | \"medium\" | \"high\" | \"xhigh\" | \"max\" | \"ultra\"); engines without an\n    /// effort knob ignore it. Engines that accept a level pass the requested string through.\n    pub effort: Option<String>,\n    /// OpenAI service tier override (OMP `--service-tier` / Codex `-c service_tier`),\n    /// independent of reasoning effort.\n    pub service_tier: Option<String>,\n    /// Permission mode (\"auto\" | \"manual\" | \"plan\" | \"bypass\"); each engine\n    /// resolves it against the modes it can actually honor at spawn (see\n    /// `Engine::resolve_permission`).\n    pub permission: Option<String>,\n    /// User-granted extra directories (db `granted_roots`); claude launches\n    /// pass them as `--add-dir` so reads outside the workspace stop hitting\n    /// headless permission denials. Engines without an equivalent flag\n    /// ignore them.\n    pub additional_dirs: Vec<String>,\n    /// Session-scoped channel id. Official / empty injects nothing; spawn\n    /// falls back to the engine's `current` when this is None.\n    pub provider_id: Option<String>,\n    /// Computer use: expose the app's screenshot/input driver to the agent\n    /// as an MCP server (see computer_use.rs). Engines without an\n    /// MCP-config launch flag ignore it.\n    pub computer_use: Option<bool>,\n    /// 记忆：把 `memory` MCP 工具（memory/mcp.rs）挂给本次会话，并绑定到这\n    /// 个 Bot 的账本。只在选中的 Bot 开启记忆、且引擎能挂 MCP 时由发送路径\n    /// 传入；引擎不能兑现时 prepare_launch 过滤掉（提示词里的记忆区块仍然\n    /// 注入，只是模型拿不到写入工具）。\n    pub memory_bot: Option<String>,\n    /// 逐次调用的工具白名单（任务工作台只读节点）：引擎必须真正把它兑现\n    /// 为运行时约束，否则 prepare_launch 直接拒绝——不允许用节点名假装。\n    pub allowed_tools: Option<Vec<String>>,\n}\npub struct BuiltCommand {\n    pub command: Command,\n    /// Written to stdin after spawn; stdin is then closed.\n    pub stdin_payload: Option<String>,\n    /// Keep the child's stdin open after the payload instead of closing it:\n    /// claude answers control-protocol requests (permission asks, the\n    /// AskUserQuestion dialog) on the same pipe via `control_response` lines.\n    pub keep_stdin_open: bool,\n    /// Private staging files/directories to remove once the process exits.\n    pub cleanup_files: Vec<PathBuf>,\n    /// omp computer-use injection into the workspace's `.omp/mcp.json`;\n    /// restored once the process exits (same funnel as cleanup_files).\n    pub mcp_restore: Option<crate::computer_use::McpRestore>,\n    /// Session id assigned before spawn (grok `-s <uuid>`).\n    pub preassigned_session_id: Option<String>,\n}\n/// Which transport one send uses. On `Own` the app spawns no engine child:\n/// the host driver task owns the process (or the connection) and settles the\n/// turn itself.\n#[derive(Clone, Copy, PartialEq, Eq)]\npub enum Transport {\n    /// The app spawns the CLI and reads its stdout.\n    Child,\n    /// The engine drives its own transport (host session, ACP, app-server).\n    Own,\n}\n\npub trait Engine: Send + Sync {\n    fn id(&self) -> &'static str;\n    fn build_command(&self, req: &SendRequest, bin: &str) -> Result<BuiltCommand, String>;\n    /// The command a host-transport driver spawns, for engines whose `Own`\n    /// transport is a process of their own (codex app-server, grok ACP). The\n    /// driver spawns it verbatim, so channel flags/env land here exactly as\n    /// they do for a child command.\n    ///\n    /// Default: the placeholder a driver that spawns no local child (qoder,\n    /// dsh, opencode) never touches.\n    fn host_command(&self, _req: &SendRequest, _bin: &str) -> Result<BuiltCommand, String> {\n        Ok(BuiltCommand {\n            command: Command::new(\"unused-virtual-engine\"),\n            stdin_payload: None,\n            keep_stdin_open: false,\n            cleanup_files: Vec::new(),\n            mcp_restore: None,\n            preassigned_session_id: None,\n        })\n    }\n    /// Parse one NDJSON stdout line into zero or more events.\n    fn parse_line(&self, line: &str, out: &mut Vec<EngineEvent>);\n    /// Attach this run's served-model sidecar before the reader starts.\n    /// Engines whose injected extension records the provider's own `model`\n    /// read it back; the default is a no-op.\n    fn set_served_models_file(&self, _path: &std::path::Path) {}\n    /// True when this run's stream can report what served it (`Served`).\n    /// The response check keeps its badge while that report is pending;\n    /// a run that can never report shows nothing until evidence arrives,\n    /// instead of an \"unreported\" badge on every turn.\n    fn reports_served(&self) -> bool {\n        false\n    }\n    /// True when the engine drives its own transport (e.g. a host WS session)\n    /// instead of spawning a child process. send_message routes these to a\n    /// virtual run: no spawn, no pid — the registry entry carries only the\n    /// abort handle, and the transport task settles the turn itself.\n    fn drives_own_transport(&self) -> bool {\n        false\n    }\n    /// Transport for one send. Default: an engine that drives its own\n    /// transport keeps it for every workspace, so a WSL one has to be\n    /// rejected — the driver spawns locally and its session has no remote\n    /// path. codex and grok override this: their native harness protocol\n    /// carries the question channel for a local workspace, while a remote one\n    /// keeps today's one-shot CLI child, which the ssh wrapper owns.\n    fn transport_for(&self, _wsl: bool) -> Transport {\n        if self.drives_own_transport() {\n            Transport::Own\n        } else {\n            Transport::Child\n        }\n    }\n    /// Whether this engine accepts image attachments.\n    fn supports_images(&self) -> bool;\n    /// Whether the engine can hand the agent the app's computer-use driver\n    /// (requires an MCP-server launch flag the CLI honors).\n    fn supports_computer_use(&self) -> bool {\n        false\n    }\n    /// Whether the engine can mount the app's per-bot `memory` MCP server for\n    /// one launch. Same mechanism as computer use; a false answer means the\n    /// prompt block still carries MEMORY/USER but no tool claims to write.\n    fn supports_memory(&self) -> bool {\n        false\n    }\n    /// Mount the user's「按需启动」MCP entries for this launch: re-point each\n    /// winning definition at `--mcp-lazy` through the engine's own per-launch\n    /// channel (see mcp/launch.rs). Default: no channel, nothing to do.\n    fn mount_on_demand(\n        &self,\n        _built: &mut BuiltCommand,\n        _servers: &[crate::mcp::launch::OnDemandServer],\n        _workspace: &std::path::Path,\n    ) -> Result<(), String> {\n        Ok(())\n    }\n    /// Whether this engine supports reasoning effort configuration.\n    fn supports_effort(&self) -> bool {\n        false\n    }\n    /// Whether this engine can enforce a per-call tool whitelist (mission\n    /// read-only nodes). Engines that return false are rejected before\n    /// spawn rather than silently running without the constraint.\n    fn supports_tool_constraints(&self) -> bool {\n        false\n    }\n    /// Permission modes this engine can honor at spawn (\"auto\" | \"manual\" |\n    /// \"plan\" | \"bypass\"). These are one-shot headless launches that cannot\n    /// ask mid-turn, so most engines support only a subset; the UI greys out\n    /// the rest rather than promising a mode the CLI would silently ignore.\n    fn supported_permissions(&self) -> &'static [&'static str] {\n        &[\"auto\"]\n    }\n    /// Effective mode for one send: the requested mode when this engine\n    /// supports it, otherwise the engine's first supported mode.\n    fn resolve_permission(&self, requested: Option<&str>) -> &'static str {\n        let supported = self.supported_permissions();\n        requested\n            .and_then(|mode| supported.iter().copied().find(|m| *m == mode))\n            .unwrap_or(supported[0])\n    }\n    /// 计划预览与人工审批能力(engine/plan_review.rs)。默认 Legacy:引擎\n    /// 自身的原生计划入口保持既有行为。返回 Unavailable 时,显式 plan 请求\n    /// 必须在发送前受控拒绝——计划审批是用户决策,auto/bypass、静默回退\n    /// 和自动批准参数都不能代替(OMP/Codex/DSH/Grok/Qoder 在各自适配器\n    /// 接通前都是 Unavailable;PRD §1 原则 1/4)。\n    fn plan_approval(&self) -> PlanApproval {\n        PlanApproval::Legacy\n    }\n}\npub fn engine_by_id(id: &str) -> Option<Box<dyn Engine>> {\n    match id {\n        \"claude\" => Some(Box::new(claude::ClaudeEngine::new())),\n        \"kimi\" => Some(Box::new(kimi::KimiEngine)),\n        \"minimax\" => Some(Box::new(minimax::MiniMaxEngine)),\n        \"codebuddy\" => Some(Box::new(codebuddy::CodeBuddyEngine::new())),\n        \"grok\" => Some(Box::new(grok::GrokEngine)),\n        \"codex\" => Some(Box::new(codex::CodexEngine)),\n        \"pi\" => Some(Box::new(pi_family::pi())),\n        \"omp\" => Some(Box::new(pi_family::omp())),\n        \"dsh\" => Some(Box::new(dsh::DshEngine)),\n        \"agy\" => Some(Box::new(agy::AgyEngine)),\n        \"opencode\" => Some(Box::new(opencode::OpenCodeEngine)),\n        \"qoder\" => Some(Box::new(qoder::QoderEngine::new(\n            qoder::QoderDistribution::Global,\n        ))),\n        \"qoder-cn\" => Some(Box::new(qoder::QoderEngine::new(\n            qoder::QoderDistribution::Cn,\n        ))),\n        _ => None,\n    }\n}\n/// Engine home dir: `$ENV_KEY` (with `~` expansion, as the CLIs resolve it)\n/// when set and non-empty, else `~/<default_dir>`.\npub(crate) fn engine_home(env_key: Option<&str>, default_dir: &str) -> PathBuf {\n    if let Some(key) = env_key {\n        if let Some(value) = std::env::var_os(key).filter(|v| !v.is_empty()) {\n            let text = value.to_string_lossy();\n            if let Ok(expanded) = crate::open_app::expand_user_path(&text) {\n                return expanded;\n            }\n            return PathBuf::from(value);\n        }\n    }\n    fallback_home().join(default_dir)\n}\n/// Codex config/session home. Settings override wins in production so CLI\n/// 管理's directory is what history, official config, and `codex exec` all\n/// read — not a leftover `~/.codex` default. Tests keep using `CODEX_HOME`\n/// / `HOME/.codex` so HomeGuard scratch dirs stay isolated.\npub(crate) fn codex_home() -> PathBuf {\n    #[cfg(not(test))]\n    if let Some(path) = settings_codex_home() {\n        return path;\n    }\n    engine_home(Some(\"CODEX_HOME\"), \".codex\")\n}\n#[cfg(not(test))]\nfn settings_codex_home() -> Option<PathBuf> {\n    let custom = crate::settings::read_settings().ok()?.codex_home?;\n    let trimmed = custom.trim();\n    if trimmed.is_empty() {\n        return None;\n    }\n    crate::open_app::expand_user_path(trimmed).ok()\n}\n/// Home dir for the default engine path. Production uses `dirs` (Known\n/// Folder API on Windows); tests steer the fallback through HOME /\n/// USERPROFILE env instead, because `dirs` ignores env on Windows and would\n/// scan the real profile.\nfn fallback_home() -> PathBuf {\n    #[cfg(test)]\n    {\n        if let Some(home) = std::env::var_os(\"HOME\").filter(|v| !v.is_empty()) {\n            return PathBuf::from(home);\n        }\n        #[cfg(windows)]\n        if let Some(profile) = std::env::var_os(\"USERPROFILE\").filter(|v| !v.is_empty()) {\n            return PathBuf::from(profile);\n        }\n    }\n    dirs::home_dir().unwrap_or_default()\n}\n// ==================== Commands ====================\n\n#[derive(Serialize)]\n#[serde(rename_all = \"camelCase\")]\npub struct SendResult {\n    pub run_id: String,\n    pub session_id: Option<String>,\n}\n#[derive(Debug, Clone, Serialize)]\n#[serde(rename_all = \"camelCase\")]\npub struct EngineInfo {\n    pub id: String,\n    pub available: bool,\n    /// False when the user disabled this CLI in settings; the UI hides it\n    /// from pickers and history lists rather than erroring on launch.\n    pub enabled: bool,\n    pub supports_images: bool,\n    /// Drives the composer's computer-use toggle: engines without an\n    /// MCP-config launch flag cannot receive the driver.\n    pub supports_computer_use: bool,\n    /// Whether the engine can mount the per-bot memory tool. The send path\n    /// reads it so a bot's memory guide only promises a tool that exists.\n    pub supports_memory: bool,\n    /// Whether this engine supports reasoning effort configuration.\n    pub supports_effort: bool,\n    /// Whether this engine can enforce a per-call tool whitelist (mission\n    /// read-only nodes); the workbench blocks read-only nodes otherwise.\n    pub supports_tool_constraints: bool,\n    /// Permission modes the engine honors at spawn; drives the composer\n    /// picker's disabled options.\n    pub permissions: Vec<String>,\n    /// 计划预览与人工审批能力(engine/plan_review.rs):typed = 审批主干已\n    /// 接通;legacy = 引擎原生计划入口(不经主干);unavailable + reason =\n    /// 显式计划请求将被受控拒绝,UI 不得提供可点的计划入口。\n    pub plan: PlanApproval,\n}\nfn codex_bin_from_home(settings: &crate::settings::AppSettings) -> Option<String> {\n    let home = settings.codex_home.as_deref()?.trim();\n    if home.is_empty() {\n        return None;\n    }\n    let expanded = crate::open_app::expand_user_path(home).ok()?;\n    let candidate = expanded.join(\"bin\").join(\"codex\");\n    candidate\n        .exists()\n        .then(|| resolve::resolve_launchable_cli_binary(&candidate.to_string_lossy()))\n}\n/// CLI binary name behind an engine id, when they differ: qoder's engine ids\n/// name the product/distribution, but only the `qodercli*` binaries speak\n/// ACP (the `qoder` binary is the IDE launcher and is rejected at spawn).\npub(crate) fn cli_binary_name(engine_id: &str) -> &str {\n    match engine_id {\n        \"qoder\" => qoder::QoderDistribution::Global.cli_name(),\n        \"qoder-cn\" => qoder::QoderDistribution::Cn.cli_name(),\n        // MiniMax Code ships its CLI under the product-independent `mcode`\n        // command, not the engine id.\n        \"minimax\" => \"mcode\",\n        _ => engine_id,\n    }\n}\npub(crate) fn engine_bin(settings: &crate::settings::AppSettings, engine_id: &str) -> String {\n    // An explicit bin override always wins: it predates the codex-home row\n    // (hidden for codex in the UI), and a stale codexBin in an upgraded\n    // settings.json must not be silently overridden by $home/bin/codex.\n    if let Some(custom) = settings.bin_override(engine_id) {\n        let trimmed = custom.trim();\n        if !trimmed.is_empty() {\n            // Defense in depth: settings write validates too, but the file\n            // may have been hand-edited since.\n            match crate::settings::validate_bin_override(trimmed) {\n                Ok(path) => return resolve::resolve_launchable_cli_binary(&path.to_string_lossy()),\n                Err(reason) => {\n                    eprintln!(\"[engine] ignoring invalid {engine_id} bin override: {reason}\");\n                }\n            }\n        }\n    }\n    if engine_id == \"codex\" {\n        if let Some(from_home) = codex_bin_from_home(settings) {\n            return from_home;\n        }\n    }\n    resolve::resolve_launchable_cli_binary(cli_binary_name(engine_id))\n}\n#[tauri::command]\npub async fn list_engines() -> Result<Vec<EngineInfo>, String> {\n    tauri::async_runtime::spawn_blocking(list_engines_blocking)\n        .await\n        .map_err(|error| format!(\"engine detection task failed: {error}\"))\n}\n\nfn list_engines_blocking() -> Vec<EngineInfo> {\n    let settings = crate::settings::read_settings().unwrap_or_default();\n    let config = crate::config::read_config().unwrap_or_default();\n    crate::config::ENGINES\n        .iter()\n        .map(|id| {\n            let engine = engine_by_id(id).expect(\"known engine\");\n            let available = match settings.bin_override(id) {\n                Some(custom) if !custom.trim().is_empty() => {\n                    crate::settings::validate_bin_override(custom).is_ok()\n                }\n                _ if *id == \"codex\" && codex_bin_from_home(&settings).is_some() => true,\n                _ => resolve::find_cli_binary(cli_binary_name(id), None).is_some(),\n            };\n            EngineInfo {\n                id: id.to_string(),\n                available,\n                enabled: config.section(id).and_then(|s| s.current.as_deref())\n                    != Some(crate::config::DISABLED_PROVIDER_ID),\n                supports_images: engine.supports_images(),\n                supports_computer_use: engine.supports_computer_use(),\n                supports_memory: engine.supports_memory(),\n                supports_effort: engine.supports_effort(),\n                supports_tool_constraints: engine.supports_tool_constraints(),\n                permissions: engine\n                    .supported_permissions()\n                    .iter()\n                    .map(|m| m.to_string())\n                    .collect(),\n                plan: engine.plan_approval(),\n            }\n        })\n        .collect()\n}\n/// Concurrent engine runs; past this the machine thrashes and the registry\n/// fan-out makes interrupts unreliable anyway.\n/// Counted as distinct runs (run ids), not map entries: one run is keyed\n/// under both its run id and its session alias, so an entry count would\n/// halve the real ceiling.\nconst MAX_CONCURRENT_RUNS: usize = 64;\n/// 显式计划请求的能力门禁:计划审批是用户决策,能力不足必须报错,禁止\n/// 降级——auto/bypass、resolve_permission 的静默回退和自动批准参数\n/// (如 --plan-yolo)都不能代替用户批准(PRD §1 原则 1/4、§3.1)。\n/// prepare_launch 在构建命令与 spawn 之前调用;Typed/Legacy 路径放行。\nfn ensure_plan_approval(\n    engine: &str,\n    engine_impl: &dyn Engine,\n    permission: Option<&str>,\n) -> Result<(), String> {\n    if permission == Some(\"plan\") {\n        if let PlanApproval::Unavailable { reason } = engine_impl.plan_approval() {\n            return Err(format!(\n                \"engine {engine} cannot run a human-approved plan: {reason}\"\n            ));\n        }\n    }\n    Ok(())\n}\n\n/// Resolved launch parameters for one send: request, binary, built command.\nstruct Launch {\n    comparison_model: Option<Option<String>>,\n    req: SendRequest,\n    bin: String,\n    built: BuiltCommand,\n    engine_impl: Box<dyn Engine>,\n}\nfn prepare_launch(\n    engine: &str,\n    workspace_path: &str,\n    session_id: Option<String>,\n    prompt: String,\n    prompt_contributions: Vec<PromptContribution>,\n    native_compact: Option<bool>,\n    image_paths: Option<Vec<String>>,\n    model: Option<String>,\n    effort: Option<String>,\n    permission: Option<String>,\n    additional_dirs: Vec<String>,\n    provider_id: Option<String>,\n    computer_use: Option<bool>,\n    memory_bot: Option<String>,\n    allowed_tools: Option<Vec<String>>,\n    wsl: bool,\n) -> Result<Launch, String> {\n    let engine_impl = engine_by_id(engine).ok_or_else(|| format!(\"unknown engine: {engine}\"))?;\n    // 停用 still gates sending. Channel settings apply to this child below;\n    // native CLI files remain the official configuration.\n    crate::config::ensure_engine_enabled(engine)?;\n    ensure_plan_approval(engine, engine_impl.as_ref(), permission.as_deref())?;\n    // 记忆工具注入的是本机 exe + 本机数据库,远端(WSL)CLI 拉不起来。\n    // 发送时提示词快照已经冻结(里面写着「用 memory 工具」),所以这里显式\n    // 拒绝,而不是挂一个起不来的服务器让模型自己发现工具不存在。\n    if wsl && memory_bot.as_deref().is_some_and(|id| !id.trim().is_empty()) {\n        return Err(\"记忆工具不支持远程工作区(WSL):注入的是本机程序\".into());\n    }\n    // 工具白名单是硬约束：引擎不能兑现就直接拒绝启动（不降级为无约束）。\n    let allowed_tools = match allowed_tools {\n        Some(tools) if !tools.is_empty() => {\n            if !engine_impl.supports_tool_constraints() {\n                return Err(format!(\n                    \"engine {engine} does not support per-call tool constraints\"\n                ));\n            }\n            Some(\n                tools\n                    .into_iter()\n                    .map(|tool| tool.trim().to_string())\n                    .filter(|tool| !tool.is_empty())\n                    .take(32)\n                    .collect::<Vec<_>>(),\n            )\n        }\n        Some(_) => return Err(\"tool constraints must not be empty\".into()),\n        None => None,\n    };\n    let provider_id = provider_id.filter(|s| !s.trim().is_empty());\n    let provider = crate::config::resolve_provider(engine, provider_id.as_deref())?;\n    let channel_env = provider\n        .as_ref()\n        .map(|p| crate::provider_files::channel_env(engine, p))\n        .transpose()?\n        .unwrap_or_default();\n    let settings = crate::settings::read_settings().unwrap_or_default();\n    let model = model\n        .filter(|m| !m.trim().is_empty())\n        .or_else(|| settings.default_models.get(engine).cloned())\n        .filter(|m| !m.trim().is_empty());\n    let model = if engine == \"claude\" {\n        claude_channel::resolve_model(model.as_deref(), provider.as_ref(), &channel_env)\n    } else {\n        model\n    };\n    let effort = effort\n        .filter(|e| !e.trim().is_empty())\n        .or_else(|| settings.default_efforts.get(engine).cloned())\n        .filter(|e| !e.trim().is_empty());\n    let req = SendRequest {\n        session_id: session_id.filter(|s| !s.trim().is_empty()),\n        workspace: PathBuf::from(workspace_path),\n        prompt: effective_prompt(&prompt, prompt_contributions),\n        prompt_contributions: Vec::new(),\n        native_compact: native_compact.unwrap_or(false) && engine == \"omp\",\n        images: image_paths.unwrap_or_default(),\n        model,\n        effort,\n        service_tier: match engine {\n            \"omp\" => settings.omp_openai_service_tier.clone(),\n            \"codex\" => settings.codex_service_tier.clone(),\n            _ => None,\n        },\n        permission: permission.filter(|p| !p.trim().is_empty()),\n        // Cap defensively: the list lands on a command line, and a\n        // hand-edited db should not produce an argv bomb.\n        additional_dirs: additional_dirs\n            .into_iter()\n            .map(|d| d.trim().to_string())\n            .filter(|d| !d.is_empty() && Path::new(d).is_absolute())\n            .take(32)\n            .collect(),\n        provider_id,\n        // Only honored by engines that can actually mount the driver.\n        computer_use: computer_use.filter(|on| *on && engine_impl.supports_computer_use()),\n        // Same rule for the memory tool: a bot id is only useful to an engine\n        // that can mount the server. Shape-checked (it becomes argv/env on the\n        // child) and capped like the run id.\n        memory_bot: memory_bot\n            .map(|id| id.trim().to_string())\n            .filter(|id| {\n                !id.is_empty()\n                    && id.len() <= 128\n                    && id\n                        .bytes()\n                        .all(|c| c.is_ascii_alphanumeric() || c == b'-' || c == b'_')\n            })\n            .filter(|_| engine_impl.supports_memory()),\n        allowed_tools,\n    };\n    let bin = engine_bin(&settings, engine);\n    // Host-transport engines spawn through their driver instead: codex/grok\n    // hand back the real app-server / ACP command the driver spawns verbatim\n    // (channel flags and env land on it below, as for any child), while the\n    // session-only engines keep the placeholder their driver never touches.\n    let mut built = if engine_impl.transport_for(wsl) == Transport::Own {\n        let mut own = engine_impl.host_command(&req, &bin)?;\n        // The driver spawns this command with the workspace as its cwd.\n        own.command.current_dir(&req.workspace);\n        own\n    } else if engine == \"kimi\" && provider.is_some() {\n        kimi::build_channel_command(&req, &bin)?\n    } else {\n        engine_impl.build_command(&req, &bin)?\n    };\n    // 按需启动的 MCP 条目：只对本机工作区、无工具白名单的普通发送生效\n    // （远端 CLI 读不到本机 exe；只读/计划隔离要求零 MCP）。失败就保持\n    // 随会话启动，不拦发送。\n    if !wsl && req.allowed_tools.is_none() && !codex_read_only::requested(&req) {\n        let servers = crate::mcp::launch::on_demand_servers(engine, &req.workspace);\n        if !servers.is_empty() {\n            if let Err(error) = engine_impl.mount_on_demand(&mut built, &servers, &req.workspace) {\n                eprintln!(\"[mcp-lazy] {engine}: on-demand mount skipped: {error}\");\n            }\n        }\n    }\n    for (key, value) in &channel_env {\n        built.command.env(key, value);\n    }\n    if engine == \"codex\" && codex_read_only::requested(&req) {\n        codex_read_only::stage(\n            &req,\n            &mut built,\n            &codex_home(),\n            &crate::paths::app_home().join(\"codex-plan-staging\"),\n        )?;\n    }\n    let configured = match (engine, provider.as_ref()) {\n        (\"claude\", Some(provider)) => {\n            claude_channel::apply(&mut built, provider, &channel_env, &req)\n        }\n        (\"codebuddy\", Some(_)) => codebuddy::apply_channel(\n            &mut built,\n            &channel_env,\n            req.model.as_deref(),\n            &crate::paths::app_home().join(\"codebuddy-staging\"),\n        ),\n        (\"kimi\", Some(_)) => kimi::apply_channel(&mut built.command, &channel_env, &req),\n        (\"codex\", Some(provider)) => {\n            codex::apply_channel(&mut built.command, provider, &channel_env, &req)\n        }\n        (\"grok\", Some(provider)) => grok::isolate_channel(&mut built, provider, &req),\n        _ => Ok(()),\n    };\n    if let Err(error) = configured {\n        cleanup_staged_files(&built.cleanup_files);\n        if let Some(restore) = &built.mcp_restore {\n            restore.restore();\n        }\n        return Err(error);\n    }\n    let comparison_model = (engine == \"claude\").then(|| {\n        models::claude_comparison_model(\n            req.model.as_deref().unwrap_or(\"default\"),\n            &bin,\n            provider.as_ref().map(|_| &channel_env),\n            &req.workspace,\n            wsl,\n        )\n    });\n    Ok(Launch {\n        comparison_model,\n        req,\n        bin,\n        built,\n        engine_impl,\n    })\n}\n\n#[tauri::command]\npub async fn send_message(\n    state: tauri::State<'_, crate::AppState>,\n    engine: String,\n    workspace_path: String,\n    session_id: Option<String>,\n    prompt: String,\n    prompt_contributions: Vec<PromptContribution>,\n    native_compact: Option<bool>,\n    image_paths: Option<Vec<String>>,\n    model: Option<String>,\n    effort: Option<String>,\n    permission: Option<String>,\n    provider_id: Option<String>,\n    run_id: Option<String>,\n    computer_use: Option<bool>,\n    memory_bot: Option<String>,\n) -> Result<SendResult, String> {\n    send_message_inner(\n        &state,\n        engine,\n        workspace_path,\n        session_id,\n        prompt,\n        prompt_contributions,\n        native_compact,\n        image_paths,\n        model,\n        effort,\n        permission,\n        provider_id,\n        run_id,\n        computer_use,\n        memory_bot,\n    )\n    .await\n}\n/// Body of the `send_message` command, taking the state directly: integration\n/// tests drive the real spawn/read pipeline without a Tauri app (the mock\n/// runtime links the GUI crates into the test exe, which then cannot load\n/// without a comctl32 v6 manifest).\n/// 插件 agent 轮次入口（plugin_caps::plugin_agent_start 调用）：与聊天发送\n/// 共用同一条 spawn/reader/registry 管线，但事件走独立的\n/// `plugin-agent://event` 流（绝不进 engine://event——chat store 会把未知\n/// runId 当孤儿会话收养）。effort/permission/computer_use/图片暂不开放，\n/// provider_id 缺省 = 引擎当前渠道（与聊天发送同一解析）。\n#[allow(clippy::too_many_arguments)]\npub(crate) async fn plugin_agent_send(\n    state: &crate::AppState,\n    engine: String,\n    workspace_path: String,\n    session_id: Option<String>,\n    prompt: String,\n    model: Option<String>,\n    provider_id: Option<String>,\n    run_id: String,\n    read_only: Option<bool>,\n) -> Result<SendResult, String> {\n    let allowed_tools = plugin_agent_tools(&engine, read_only)?;\n    let session_id = codex_read_only::fresh_plugin_session(&engine, read_only, session_id);\n    let permission = (engine == \"codex\" && read_only == Some(true))\n        .then(|| codex_read_only::PERMISSION.to_string());\n    send_message_inner_with_sink(\n        state,\n        Arc::clone(&state.plugin_sink),\n        engine,\n        workspace_path,\n        session_id,\n        prompt,\n        Vec::new(),\n        None,\n        None,\n        model,\n        None,\n        permission,\n        provider_id,\n        Some(run_id),\n        None,\n        None,\n        allowed_tools,\n    )\n    .await\n}\n\nfn plugin_agent_tools(\n    engine: &str,\n    read_only: Option<bool>,\n) -> Result<Option<Vec<String>>, String> {\n    if read_only != Some(true) {\n        return Ok(None);\n    }\n    if engine == \"codex\" {\n        return Ok(None);\n    }\n    if engine != \"pi\" {\n        return Err(format!(\n            \"engine {engine} does not support isolated plugin read-only runs; only Pi and audited local Codex planning are supported\"\n        ));\n    }\n    Ok(Some(\n        [\"read\", \"grep\", \"find\", \"ls\"]\n            .into_iter()\n            .map(str::to_string)\n            .collect(),\n    ))\n}\n\n/// 任务工作台 agent 节点入口（mission::mission_agent_start 调用）：同一条\n/// spawn/reader/registry 管线，事件走独立的 `mission-agent://event` 流。\n/// `allowed_tools` 是逐节点工具白名单（只读约束）；引擎不能兑现时\n/// prepare_launch 直接拒绝，而不是静默降级。\n#[allow(clippy::too_many_arguments)]\npub(crate) async fn mission_agent_send(\n    state: &crate::AppState,\n    engine: String,\n    workspace_path: String,\n    session_id: Option<String>,\n    prompt: String,\n    model: Option<String>,\n    effort: Option<String>,\n    provider_id: Option<String>,\n    run_id: String,\n    allowed_tools: Option<Vec<String>>,\n) -> Result<SendResult, String> {\n    send_message_inner_with_sink(\n        state,\n        Arc::clone(&state.mission_sink),\n        engine,\n        workspace_path,\n        session_id,\n        prompt,\n        Vec::new(),\n        None,\n        None,\n        model,\n        effort,\n        None,\n        provider_id,\n        Some(run_id),\n        None,\n        None,\n        allowed_tools,\n    )\n    .await\n}\n\n#[allow(clippy::too_many_arguments)]\npub async fn send_message_inner(\n    state: &crate::AppState,\n    engine: String,\n    workspace_path: String,\n    session_id: Option<String>,\n    prompt: String,\n    prompt_contributions: Vec<PromptContribution>,\n    native_compact: Option<bool>,\n    image_paths: Option<Vec<String>>,\n    model: Option<String>,\n    effort: Option<String>,\n    permission: Option<String>,\n    provider_id: Option<String>,\n    run_id: Option<String>,\n    computer_use: Option<bool>,\n    memory_bot: Option<String>,\n) -> Result<SendResult, String> {\n    send_message_inner_with_sink(\n        state,\n        Arc::clone(&state.sink),\n        engine,\n        workspace_path,\n        session_id,\n        prompt,\n        prompt_contributions,\n        native_compact,\n        image_paths,\n        model,\n        effort,\n        permission,\n        provider_id,\n        run_id,\n        computer_use,\n        memory_bot,\n        None,\n    )\n    .await\n}\n\n#[allow(clippy::too_many_arguments)]\nasync fn send_message_inner_with_sink(\n    state: &crate::AppState,\n    sink: Arc<event_sink::EventSink>,\n    engine: String,\n    workspace_path: String,\n    session_id: Option<String>,\n    prompt: String,\n    prompt_contributions: Vec<PromptContribution>,\n    native_compact: Option<bool>,\n    image_paths: Option<Vec<String>>,\n    model: Option<String>,\n    effort: Option<String>,\n    permission: Option<String>,\n    provider_id: Option<String>,\n    run_id: Option<String>,\n    computer_use: Option<bool>,\n    memory_bot: Option<String>,\n    allowed_tools: Option<Vec<String>>,\n) -> Result<SendResult, String> {\n    // A claude process may still be alive for a background task's follow-up\n    // turn on this very session. A new process would stop that task, so the\n    // prompt goes into the live one instead and its events keep their run id.\n    // Chat sends only: plugin and mission turns report on their own event\n    // streams, and the idle process reports on the chat one. Computer-use\n    // sends must launch fresh — the driver is mounted via launch flags.\n    if engine == \"claude\" && Arc::ptr_eq(&sink, &state.sink) && computer_use != Some(true) {\n        let workspace = PathBuf::from(&workspace_path);\n        let images = image_paths.clone().unwrap_or_default();\n        let effective = effective_prompt(&prompt, prompt_contributions.clone());\n        let prefs = registry::FollowupPrefs {\n            model: model.clone(),\n            effort: effort.clone(),\n            permission: permission.clone(),\n            provider_id: provider_id.clone(),\n            memory_bot: memory_bot.clone(),\n            allowed_tools: allowed_tools.clone(),\n            // Only non-computer-use sends reach this branch.\n            computer_use: false,\n        };\n        if let Some(live_run) = deliver_to_idle_followup(\n            &state.processes,\n            session_id.as_deref(),\n            &prefs,\n            || images::claude_stdin_message(&effective, &images, &workspace),\n        )\n        .await?\n        {\n            return Ok(SendResult {\n                run_id: live_run,\n                session_id,\n            });\n        }\n    }\n    let run_id = run_id.unwrap_or_else(|| uuid::Uuid::new_v4().to_string());\n    if run_id.is_empty()\n        || run_id.len() > 128\n        || !run_id\n            .bytes()\n            .all(|c| c.is_ascii_alphanumeric() || c == b'-' || c == b'_')\n    {\n        return Err(\"invalid run id\".into());\n    }\n    // Reserve the run id atomically, before the first await: a contains_key\n    // check here with the registry insert after spawn would let two\n    // concurrent sends carrying the same client id both pass, and the second\n    // insert would overwrite the first entry — orphaning its child (no key\n    // routes an interrupt to it) and streaming two runs under one runId.\n    // The placeholder owns the run's killed/reader_abort handles, so a Stop\n    // landing inside the launch window still settles the turn; every error\n    // path before the real registration drops the reservation.\n    let killed = Arc::new(std::sync::atomic::AtomicBool::new(false));\n    let reader_abort = Arc::new(std::sync::OnceLock::new());\n    {\n        let mut map = state.processes.0.lock().map_err(|e| e.to_string())?;\n        state.processes.ensure_session_not_editing(session_id.as_deref())?;\n        if map.contains_key(&run_id) {\n            return Err(\"run id already active\".into());\n        }\n        if registry::active_run_count(&map) >= MAX_CONCURRENT_RUNS {\n            return Err(format!(\n                \"too many concurrent runs ({MAX_CONCURRENT_RUNS}); wait for one to finish\"\n            ));\n        }\n        let entry = ChildEntry {\n            child: None,\n            pid: 0,\n            run_id: run_id.clone(),\n            killed: Arc::clone(&killed),\n            reader_abort: Arc::clone(&reader_abort),\n            stdin: None,\n            questions: Arc::new(Mutex::new(HashMap::new())),\n            plans: Arc::new(Mutex::new(HashMap::new())),\n        };\n        if let Some(session_id) = session_id.as_ref() {\n            map.entry(session_id.clone()).or_insert_with(|| entry.clone());\n        }\n        map.insert(run_id.clone(), entry);\n    }\n    let reserved = run_id.clone();\n    let result = send_reserved(\n        state,\n        sink,\n        engine,\n        workspace_path,\n        session_id,\n        prompt,\n        prompt_contributions,\n        native_compact,\n        image_paths,\n        model,\n        effort,\n        permission,\n        provider_id,\n        run_id,\n        killed,\n        reader_abort,\n        computer_use,\n        memory_bot,\n        allowed_tools,\n    )\n    .await;\n    if result.is_err() {\n        state.processes.remove_reservation(&reserved);\n    }\n    result\n}\n/// Write a new prompt into the process that settled its turn but stays alive\n/// for a background task's follow-up turn on `session_id`. Returns that run's\n/// id, or None when no such process exists, its launch settings no longer\n/// match this send (a live process cannot take new launch flags), or it can\n/// no longer take input — a mismatched or unwritable one is killed so the\n/// caller's normal `--resume` launch cannot race it on the same session.\nasync fn deliver_to_idle_followup(\n    registry: &Arc<ProcessRegistry>,\n    session_id: Option<&str>,\n    prefs: &registry::FollowupPrefs,\n    message: impl FnOnce() -> Result<String, String>,\n) -> Result<Option<String>, String> {\n    let Some(awaiting) = session_id.and_then(|id| registry.take_awaiting_followup(id)) else {\n        return Ok(None);\n    };\n    let idle_run = awaiting.run_id;\n    let kill_idle = |registry: &Arc<ProcessRegistry>, run: &str| {\n        let registry = Arc::clone(registry);\n        let run = run.to_string();\n        async move {\n            let _ = tauri::async_runtime::spawn_blocking(move || registry.kill(&run)).await;\n        }\n    };\n    if &awaiting.prefs != prefs {\n        kill_idle(registry, &idle_run).await;\n        return Ok(None);\n    }\n    let line = message()?;\n    if registry.write_line(&idle_run, line).await.is_ok() {\n        return Ok(Some(idle_run));\n    }\n    kill_idle(registry, &idle_run).await;\n    Ok(None)\n}\n/// Body of [`send_message_inner`] once the run id is reserved: the caller id\n/// is used as-is (never regenerated — the frontend pre-routes events by it),\n/// and the placeholder's killed/reader_abort handles carry into the real\n/// registry entry so an interrupt from the launch window is honored.\n#[allow(clippy::too_many_arguments)]\nasync fn send_reserved(\n    state: &crate::AppState,\n    sink: Arc<event_sink::EventSink>,\n    engine: String,\n    workspace_path: String,\n    session_id: Option<String>,\n    prompt: String,\n    prompt_contributions: Vec<PromptContribution>,\n    native_compact: Option<bool>,\n    image_paths: Option<Vec<String>>,\n    model: Option<String>,\n    effort: Option<String>,\n    permission: Option<String>,\n    provider_id: Option<String>,\n    run_id: String,\n    killed: Arc<std::sync::atomic::AtomicBool>,\n    reader_abort: Arc<std::sync::OnceLock<tokio::task::AbortHandle>>,\n    computer_use: Option<bool>,\n    memory_bot: Option<String>,\n    allowed_tools: Option<Vec<String>>,\n) -> Result<SendResult, String> {\n    // WSL 远程工作区:引擎进程经 ssh 在发行版内执行(见 wsl_transport)。\n    let wsl_tp = wsl_transport::transport_for_workspace(&state.db, &workspace_path);\n    let mut launch = prepare_launch(\n        &engine,\n        &workspace_path,\n        session_id,\n        prompt,\n        prompt_contributions,\n        native_compact,\n        image_paths,\n        model,\n        effort,\n        permission,\n        // Every user-granted directory rides along as a launch argument, so\n        // a grant approved mid-conversation takes effect on the next send\n        // (each send is a fresh process).\n        state.db.granted_roots().unwrap_or_default(),\n        provider_id,\n        computer_use,\n        memory_bot,\n        allowed_tools,\n        wsl_tp.is_some(),\n    )?;\n    if wsl_tp.is_none() && matches!(engine.as_str(), \"pi\" | \"omp\") {\n        // 只向登录 shell 查询当前引擎配置中的变量：PI 用 $VAR，OMP 用裸名字。\n        // 只注入这次子进程；WSL 不带本机 env，跳过。\n        pi_family_env::apply(&mut launch.built.command, &engine).await;\n    }\n    // pi/omp: the injected extension observes the provider response's own\n    // `model` field and appends it to a per-run sidecar. The reader consults\n    // that file when `message_end` has no `upstreamModel`. Remote workspaces\n    // run the CLI inside WSL, which cannot write this host-side path; runs\n    // without the extension have nothing to write it.\n    if wsl_tp.is_none() && pi_family::loads_served_model_bridge(&engine, &launch.req) {\n        if let Some(path) = pi_family::prepare_served_models_file(&run_id) {\n            launch.engine_impl.set_served_models_file(&path);\n            launch\n                .built\n                .command\n                .env(\"CCGUI_SERVED_MODEL_FILE\", path.as_os_str());\n        }\n    }\n    // Host-stream engines drive their own transport: no child process — the\n    // registry entry only routes interrupts to the transport task. Their\n    // drivers spawn locally, so a remote workspace either keeps the CLI\n    // transport (codex/grok) or has no path at all — 显式拒绝。\n    // OMP 的显式计划会话固定走 ACP 传输(elicitation.form 握手 + 计划文件\n    // 全文,见 omp_acp.rs);其余 omp/pi 请求保持既有子进程路径,不迁移。\n    if launch.engine_impl.transport_for(wsl_tp.is_some()) == Transport::Own\n        || (engine == \"omp\" && pi_family::acp_plan_requested(&launch.req))\n    {\n        // 本机驱动没有远端路径:远程工作区显式拒绝(与旧行为一致),而不是\n        // 静默起一个连不上远端工作区的本地会话。codex/grok 在上面退回 child。\n        if wsl_tp.is_some() {\n            return Err(format!(\"引擎 {engine} 不支持远程工作区(WSL)\"));\n        }\n        // The child path resolves codex's provider credentials further down;\n        // the app-server driver owns its own process, so it needs them here.\n        if engine == \"codex\" && !codex_read_only::requested(&launch.req) {\n            codex_provider_env::apply(&mut launch.built.command).await;\n        }\n        return send_host_stream(state, launch, engine, run_id, killed, reader_abort).await;\n    }\n    let (mut command, extra_cleanup, skip_local_cwd) = match &wsl_tp {\n        Some(tp) => {\n            // 注入的是本机 .omp/mcp.json 与本机 exe:WSL 远端 omp 都用不上,\n            // 先恢复再拒绝,不留下被改过的工作区文件。\n            if let Some(restore) = &launch.built.mcp_restore {\n                restore.restore();\n                return Err(\"操作电脑/记忆工具不支持远程工作区(WSL):注入的是本机程序\".into());\n            }\n            // 依赖本机 staging 文件的引擎(grok 等 cleanup_files 非空):\n            // 远端 CLI 读不到本机文件,直接拒绝而非跑出莫名其妙的失败;\n            // 已写盘的 staging 文件顺手清掉,不 strand。\n            if !launch.built.cleanup_files.is_empty() {\n                for path in &launch.built.cleanup_files {\n                    let _ = std::fs::remove_file(path);\n                }\n                return Err(format!(\n                    \"引擎 {engine} 不支持远程工作区(WSL):依赖本机临时文件\"\n                ));\n            }\n            match wsl_transport::wrap(launch.built.command, tp).await {\n                Ok(wrapped) => (\n                    wrapped.command,\n                    wrapped.cleanup_files,\n                    wrapped.skip_local_cwd,\n                ),\n                Err(error) => {\n                    // wrap 失败(ssh 上传失败等)同样不许 strand staging 文件。\n                    for path in &launch.built.cleanup_files {\n                        let _ = std::fs::remove_file(path);\n                    }\n                    return Err(error);\n                }\n            }\n        }\n        None => (launch.built.command, Vec::new(), false),\n    };\n    let mut cleanup_files = launch.built.cleanup_files;\n    cleanup_files.extend(extra_cleanup);\n    // 本地 env 不跨 ssh:WSL 分支的 command 是本地 ssh 进程,apply 无意义\n    // (还白跑一次登录 shell 解析);远端 codex 用发行版自己的配置。\n    if engine == \"codex\" && wsl_tp.is_none() {\n        // v1.0.0 switched codex to `codex exec --json`: a CLI that predates\n        // the exec transport exits 1 before any event, surfacing as a bare\n        // \"exit code: 1\" banner. Fail fast with an actionable message.\n        codex::check_exec_support(&launch.bin, launch.req.session_id.is_some()).await?;\n        codex_provider_env::apply(&mut command).await;\n    }\n    command\n        .stdin(\n            if launch.built.stdin_payload.is_some() || launch.built.keep_stdin_open {\n                std::process::Stdio::piped()\n            } else {\n                std::process::Stdio::null()\n            },\n        )\n        .stdout(std::process::Stdio::piped())\n        .stderr(std::process::Stdio::piped());\n    // 远程工作区路径在本机不存在 → cwd 落本地当前目录(wsl.exe/ssh 不关心)。\n    if skip_local_cwd {\n        command.current_dir(wsl_transport::fallback_cwd());\n    } else {\n        command.current_dir(&launch.req.workspace);\n    }\n    // Own process group so interrupt can kill the whole tree (grandchildren\n    // inherit the stdout pipe and would otherwise block EOF forever).\n    #[cfg(unix)]\n    command.process_group(0);\n    #[cfg(windows)]\n    hide_console(&mut command);\n    // Shebang shims (`#!/usr/bin/env node`) need the CLI search dirs in\n    // PATH: when adopt_login_shell_path failed/timed out, the process PATH\n    // is a stale launchd snapshot and an absolute shim path alone cannot\n    // find the interpreter. Same dirs find_cli_binary searched; appended\n    // after the process PATH, so normal resolution order is unchanged.\n    // Harmless for the WSL/ssh-wrapped command (local env doesn't cross).\n    command.env(\"PATH\", resolve::cli_search_path());\n\n    let mut child = match command.spawn() {\n        Ok(child) => child,\n        Err(error) => {\n            // Never strand the staging files build_command wrote (grok).\n            cleanup_staged_files(&cleanup_files);\n            if let Some(restore) = &launch.built.mcp_restore {\n                restore.restore();\n            }\n            return Err(format!(\"failed to spawn {}: {error}\", launch.bin));\n        }\n    };\n\n    let kept_stdin = spawn_stdin_writer(\n        &mut child,\n        launch.built.stdin_payload,\n        launch.built.keep_stdin_open,\n    );\n    let questions: Arc<Mutex<HashMap<String, Value>>> = Arc::new(Mutex::new(HashMap::new()));\n    let plans: Arc<Mutex<HashMap<String, Value>>> = Arc::new(Mutex::new(HashMap::new()));\n\n    // The reserved caller id keys the real entry too: inserting under the\n    // same run_id replaces the placeholder, and the shared killed/reader_abort\n    // Arcs keep interrupts from the launch window routed to this child.\n    // Join a kill-on-close job before the run can settle: an orphaned\n    // grandchild (claude's pwsh.exe/conhost.exe) must die with the run's\n    // context, not accumulate outside every tree taskkill can still walk.\n    #[cfg(windows)]\n    let tree_guard = job::assign_kill_on_close(&child);\n    let pid = child.id().unwrap_or(0);\n    // Detach both pipes while we still own the child outright. A missing pipe\n    // after spawn is fatal: kill the child so it cannot run unobserved and\n    // unregistered.\n    let (stdout, stderr) = {\n        let pipes = child.stdout.take().zip(child.stderr.take());\n        match pipes {\n            Some(pair) => pair,\n            None => {\n                let _ = child.start_kill();\n                cleanup_staged_files(&cleanup_files);\n                if let Some(restore) = &launch.built.mcp_restore {\n                    restore.restore();\n                }\n                return Err(\"missing stdout/stderr pipe after spawn\".to_string());\n            }\n        }\n    };\n    let child = Arc::new(TokioMutex::new(child));\n    state.processes.insert(\n        run_id.clone(),\n        ChildEntry {\n            child: Some(Arc::clone(&child)),\n            pid,\n            run_id: run_id.clone(),\n            killed: Arc::clone(&killed),\n            reader_abort: Arc::clone(&reader_abort),\n            stdin: kept_stdin.clone(),\n            questions: Arc::clone(&questions),\n            plans: Arc::clone(&plans),\n        },\n    );\n    if let Some(session_id) = launch.built.preassigned_session_id.as_deref() {\n        state.processes.insert_alias(\n            session_id.to_string(),\n            ChildEntry {\n                child: Some(Arc::clone(&child)),\n                pid,\n                run_id: run_id.clone(),\n                killed: Arc::clone(&killed),\n                reader_abort: Arc::clone(&reader_abort),\n                stdin: kept_stdin.clone(),\n                questions: Arc::clone(&questions),\n                plans: Arc::clone(&plans),\n            },\n        );\n    }\n\n    let stderr_buf = spawn_stderr_capture(stderr);\n    let initial_model = if engine == \"claude\" {\n        launch\n            .req\n            .model\n            .clone()\n            .or_else(|| Some(models::resolve_claude_launch_model(\"default\")))\n            .filter(|m| !m.is_empty())\n    } else {\n        launch.req.model.clone()\n    };\n    let initial_effort = launch.req.effort.clone().filter(|e| !e.trim().is_empty());\n    // MCP runtime snapshots are workspace-scoped; the event dispatcher only\n    // has the run id, so remember the mapping for the run's lifetime.\n    crate::mcp::register_run(&run_id, &launch.req.workspace.to_string_lossy());\n    let ctx = RunContext {\n        core: TurnCore {\n            sink: Arc::clone(&sink),\n            registry: Arc::clone(&state.processes),\n            engine_id: engine.clone(),\n            run_id: run_id.clone(),\n            db: Some(Arc::clone(&state.db)),\n            // Only chat claude runs park for a background follow-up turn;\n            // snapshot the launch settings so a later send can detect drift.\n            followup: (engine == \"claude\" && Arc::ptr_eq(&sink, &state.sink)).then(|| {\n                registry::FollowupPrefs {\n                    model: launch.req.model.clone(),\n                    effort: launch.req.effort.clone(),\n                    permission: launch.req.permission.clone(),\n                    provider_id: launch.req.provider_id.clone(),\n                    memory_bot: launch.req.memory_bot.clone(),\n                    allowed_tools: launch.req.allowed_tools.clone(),\n                    computer_use: launch.req.computer_use == Some(true),\n                }\n            }),\n        },\n        engine_impl: launch.engine_impl,\n        pid,\n        preassigned_session_id: launch.built.preassigned_session_id.clone(),\n        initial_model,\n        comparison_model: launch.comparison_model,\n        initial_effort,\n        child,\n        killed,\n        cleanup_files,\n        mcp_restore: launch.built.mcp_restore,\n        stderr_buf,\n        stdout_plain_buf: Arc::new(Mutex::new(String::new())),\n        #[cfg(windows)]\n        _tree_guard: tree_guard,\n    };\n    let reader = tokio::spawn(run_reader(stdout, ctx));\n    // Registration order is unchanged (entries land before the task can\n    // settle); the OnceLock just hands kill()/kill_all() the handle.\n    let _ = reader_abort.set(reader.abort_handle());\n\n    Ok(SendResult {\n        run_id,\n        session_id: launch.built.preassigned_session_id,\n    })\n}\n\n/// Virtual run path for engines that drive their own transport\n/// ([`Engine::drives_own_transport`]): register a child-less entry whose\n/// `killed` flag and abort handle route interrupts into the transport task,\n/// then detach it. The task dispatches the same event kinds as `run_reader`\n/// and settles the turn itself (done/error + registry cleanup).\nasync fn send_host_stream(\n    state: &crate::AppState,\n    launch: Launch,\n    engine: String,\n    run_id: String,\n    killed: Arc<std::sync::atomic::AtomicBool>,\n    reader_abort: Arc<std::sync::OnceLock<tokio::task::AbortHandle>>,\n) -> Result<SendResult, String> {\n    let pid = next_virtual_pid();\n    let entry = ChildEntry {\n        child: None,\n        pid,\n        run_id: run_id.clone(),\n        killed: Arc::clone(&killed),\n        reader_abort: Arc::clone(&reader_abort),\n        stdin: None,\n        questions: Arc::new(Mutex::new(HashMap::new())),\n        plans: Arc::new(Mutex::new(HashMap::new())),\n    };\n    state.processes.insert(run_id.clone(), entry.clone());\n    if let Some(session_id) = launch.req.session_id.as_deref() {\n        // A resumed host session is keyed up front (same contract as grok's\n        // preassigned id): interrupt by conversation session id must route.\n        state.processes.insert_alias(session_id.to_string(), entry);\n    }\n\n    let core = TurnCore {\n        sink: Arc::clone(&state.sink),\n        registry: Arc::clone(&state.processes),\n        engine_id: engine.clone(),\n        run_id: run_id.clone(),\n        db: Some(Arc::clone(&state.db)),\n        // Host-stream engines never emit BackgroundTasks; no follow-up parking.\n        followup: None,\n    };\n    let resume_session_id = launch.req.session_id.clone();\n    let task = match engine.as_str() {\n        \"dsh\" => tokio::spawn(dsh_session::run_host_turn(\n            core,\n            launch.req,\n            state.dsh_host.clone(),\n            killed,\n            pid,\n        )),\n        \"opencode\" => tokio::spawn(opencode_session::run_server_turn(\n            core,\n            launch.req,\n            launch.bin,\n            state.opencode_server.clone(),\n            killed,\n            pid,\n        )),\n        \"qoder\" | \"qoder-cn\" => tokio::spawn(qoder_session::run_acp_turn(\n            core, launch.req, launch.bin, killed, pid,\n        )),\n        \"grok\" | \"kimi\" => tokio::spawn(grok_acp::run_acp_turn(\n            core,\n            launch.req,\n            launch.built,\n            killed,\n            pid,\n        )),\n        \"minimax\" => tokio::spawn(minimax_acp::run_acp_turn(\n            core,\n            launch.req,\n            launch.built,\n            killed,\n            pid,\n        )),\n        \"codex\" => tokio::spawn(codex_app::run_app_server_turn(\n            core,\n            launch.req,\n            launch.built,\n            killed,\n            pid,\n        )),\n        \"omp\" => tokio::spawn(pi_family::omp_acp::run_acp_turn(\n            core,\n            launch.req,\n            launch.built,\n            killed,\n            pid,\n        )),\n        _ => unreachable!(\"send_host_stream only routes drives_own_transport engines: {engine}\"),\n    };\n    let _ = reader_abort.set(task.abort_handle());\n    Ok(SendResult {\n        run_id,\n        session_id: resume_session_id,\n    })\n}\n/// Async + spawn_blocking: the kill waits for the Windows tree walk to\n/// finish (see `kill_process_group`), and a synchronous command would hold\n/// that wait on the UI thread — the app would visibly hitch on every Stop.\n#[tauri::command]\npub async fn interrupt_session(\n    state: tauri::State<'_, crate::AppState>,\n    session_id: String,\n) -> Result<bool, String> {\n    let registry = Arc::clone(&state.processes);\n    tauri::async_runtime::spawn_blocking(move || registry.kill(&session_id))\n        .await\n        .map_err(|e| e.to_string())\n}\n/// Which of `run_ids` the host still runs. The frontend's orphan sweep asks\n/// before settling a run that went silent: a long command or a question\n/// waiting on the user emits nothing, and silence alone is not a dead run.\n#[tauri::command]\npub async fn live_runs(\n    state: tauri::State<'_, crate::AppState>,\n    run_ids: Vec<String>,\n) -> Result<Vec<String>, String> {\n    Ok(state.processes.live_run_ids(&run_ids))\n}\n/// Answer a pending question card. Multiple transports share this command:\n/// - claude (control protocol): the answers merge into the parked tool input\n///   and ride stdin as a `control_response`.\n/// - omp (rpc-ui): the parked value carries the dialog method; the answer is\n///   an `extension_ui_response` frame on the CLI's stdin.\n/// - dsh (host session): the parked value is an answer context (origin +\n///   clientId + eventId + original request); the answer is an HTTP\n///   `$events/result` outcome.\n/// - grok (ACP) and codex (app-server): the parked value carries the server\n///   request's JSON-RPC id — codex additionally the question-text→id map its\n///   protocol answers by; the answer is the response frame on the CLI's stdin.\n/// - Codex 异步提问：app-server item id 是原始 call id；回答通过 `turn/steer`\n///   发送，并由正在运行的 app-server pump 确认。\n/// `answers` maps each question's text to the chosen option label — an array\n/// of labels for multiSelect questions. `None` means the user\n/// skipped/dismissed. Accepts either the run id or the conversation session\n/// id, like `interrupt_session`.\n#[tauri::command]\npub async fn answer_question(\n    state: tauri::State<'_, crate::AppState>,\n    session_id: String,\n    request_id: String,\n    answers: Option<Value>,\n) -> Result<(), String> {\n    let entry = state\n        .processes\n        .get(&session_id)\n        .ok_or_else(|| \"no running session for this answer\".to_string())?;\n    // Peek, don't remove: a failed write leaves the question parked so the\n    // user can retry (or the EOF drain settles the card honestly).\n    let input = entry\n        .questions\n        .lock()\n        .map_err(|_| \"question state is poisoned\".to_string())?\n        .get(&request_id)\n        .cloned()\n        .ok_or_else(|| \"question is no longer pending\".to_string())?;\n    if let Some(context) = input.get(\"kimiAcp\") {\n        let frame = kimi_acp::answer_frame(context, answers.as_ref())?;\n        state\n            .processes\n            .write_line(&session_id, frame.to_string())\n            .await?;\n        if let Ok(mut questions) = entry.questions.lock() {\n            questions.remove(&request_id);\n        }\n        return Ok(());\n    }\n    // grok's ACP driver parks the server's `_x.ai/ask_user_question` request:\n    // the answer is the JSON-RPC response line on the CLI's stdin.\n    if let Some(acp) = input.get(\"grokAcp\") {\n        let frame = grok_acp::answer_frame(acp, answers.as_ref())?;\n        state\n            .processes\n            .write_line(&session_id, frame.to_string())\n            .await?;\n        if let Ok(mut questions) = entry.questions.lock() {\n            questions.remove(&request_id);\n        }\n        return Ok(());\n    }\n    // MiniMax's ACP driver parks `session/request_permission`: the answer is\n    // the JSON-RPC response line on the CLI's stdin, selecting one of the\n    // ask's advertised options.\n    if let Some(acp) = input.get(\"minimaxAcp\") {\n        let frame = minimax_acp::answer_frame(acp, answers.as_ref())?;\n        state\n            .processes\n            .write_line(&session_id, frame.to_string())\n            .await?;\n        if let Ok(mut questions) = entry.questions.lock() {\n            questions.remove(&request_id);\n        }\n        return Ok(());\n    }\n    // Codex 异步提问附在 AgentMessage 上，不是挂起的 JSON-RPC 服务端请求。\n    // 将选择发给当前回合，收到 Codex 确认后再收起提问卡。\n    if let Some(app) = input.get(\"codexAppAsync\") {\n        let rpc_id = codex_app::next_async_question_rpc_id();\n        let frame = codex_app::async_answer_request(app, &rpc_id, answers.as_ref())?;\n        let response = state\n            .processes\n            .register_pending_rpc_reply(&entry.run_id, &rpc_id)?;\n        if let Err(error) = state\n            .processes\n            .write_line(&session_id, frame.to_string())\n            .await\n        {\n            state\n                .processes\n                .remove_pending_rpc_reply(&entry.run_id, &rpc_id);\n            return Err(error);\n        }\n        let reply = tokio::time::timeout(codex_app::ASYNC_QUESTION_REPLY_TIMEOUT, response)\n            .await\n            .map_err(|_| {\n                state\n                    .processes\n                    .remove_pending_rpc_reply(&entry.run_id, &rpc_id);\n                \"Codex did not acknowledge the question answer; it is still available to retry\"\n                    .to_string()\n            })?\n            .map_err(|_| \"Codex app-server stopped before acknowledging the answer\".to_string())??;\n        if reply.get(\"turnId\").and_then(Value::as_str).is_none() {\n            return Err(\"Codex returned an invalid turn/steer response\".to_string());\n        }\n        if let Ok(mut questions) = entry.questions.lock() {\n            questions.remove(&request_id);\n        }\n        return Ok(());\n    }\n    // codex's app-server driver parks `item/tool/requestUserInput`: same stdin\n    // response, but its answer map is keyed by the question ids the server\n    // issued — the card answers by question text.\n    if let Some(app) = input.get(\"codexApp\") {\n        let frame = codex_app::answer_frame(app, answers.as_ref())?;\n        state\n            .processes\n            .write_line(&session_id, frame.to_string())\n            .await?;\n        if let Ok(mut questions) = entry.questions.lock() {\n            questions.remove(&request_id);\n        }\n        return Ok(());\n    }\n    // pi/omp rpc sessions park the render input plus the dialog method: the\n    // answer is an extension_ui_response frame on the CLI's stdin.\n    if let Some(extui) = input.get(\"extui\") {\n        let method = extui.get(\"method\").and_then(Value::as_str).unwrap_or(\"\");\n        let frame = pi_family::extension_ui_answer_frame(method, &request_id, answers.as_ref());\n        // A failed write must surface: the frontend keeps the card pending on\n        // Err instead of falsely marking the question answered.\n        state\n            .processes\n            .write_line(&session_id, frame.to_string())\n            .await?;\n        if let Ok(mut questions) = entry.questions.lock() {\n            questions.remove(&request_id);\n        }\n        return Ok(());\n    }\n    // opencode attached sessions park an answer context: the reply is an HTTP\n    // POST to the managed server, not a stdin line.\n    if let Some(opencode) = input.get(\"opencode\") {\n        let origin = opencode\n            .get(\"origin\")\n            .and_then(Value::as_str)\n            .ok_or_else(|| \"question answer context is missing the server origin\".to_string())?;\n        let directory = opencode\n            .get(\"directory\")\n            .and_then(Value::as_str)\n            .unwrap_or(\"\");\n        let request_id = opencode\n            .get(\"requestId\")\n            .and_then(Value::as_str)\n            .ok_or_else(|| \"question answer context is missing the request id\".to_string())?;\n        let request = opencode.get(\"request\").cloned().unwrap_or(Value::Null);\n        // 忽略 = reject(工具侧抛 QuestionRejectedError,模型得到「用户拒绝\n        // 回答」并继续);否则 reply,answers 与 questions 同序。\n        let result = match answers.as_ref() {\n            None => {\n                opencode_server::post(\n                    origin,\n                    &format!(\"/question/{request_id}/reject\"),\n                    directory,\n                    None,\n                )\n                .await\n            }\n            Some(answers) => {\n                let answers = opencode_session::reply_answers(&request, answers)\n                    .ok_or_else(|| \"question answer context is malformed\".to_string())?;\n                opencode_server::post(\n                    origin,\n                    &format!(\"/question/{request_id}/reply\"),\n                    directory,\n                    Some(serde_json::json!({ \"answers\": answers })),\n                )\n                .await\n            }\n        };\n        // A failed post must surface: the frontend keeps the card pending on\n        // Err instead of falsely marking the question answered.\n        result?;\n        if let Ok(mut questions) = entry.questions.lock() {\n            questions.remove(request_id);\n        }\n        return Ok(());\n    }\n    // dsh host sessions park an answer context instead of a tool input: the\n    // answer is an HTTP outcome, not a stdin line.\n    if let Some(dsh) = input.get(\"dsh\") {\n        let origin = dsh\n            .get(\"origin\")\n            .and_then(Value::as_str)\n            .ok_or_else(|| \"question answer context is missing the host origin\".to_string())?;\n        let client_id = dsh\n            .get(\"clientId\")\n            .and_then(Value::as_str)\n            .ok_or_else(|| \"question answer context is missing the events client id\".to_string())?;\n        let event_id = dsh\n            .get(\"eventId\")\n            .and_then(Value::as_str)\n            .ok_or_else(|| \"question answer context is missing the event id\".to_string())?;\n        let request = dsh.get(\"request\").cloned().unwrap_or(Value::Null);\n        let outcome = dsh_session::question_outcome(&request, answers.as_ref());\n        // A failed post must surface: the frontend keeps the card pending on\n        // Err instead of falsely marking the question answered.\n        crate::dsh_host::host_call(\n            origin,\n            \"$events/result\",\n            serde_json::json!({\n                \"clientId\": client_id,\n                \"eventId\": event_id,\n                \"outcome\": outcome,\n            }),\n        )\n        .await?;\n        // Delivered: drop the parked copy so the turn-end drain skips it.\n        if let Ok(mut questions) = entry.questions.lock() {\n            questions.remove(&request_id);\n        }\n        return Ok(());\n    }\n    let mut updated = match input {\n        Value::Object(map) => map,\n        // Defensive: a non-object input cannot merge answers; rebuild the\n        // minimal shape the question reader expects.\n        questions => {\n            let mut map = serde_json::Map::new();\n            map.insert(\"questions\".to_string(), questions);\n            map\n        }\n    };\n    if let Some(answers) = answers {\n        updated.insert(\"answers\".to_string(), answers);\n    }\n    let line = serde_json::json!({\n        \"type\": \"control_response\",\n        \"response\": {\n            \"subtype\": \"success\",\n            \"request_id\": request_id,\n            \"response\": { \"behavior\": \"allow\", \"updatedInput\": Value::Object(updated) },\n        },\n    })\n    .to_string();\n    // A failed write must surface: the frontend keeps the card pending on\n    // Err instead of falsely marking the question answered.\n    state.processes.write_line(&session_id, line).await?;\n    // Delivered: drop the parked copy so the EOF drain skips it.\n    if let Ok(mut questions) = entry.questions.lock() {\n        questions.remove(&request_id);\n    }\n    Ok(())\n}\n\n/// respond_plan_review 的结果:决策已生效,或冲突(当前状态原样返回,供\n/// UI 呈现\"已被另一窗口/新版本取代\"而不是重复执行)。重复点击返回相同\n/// 结果或明确冲突——PRD §4.2。\n#[derive(Debug, Clone, Serialize)]\n#[serde(rename_all = \"camelCase\", tag = \"outcome\")]\npub enum PlanRespondOutcome {\n    Applied { review: PlanReview },\n    Conflict { review: PlanReview },\n}\n\n/// 计划审批决策入口。前端只提交 planId + expectedRevision + decision +\n/// 可选反馈;原生回复上下文从不离开后端。流程:\n/// 1. expectedRevision + 状态条件原子抢占(plan_review::submit_decision),\n///    决策意图先落盘;\n/// 2. 按停住的原生上下文构造回复并写出——写管道失败退回待审、意图留存,\n///    批准绝不显示成功;\n/// 3. 原生确认后 mark_applied 落账。写成功 ≠ 远端已执行:失联只能标\n///    unknown 并核对上游,本客户端保证不重复提交同一批准。\n#[tauri::command]\npub async fn respond_plan_review(\n    state: tauri::State<'_, crate::AppState>,\n    plan_id: String,\n    expected_revision: i64,\n    decision: plan_review::PlanDecision,\n    feedback: Option<String>,\n) -> Result<PlanRespondOutcome, String> {\n    let claimed = match plan_review::submit_decision(\n        &state.db,\n        &plan_id,\n        expected_revision,\n        decision,\n        feedback.as_deref(),\n    )? {\n        plan_review::SubmitOutcome::Conflict(review) => {\n            return Ok(PlanRespondOutcome::Conflict { review: *review });\n        }\n        plan_review::SubmitOutcome::Claimed { previous } => previous,\n    };\n    let fail = |message: String| -> Result<PlanRespondOutcome, String> {\n        // 提交权已抢占但路由/写入失败:退回待审,决策意图留存待恢复。\n        plan_review::revert_submission(&state.db, &plan_id, expected_revision, claimed)?;\n        Err(message)\n    };\n    let review = plan_review::get_review(&state.db, &plan_id, expected_revision)?\n        .ok_or_else(|| \"plan review vanished mid-decision\".to_string())?;\n\n    // 暂不执行:任何生命周期都不需要写原生回复;原生等待点保持停着,\n    // 用户可回到同一会话继续审批(deferred 允许再次提交)。\n    if decision == plan_review::PlanDecision::Defer {\n        plan_review::mark_applied(&state.db, &plan_id, expected_revision, decision)?;\n        let review = plan_review::get_review(&state.db, &plan_id, expected_revision)?\n            .ok_or_else(|| \"plan review vanished mid-decision\".to_string())?;\n        return Ok(PlanRespondOutcome::Applied { review });\n    }\n\n    if review.review_kind == plan_review::PlanReviewKind::NextTurn {\n        // next_turn:计划轮次已正常结束,没有停着的原生请求;批准=原子创建\n        // 一次 default 执行 turn,修改=新 plan turn 携反馈。执行器核对线程\n        // 存在且最终 plan item 未变(stale 由其就地 expire)。今天只有 codex\n        // 是 next_turn;其他引擎声明 next_turn 却没有执行器是编程错误,\n        // fail-closed 而不是静默无事发生。\n        if review.engine != \"codex\" {\n            return fail(format!(\n                \"no next_turn plan executor is wired for engine {}\",\n                review.engine\n            ));\n        }\n        if let Err(message) =\n            codex_app::run_plan_decision(&state, &review, decision, feedback.as_deref()).await\n        {\n            return fail(format!(\"plan decision was NOT delivered: {message}\"));\n        }\n        plan_review::mark_applied(&state.db, &plan_id, expected_revision, decision)?;\n        if decision == plan_review::PlanDecision::Approve {\n            // 执行 turn 已被服务端确认创建(原子一次);完成/失败由该 run 的\n            // 后续事件推进,approved ≠ 执行成功。\n            plan_review::mark_execution(\n                &state.db,\n                &plan_id,\n                expected_revision,\n                plan_review::PlanExecution::Starting,\n            )?;\n        }\n        let review = plan_review::get_review(&state.db, &plan_id, expected_revision)?\n            .ok_or_else(|| \"plan review vanished mid-decision\".to_string())?;\n        return Ok(PlanRespondOutcome::Applied { review });\n    }\n\n    // native_request:取出停住的上下文,校验它属于同一版本、正文未变。\n    let session_key = review.run_id.clone().unwrap_or_else(|| review.session_id.clone());\n    let entry = state\n        .processes\n        .get(&session_key)\n        .or_else(|| state.processes.get(&review.session_id))\n        .ok_or_else(|| \"no running session holds this plan's native request\".to_string());\n    let entry = match entry {\n        Ok(entry) => entry,\n        Err(message) => return fail(message),\n    };\n    let parked = entry\n        .plans\n        .lock()\n        .map_err(|_| \"plan state is poisoned\".to_string())\n        .ok()\n        .and_then(|plans| plans.get(&plan_id).cloned());\n    let Some(parked) = parked else {\n        return fail(\"the native plan request is no longer parked for this session\".to_string());\n    };\n    if parked.get(\"revision\").and_then(Value::as_i64) != Some(expected_revision) {\n        return fail(\"the parked native request belongs to a different plan revision\".to_string());\n    }\n    if let Some(hash) = parked.get(\"contentHash\").and_then(Value::as_str) {\n        if hash != review.content_hash {\n            // 正文在审批期间变化:不能让已抢占版本带着旧正文继续执行——\n            // 先失效,要求重新审阅(PR §4.2 末条)。\n            let _ = plan_review::expire_reviews(&state.db, &[(plan_id.clone(), expected_revision)]);\n            return Err(\"plan content changed while awaiting review; the revision was expired\"\n                .to_string());\n        }\n    }\n\n    let frame_key = match decision {\n        plan_review::PlanDecision::Approve => \"approve\",\n        plan_review::PlanDecision::RequestChanges => \"changes\",\n        plan_review::PlanDecision::Defer => unreachable!(\"defer returned above\"),\n    };\n    let frame = parked\n        .get(\"frames\")\n        .and_then(|frames| frames.get(frame_key))\n        .cloned()\n        .ok_or_else(|| {\n            \"the parked native context carries no reply frame for this decision\".to_string()\n        });\n    let frame = match frame {\n        Ok(frame) => frame,\n        Err(message) => return fail(message),\n    };\n    let frame = substitute_plan_feedback(frame, feedback.as_deref());\n\n    let written = match parked.get(\"route\").and_then(Value::as_str) {\n        Some(\"stdin\") => state.processes.write_line(&session_key, frame_to_line(&frame)).await,\n        Some(\"http\") => {\n            let origin = parked.get(\"origin\").and_then(Value::as_str).unwrap_or(\"\");\n            let path = parked.get(\"path\").and_then(Value::as_str).unwrap_or(\"\");\n            if origin.is_empty() || path.is_empty() {\n                Err(\"the parked native context is missing its http origin/path\".to_string())\n            } else {\n                crate::dsh_host::host_call(origin, path, frame).await.map(|_| ())\n            }\n        }\n        _ => Err(\"the parked native context does not declare a reply route\".to_string()),\n    };\n    if let Err(message) = written {\n        return fail(format!(\"plan decision was NOT delivered: {message}\"));\n    }\n\n    plan_review::mark_applied(&state.db, &plan_id, expected_revision, decision)?;\n    if decision == plan_review::PlanDecision::Approve {\n        // 原生确认已收到,实施开始;approved ≠ 执行成功,完成/失败由后续\n        // 运行事件推进。\n        plan_review::mark_execution(\n            &state.db,\n            &plan_id,\n            expected_revision,\n            plan_review::PlanExecution::Starting,\n        )?;\n    }\n    if let Ok(mut plans) = entry.plans.lock() {\n        plans.remove(&plan_id);\n    }\n    let review = plan_review::get_review(&state.db, &plan_id, expected_revision)?\n        .ok_or_else(|| \"plan review vanished mid-decision\".to_string())?;\n    Ok(PlanRespondOutcome::Applied { review })\n}\n\n/// 计划审批历史(重启后历史页加载):按 planId/revision 主键去重,随会话\n/// 删除清理。前端 localStorage 不是审批权威。\n#[tauri::command]\npub async fn list_plan_reviews(\n    state: tauri::State<'_, crate::AppState>,\n    engine: String,\n    session_id: String,\n) -> Result<Vec<PlanReview>, String> {\n    plan_review::list_reviews(&state.db, &engine, &session_id)\n}\n\n/// 反馈文本注入原生回复帧:适配器在停车时把帧里需要携带用户反馈的字符串\n/// 叶子写成该占位符,发送时替换(如 DSH 的 custom 字段)。无占位符的帧原样\n/// 通过;无反馈时占位符替换为空对象 null 语义由适配器决定——DSH 规则是\n/// 反馈答案 selected:[] + custom 文本,批准答案绝不携带 custom。\npub(crate) const PLAN_FEEDBACK_PLACEHOLDER: &str = \"__CCGUI_PLAN_FEEDBACK__\";\nfn substitute_plan_feedback(frame: Value, feedback: Option<&str>) -> Value {\n    match frame {\n        Value::String(text) if text.contains(PLAN_FEEDBACK_PLACEHOLDER) => {\n            Value::String(text.replace(PLAN_FEEDBACK_PLACEHOLDER, feedback.unwrap_or(\"\")))\n        }\n        Value::Array(items) => Value::Array(\n            items\n                .into_iter()\n                .map(|item| substitute_plan_feedback(item, feedback))\n                .collect(),\n        ),\n        Value::Object(map) => Value::Object(\n            map.into_iter()\n                .map(|(key, value)| (key, substitute_plan_feedback(value, feedback)))\n                .collect(),\n        ),\n        other => other,\n    }\n}\nfn frame_to_line(frame: &Value) -> String {\n    match frame {\n        Value::String(text) => text.clone(),\n        other => other.to_string(),\n    }\n}\n#[cfg(test)]\nmod prompt_contribution_tests {\n    use super::*;\n\n    #[test]\n    fn internal_contributions_append_after_the_visible_prompt_in_stable_order() {\n        let prompt = effective_prompt(\n            \"visible\",\n            vec![\n                PromptContribution {\n                    id: \"system\".into(),\n                    content: \"system context\".into(),\n                    placement: PromptPlacement::SystemTail,\n                    visibility: \"internal\".into(),\n                    persistence: \"turn\".into(),\n                },\n                PromptContribution {\n                    id: \"request\".into(),\n                    content: \"request context\".into(),\n                    placement: PromptPlacement::RequestTail,\n                    visibility: \"internal\".into(),\n                    persistence: \"turn\".into(),\n                },\n            ],\n        );\n\n        assert_eq!(\n            prompt,\n            \"visible\\n\\n[CCGUI internal system-tail]\\nsystem context\\n\\n[CCGUI internal request-tail]\\nrequest context\"\n        );\n    }\n}\n\n#[cfg(test)]\nmod codebuddy_launch_tests {\n    use super::*;\n\n    struct ScratchHome {\n        dir: PathBuf,\n        previous_home: Option<std::ffi::OsString>,\n        previous_profile: Option<std::ffi::OsString>,\n        _lock: parking_lot::MutexGuard<'static, ()>,\n    }\n\n    impl ScratchHome {\n        fn new() -> Self {\n            let lock = crate::paths::HOME_ENV_LOCK.lock();\n            let dir = std::env::temp_dir().join(format!(\n                \"ccgui-codebuddy-launch-test-{}\",\n                uuid::Uuid::new_v4()\n            ));\n            std::fs::create_dir_all(&dir).unwrap();\n            let previous_home = std::env::var_os(\"HOME\");\n            let previous_profile = std::env::var_os(\"USERPROFILE\");\n            std::env::set_var(\"HOME\", &dir);\n            std::env::set_var(\"USERPROFILE\", &dir);\n            Self {\n                dir,\n                previous_home,\n                previous_profile,\n                _lock: lock,\n            }\n        }\n    }\n\n    impl Drop for ScratchHome {\n        fn drop(&mut self) {\n            match &self.previous_home {\n                Some(value) => std::env::set_var(\"HOME\", value),\n                None => std::env::remove_var(\"HOME\"),\n            }\n            match &self.previous_profile {\n                Some(value) => std::env::set_var(\"USERPROFILE\", value),\n                None => std::env::remove_var(\"USERPROFILE\"),\n            }\n            let _ = std::fs::remove_dir_all(&self.dir);\n        }\n    }\n\n    #[test]\n    fn channel_model_reaches_overlay_when_request_has_no_model() {\n        let home = ScratchHome::new();\n        let mut config = crate::config::CliConfig::default();\n        let section = config.section_mut(\"codebuddy\").unwrap();\n        section.providers.insert(\n            \"channel\".into(),\n            serde_json::json!({\"model\":\"channel-model\"}),\n        );\n        section.current = Some(\"channel\".into());\n        crate::paths::ensure_dirs().unwrap();\n        crate::settings::atomic_write(\n            &crate::paths::config_path(),\n            &serde_json::to_string(&config).unwrap(),\n        )\n        .unwrap();\n\n        let launch = prepare_launch(\n            \"codebuddy\",\n            home.dir.join(\"workspace\").to_str().unwrap(),\n            None,\n            \"hello\".into(),\n            Vec::new(),\n            None,\n            None,\n            None,\n            None,\n            None,\n            Vec::new(),\n            None,\n            None,\n            None,\n            None,\n            false,\n        )\n        .unwrap();\n        assert_eq!(launch.req.model, None);\n        assert_eq!(launch.built.cleanup_files.len(), 1);\n        let overlay: Value = serde_json::from_slice(\n            &std::fs::read(&launch.built.cleanup_files[0]).unwrap(),\n        )\n        .unwrap();\n        assert_eq!(overlay[\"model\"], \"channel-model\");\n        assert_eq!(overlay[\"env\"][\"CODEBUDDY_MODEL\"], \"channel-model\");\n        cleanup_staged_files(&launch.built.cleanup_files);\n    }\n}\n\n#[cfg(test)]\nmod permission_tests {\n    use super::*;\n\n    #[test]\n    fn list_engines_ipc_runs_off_handler_thread() {\n        let app = tauri::test::mock_builder()\n            .invoke_handler(tauri::generate_handler![list_engines])\n            .build(tauri::test::mock_context(tauri::test::noop_assets()))\n            .unwrap();\n        let window = tauri::WebviewWindowBuilder::new(&app, \"engine-test\", Default::default())\n            .build()\n            .unwrap();\n        let handler_thread = std::thread::current().id();\n        let (sender, receiver) = std::sync::mpsc::channel();\n        let webview: &tauri::Webview<tauri::test::MockRuntime> = window.as_ref();\n        webview.clone().on_message(\n            tauri::webview::InvokeRequest {\n                cmd: \"list_engines\".into(),\n                callback: tauri::ipc::CallbackFn(0),\n                error: tauri::ipc::CallbackFn(1),\n                url: if cfg!(windows) {\n                    \"http://tauri.localhost\"\n                } else {\n                    \"tauri://localhost\"\n                }\n                .parse()\n                .unwrap(),\n                body: tauri::ipc::InvokeBody::default(),\n                headers: Default::default(),\n                invoke_key: tauri::test::INVOKE_KEY.to_string(),\n            },\n            Box::new(move |_, _, response, _, _| {\n                sender\n                    .send((std::thread::current().id(), response))\n                    .unwrap();\n            }),\n        );\n        let (response_thread, response) = receiver\n            .recv_timeout(std::time::Duration::from_secs(10))\n            .unwrap();\n        assert!(matches!(response, tauri::ipc::InvokeResponse::Ok(_)));\n        assert_ne!(\n            handler_thread, response_thread,\n            \"engine detection ran inline on the IPC handler\"\n        );\n    }\n\n    #[test]\n    fn every_registered_engine_has_an_adapter() {\n        for id in crate::config::ENGINES {\n            assert!(engine_by_id(id).is_some(), \"{id}\");\n        }\n    }\n\n    /// 工具白名单是显式能力：只有实现了约束的引擎才允许被任务工作台\n    /// 用于只读节点，其余引擎必须在启动时被拒绝。\n    #[test]\n    fn tool_constraint_support_is_explicit() {\n        assert!(engine_by_id(\"claude\").unwrap().supports_tool_constraints());\n        assert!(engine_by_id(\"pi\").unwrap().supports_tool_constraints());\n        for id in [\"codex\", \"omp\", \"grok\", \"kimi\"] {\n            assert!(\n                !engine_by_id(id).unwrap().supports_tool_constraints(),\n                \"{id}\"\n            );\n        }\n    }\n\n    fn req(permission: Option<&str>) -> SendRequest {\n        SendRequest {\n            session_id: None,\n            workspace: PathBuf::from(\"/tmp\"),\n            prompt: \"hi\".to_string(),\n            prompt_contributions: Vec::new(),\n            native_compact: false,\n            images: Vec::new(),\n            model: None,\n            effort: None,\n            service_tier: None,\n            permission: permission.map(str::to_string),\n            additional_dirs: Vec::new(),\n            provider_id: None,\n            computer_use: None,\n            memory_bot: None,\n            allowed_tools: None,\n        }\n    }\n\n    #[test]\n    fn pi_read_only_launch_disables_all_extensions_on_start_and_resume() {\n        for session_id in [None, Some(\"existing-session\".to_string())] {\n            let mut request = req(None);\n            request.session_id = session_id;\n            request.allowed_tools = Some(vec![\n                \"read\".into(),\n                \"grep\".into(),\n                \"find\".into(),\n                \"ls\".into(),\n            ]);\n            let args = argv(&pi_family::pi(), &request);\n            assert!(args\n                .windows(2)\n                .any(|args| args == [\"--tools\", \"read,grep,find,ls\"]));\n            assert!(args.contains(&\"--no-extensions\".to_string()));\n            assert!(!args.contains(&\"--extension\".to_string()));\n            assert!(!args.contains(&\"--auto-approve\".to_string()));\n        }\n    }\n\n    #[test]\n    fn pi_read_only_rejects_empty_writable_and_custom_tools() {\n        for tools in [\n            vec![],\n            vec![\"\"],\n            vec![\"read\", \"bash\"],\n            vec![\"write\"],\n            vec![\"edit\"],\n            vec![\"custom\"],\n            vec![\"read,bash\"],\n        ] {\n            let mut request = req(None);\n            request.allowed_tools = Some(tools.into_iter().map(str::to_string).collect());\n            assert!(pi_family::pi().build_command(&request, \"pi\").is_err());\n        }\n    }\n\n    #[test]\n    fn pi_read_only_rejects_computer_use_and_omp_constraints() {\n        let mut request = req(None);\n        request.allowed_tools = Some(vec![\"read\".into()]);\n        assert!(pi_family::omp().build_command(&request, \"omp\").is_err());\n        request.computer_use = Some(true);\n        assert!(pi_family::pi().build_command(&request, \"pi\").is_err());\n    }\n\n    #[test]\n    fn pi_read_only_rejects_session_file_destinations() {\n        for session in [\"/tmp/plan.jsonl\", \"relative.jsonl\", \"../plan\", \"C:\\\\plan\"] {\n            let mut request = req(None);\n            request.allowed_tools = Some(vec![\"read\".into()]);\n            request.session_id = Some(session.into());\n            assert!(\n                pi_family::pi().build_command(&request, \"pi\").is_err(),\n                \"{session}\"\n            );\n        }\n    }\n\n    #[test]\n    fn pi_unrestricted_launch_keeps_the_ask_extension() {\n        let args = argv(&pi_family::pi(), &req(None));\n        assert!(args.contains(&\"--extension\".to_string()));\n        assert!(!args.contains(&\"--no-extensions\".to_string()));\n        assert!(!args.contains(&\"--tools\".to_string()));\n    }\n\n    #[test]\n    fn plugin_read_only_is_opt_in_and_fails_closed() {\n        for engine in crate::config::ENGINES {\n            assert_eq!(plugin_agent_tools(engine, None).unwrap(), None);\n            assert_eq!(plugin_agent_tools(engine, Some(false)).unwrap(), None);\n            if !matches!(engine, \"pi\" | \"codex\") {\n                assert!(plugin_agent_tools(engine, Some(true)).is_err(), \"{engine}\");\n            }\n        }\n        assert_eq!(\n            plugin_agent_tools(\"pi\", Some(true)).unwrap(),\n            Some(vec![\n                \"read\".into(),\n                \"grep\".into(),\n                \"find\".into(),\n                \"ls\".into()\n            ])\n        );\n        assert!(plugin_agent_tools(\"unknown\", Some(true)).is_err());\n        assert_eq!(plugin_agent_tools(\"codex\", Some(true)).unwrap(), None);\n    }\n\n    fn argv(engine: &dyn Engine, req: &SendRequest) -> Vec<String> {\n        let built = engine.build_command(req, \"fake-bin\").unwrap();\n        built\n            .command\n            .as_std()\n            .get_args()\n            .map(|a| a.to_string_lossy().to_string())\n            .collect()\n    }\n\n    #[test]\n    fn claude_computer_use_mounts_driver_mcp_and_preapproves_it() {\n        let mut request = req(None);\n        request.computer_use = Some(true);\n        let args = argv(&claude::ClaudeEngine::new(), &request);\n        let at = args\n            .iter()\n            .position(|a| a == \"--mcp-config\")\n            .unwrap_or_else(|| panic!(\"{args:?}\"));\n        let config: Value =\n            serde_json::from_str(&args[at + 1]).expect(\"mcp config must be inline JSON\");\n        let server = &config[\"mcpServers\"][\"ccgui-computer\"];\n        assert_eq!(server[\"args\"], serde_json::json!([]));\n        // The driver is the separate helper binary, never this executable.\n        assert_eq!(\n            std::path::Path::new(server[\"command\"].as_str().unwrap_or_default())\n                .file_stem()\n                .and_then(|s| s.to_str()),\n            Some(crate::computer_use::HELPER_BIN)\n        );\n        // Pre-approved: a click-per-approval loop would be unusable.\n        let tools_at = args\n            .iter()\n            .position(|a| a == \"--allowedTools\")\n            .unwrap_or_else(|| panic!(\"{args:?}\"));\n        assert!(\n            args[tools_at + 1..].contains(&\"mcp__ccgui-computer\".to_string()),\n            \"{args:?}\"\n        );\n        // Off by default: no driver, no pre-approval.\n        let off = argv(&claude::ClaudeEngine::new(), &req(None));\n        assert!(!off.contains(&\"--mcp-config\".to_string()));\n        assert!(!off.contains(&\"mcp__ccgui-computer\".to_string()));\n    }\n\n    #[test]\n    fn claude_memory_mounts_tool_mcp_and_preapproves_it() {\n        let mut request = req(None);\n        request.memory_bot = Some(\"bot-1\".into());\n        let args = argv(&claude::ClaudeEngine::new(), &request);\n        let at = args\n            .iter()\n            .position(|a| a == \"--mcp-config\")\n            .unwrap_or_else(|| panic!(\"{args:?}\"));\n        let config: Value =\n            serde_json::from_str(&args[at + 1]).expect(\"mcp config must be inline JSON\");\n        let server = &config[\"mcpServers\"][\"ccgui-memory\"];\n        assert_eq!(\n            server[\"args\"],\n            serde_json::json!([\"--memory-mcp\", \"--bot-id\", \"bot-1\"])\n        );\n        // 单条 --allowedTools 前缀覆盖该服务器的全部工具。\n        let tools_at = args\n            .iter()\n            .position(|a| a == \"--allowedTools\")\n            .unwrap_or_else(|| panic!(\"{args:?}\"));\n        assert!(\n            args[tools_at + 1..].contains(&\"mcp__ccgui-memory\".to_string()),\n            \"{args:?}\"\n        );\n        // 两个工具同时开启时合并进同一个 --mcp-config。\n        let mut both = request.clone();\n        both.computer_use = Some(true);\n        let args = argv(&claude::ClaudeEngine::new(), &both);\n        assert_eq!(\n            args.iter().filter(|a| *a == \"--mcp-config\").count(),\n            1,\n            \"{args:?}\"\n        );\n        let at = args.iter().position(|a| a == \"--mcp-config\").unwrap();\n        let config: Value = serde_json::from_str(&args[at + 1]).unwrap();\n        assert!(config[\"mcpServers\"][\"ccgui-memory\"].is_object());\n        assert!(config[\"mcpServers\"][\"ccgui-computer\"].is_object());\n        // 默认不挂：也没有任何 mcp__ 前缀被预批准。\n        let off = argv(&claude::ClaudeEngine::new(), &req(None));\n        assert!(!off.contains(&\"--mcp-config\".to_string()));\n        assert!(!off.iter().any(|a| a.starts_with(\"mcp__\")));\n    }\n\n    #[test]\n    fn codex_memory_mounts_tool_mcp_through_process_overrides() {\n        let mut request = req(None);\n        request.memory_bot = Some(\"bot-1\".into());\n        let built = codex::CodexEngine\n            .host_command(&request, \"fake-bin\")\n            .unwrap();\n        let args: Vec<String> = built\n            .command\n            .as_std()\n            .get_args()\n            .map(|a| a.to_string_lossy().to_string())\n            .collect();\n        assert!(\n            args.iter()\n                .any(|a| a.starts_with(\"mcp_servers.ccgui-memory.command=\")),\n            \"{args:?}\"\n        );\n        let args_value = args\n            .iter()\n            .find(|a| a.starts_with(\"mcp_servers.ccgui-memory.args=\"))\n            .unwrap_or_else(|| panic!(\"{args:?}\"));\n        assert!(args_value.contains(\"--memory-mcp\"), \"{args_value}\");\n        assert!(args_value.contains(\"\\\"bot-1\\\"\"), \"{args_value}\");\n        // 默认不挂。\n        let off = codex::CodexEngine.host_command(&req(None), \"fake-bin\").unwrap();\n        assert!(!off.command.as_std().get_args().any(|a| a\n            .to_string_lossy()\n            .contains(\"ccgui-memory\")));\n    }\n\n    #[test]\n    fn engine_info_exposes_computer_use_support_under_its_camel_case_key() {\n        // The composer's /ccgui-cua gate reads `supportsComputerUse` off\n        // list_engines; a rename (or a lost rename_all) would make the field\n        // read undefined and refuse every engine. Pin the wire name.\n        let info = EngineInfo {\n            id: \"claude\".into(),\n            available: true,\n            enabled: true,\n            plan: PlanApproval::Legacy,\n            supports_images: true,\n            supports_computer_use: true,\n            supports_memory: true,\n            supports_effort: true,\n            supports_tool_constraints: false,\n            permissions: vec![\"auto\".into()],\n        };\n        let json = serde_json::to_value(&info).expect(\"EngineInfo serializes\");\n        assert_eq!(json[\"supportsComputerUse\"], serde_json::json!(true));\n        assert_eq!(json[\"supportsMemory\"], serde_json::json!(true));\n        assert!(json.get(\"supports_computer_use\").is_none());\n    }\n\n    #[test]\n    fn pi_prompt_rides_the_rpc_prompt_command() {\n        // pi 也走 rpc 模式(提问桥扩展需要):prompt 是 stdin NDJSON 命令的\n        // message 字段,多行文本不再被 Windows 的 cmd.exe shim 截断。\n        let mut request = req(None);\n        request.prompt = \"first line\\nsecond line\\n%PATH%\".to_string();\n        let built = pi_family::pi().build_command(&request, \"fake-bin\").unwrap();\n        let args: Vec<String> = built\n            .command\n            .as_std()\n            .get_args()\n            .map(|a| a.to_string_lossy().to_string())\n            .collect();\n        assert!(args.windows(2).any(|w| w == [\"--mode\", \"rpc\"]), \"{args:?}\");\n        // The ask bridge extension rides along via --extension.\n        let at = args\n            .iter()\n            .position(|a| a == \"--extension\")\n            .expect(\"{args:?}\");\n        assert!(args[at + 1].ends_with(\"ccgui-ask-bridge.ts\"), \"{args:?}\");\n        assert!(!args.iter().any(|a| a.contains(\"first line\")), \"{args:?}\");\n        let payload = built.stdin_payload.expect(\"rpc prompt must ride stdin\");\n        let mut lines = payload.lines();\n        // pi 只有 v1:没有 negotiate_protocol 前导。\n        let state: Value = serde_json::from_str(lines.next().unwrap()).unwrap();\n        assert_eq!(state[\"type\"], \"get_state\");\n        let prompt: Value = serde_json::from_str(lines.next().unwrap()).unwrap();\n        assert_eq!(prompt[\"type\"], \"prompt\");\n        assert_eq!(prompt[\"message\"], request.prompt);\n        assert!(\n            lines.next().is_none(),\n            \"unexpected extra command: {payload}\"\n        );\n        // 末尾不得自带换行:writer 统一补 `\\n`,自带会在 rpc stdin 上产生\n        // 空行,pi 回一帧 `command:\"parse\"` 失败响应(parse 错误警告横幅)。\n        assert!(\n            !payload.ends_with('\\n'),\n            \"writer appends the terminator: {payload:?}\"\n        );\n        assert!(built.keep_stdin_open);\n    }\n\n    #[test]\n    fn omp_prompt_rides_the_rpc_prompt_command() {\n        // rpc-ui 模式拒绝位置参数与 @file:prompt 是 stdin NDJSON 命令里的\n        // message 字段,图片是命令里的 base64 payload,argv 只带协议 flags。\n        // 图片走 prompt 命令的 base64 字段(load_image 覆盖),这里纯文本即可。\n        let mut request = req(None);\n        request.prompt = \"first line\\nsecond line\".to_string();\n        let built = pi_family::omp()\n            .build_command(&request, \"fake-bin\")\n            .unwrap();\n        let args: Vec<String> = built\n            .command\n            .as_std()\n            .get_args()\n            .map(|a| a.to_string_lossy().to_string())\n            .collect();\n        assert!(\n            args.windows(2).any(|w| w == [\"--mode\", \"rpc-ui\"]),\n            \"{args:?}\"\n        );\n        assert!(!args.contains(&\"--print\".to_string()), \"{args:?}\");\n        assert!(!args.iter().any(|a| a.contains(\"first line\")), \"{args:?}\");\n        let payload = built.stdin_payload.expect(\"rpc prompt must ride stdin\");\n        let mut lines = payload.lines();\n        assert!(lines.next().unwrap().contains(\"negotiate_protocol\"));\n        assert!(lines.next().unwrap().contains(\"get_state\"));\n        let prompt: Value = serde_json::from_str(lines.next().unwrap()).unwrap();\n        assert_eq!(prompt[\"type\"], \"prompt\");\n        assert_eq!(prompt[\"message\"], \"first line\\nsecond line\");\n        assert!(\n            lines.next().is_none(),\n            \"unexpected extra command: {payload}\"\n        );\n        // The question answer frames write back over this same stdin.\n        assert!(built.keep_stdin_open);\n    }\n\n    #[test]\n    fn omp_fast_tier_is_explicit_and_independent_of_effort() {\n        let mut request = req(None);\n        request.model = Some(\"openai-codex/gpt-5.4\".into());\n        request.effort = Some(\"high\".into());\n        for tier in [None, Some(\"priority\"), Some(\"default\")] {\n            request.service_tier = tier.map(str::to_string);\n            let args = argv(&pi_family::omp(), &request);\n            let actual = args\n                .iter()\n                .position(|a| a == \"--service-tier\")\n                .map(|i| args[i + 1].as_str());\n            assert_eq!(actual, tier);\n            assert!(args.windows(2).any(|a| a == [\"--thinking\", \"high\"]));\n        }\n    }\n\n    #[test]\n    fn omp_fast_tier_does_not_leak_to_other_models_or_pi() {\n        let mut request = req(None);\n        request.service_tier = Some(\"priority\".into());\n        for model in [\n            None,\n            Some(\"anthropic/claude\"),\n            Some(\"google/gemini\"),\n            Some(\"gpt-5.4\"),\n            Some(\"openai/\"),\n            Some(\"openai/gpt-5.4\"),\n            Some(\"openai-codex/\"),\n            Some(\"custom/gpt-5.4\"),\n        ] {\n            request.model = model.map(str::to_string);\n            assert!(!argv(&pi_family::omp(), &request)\n                .iter()\n                .any(|a| a == \"--service-tier\"));\n        }\n        request.model = Some(\"openai-codex/gpt-5.4\".into());\n        assert!(!argv(&pi_family::pi(), &request)\n            .iter()\n            .any(|a| a == \"--service-tier\"));\n        assert!(argv(&pi_family::omp(), &request)\n            .iter()\n            .any(|a| a == \"--service-tier\"));\n        request.service_tier = Some(\"invalid\".into());\n        assert!(pi_family::omp()\n            .build_command(&request, \"fake-bin\")\n            .is_err());\n    }\n\n    #[test]\n    fn omp_tier_settings_are_backward_compatible_and_roundtrip() {\n        let mut settings: crate::settings::AppSettings = serde_json::from_str(\"{}\").unwrap();\n        assert_eq!(settings.omp_openai_service_tier, None);\n        for tier in [Some(\"priority\"), Some(\"default\"), None] {\n            settings.omp_openai_service_tier = tier.map(str::to_string);\n            let encoded = serde_json::to_string(&settings).unwrap();\n            let decoded: crate::settings::AppSettings = serde_json::from_str(&encoded).unwrap();\n            assert_eq!(decoded.omp_openai_service_tier.as_deref(), tier);\n        }\n    }\n\n    #[test]\n    fn unsupported_mode_falls_back_to_first_supported() {\n        // codex/omp/dsh 的 typed 计划适配器已接通:plan 不再回退 auto。\n        let codex = codex::CodexEngine;\n        assert_eq!(codex.resolve_permission(Some(\"plan\")), \"plan\");\n        assert_eq!(codex.resolve_permission(Some(\"manual\")), \"manual\");\n        assert_eq!(codex.resolve_permission(None), \"auto\");\n        assert_eq!(pi_family::omp().resolve_permission(Some(\"plan\")), \"plan\");\n        assert_eq!(dsh::DshEngine.resolve_permission(Some(\"plan\")), \"plan\");\n        // 未接通引擎保持回退(门禁 ensure_plan_approval 先拒绝显式 plan,\n        // 回退只是防御层)。\n        assert_eq!(pi_family::pi().resolve_permission(Some(\"plan\")), \"auto\");\n        let grok = grok::GrokEngine;\n        assert_eq!(grok.resolve_permission(Some(\"auto\")), \"bypass\");\n        assert_eq!(grok.resolve_permission(Some(\"plan\")), \"bypass\");\n    }\n\n    #[test]\n    fn claude_maps_modes_to_permission_flags() {\n        let e = claude::ClaudeEngine::new();\n        let auto = argv(&e, &req(Some(\"auto\")));\n        assert!(auto.contains(&\"--permission-mode\".to_string()));\n        assert!(auto.contains(&\"acceptEdits\".to_string()));\n        assert!(!auto.contains(&\"--dangerously-skip-permissions\".to_string()));\n        // Headless cannot prompt: auto pre-approves the read-only network\n        // tools acceptEdits does not cover, or every web call is denied.\n        assert!(auto\n            .windows(3)\n            .any(|w| w == [\"--allowedTools\", \"WebSearch\", \"WebFetch\"]));\n\n        let manual = argv(&e, &req(Some(\"manual\")));\n        assert!(manual.contains(&\"default\".to_string()));\n        assert!(!manual.contains(&\"--allowedTools\".to_string()));\n\n        let plan = argv(&e, &req(Some(\"plan\")));\n        assert!(plan.contains(&\"plan\".to_string()));\n\n        let bypass = argv(&e, &req(Some(\"bypass\")));\n        assert!(bypass.contains(&\"--dangerously-skip-permissions\".to_string()));\n        assert!(!bypass.contains(&\"--permission-mode\".to_string()));\n    }\n\n    #[test]\n    fn codex_maps_modes_to_sandbox_flags() {\n        let e = codex::CodexEngine;\n        let auto = argv(&e, &req(Some(\"auto\")));\n        assert!(auto.contains(&\"sandbox_mode=\\\"workspace-write\\\"\".to_string()));\n        assert!(!auto.contains(&\"--dangerously-bypass-approvals-and-sandbox\".to_string()));\n\n        let manual = argv(&e, &req(Some(\"manual\")));\n        assert!(manual.contains(&\"sandbox_mode=\\\"read-only\\\"\".to_string()));\n\n        let bypass = argv(&e, &req(Some(\"bypass\")));\n        assert!(bypass.contains(&\"--dangerously-bypass-approvals-and-sandbox\".to_string()));\n    }\n\n    #[test]\n    fn codex_resume_avoids_unsupported_sandbox_flag() {\n        // `codex exec resume` rejects --sandbox (clap exit 2); the sandbox must\n        // travel via -c sandbox_mode on both fresh and resumed sessions.\n        let e = codex::CodexEngine;\n        let mut resume = req(Some(\"manual\"));\n        resume.session_id = Some(\"00000000-0000-0000-0000-000000000000\".to_string());\n        let args = argv(&e, &resume);\n        assert!(args.contains(&\"resume\".to_string()));\n        assert!(!args.contains(&\"--sandbox\".to_string()));\n        assert!(args.contains(&\"sandbox_mode=\\\"read-only\\\"\".to_string()));\n\n        let fresh = argv(&e, &req(Some(\"auto\")));\n        assert!(!fresh.contains(&\"--sandbox\".to_string()));\n        assert!(fresh.contains(&\"sandbox_mode=\\\"workspace-write\\\"\".to_string()));\n    }\n\n    #[test]\n    fn codex_prompt_goes_through_stdin_not_argv() {\n        // Windows resolves npm codex to a `.cmd` shim spawned via `cmd /c`;\n        // cmd.exe cuts a multiline argument at the first newline, so only line\n        // 1 ever reached the model. The prompt must ride stdin (`-`) verbatim.\n        let e = codex::CodexEngine;\n        let mut request = req(Some(\"auto\"));\n        request.prompt = \"first line\\nmodel = \\\"gpt-5\\\"\\n%PATH%\".to_string();\n        let built = e.build_command(&request, \"fake-bin\").unwrap();\n        let args: Vec<String> = built\n            .command\n            .as_std()\n            .get_args()\n            .map(|a| a.to_string_lossy().to_string())\n            .collect();\n        assert!(args.contains(&\"-\".to_string()));\n        assert!(!args.iter().any(|a| a.contains(\"first line\")));\n        assert_eq!(\n            built.stdin_payload.as_deref(),\n            Some(request.prompt.as_str())\n        );\n\n        let mut resume = req(Some(\"auto\"));\n        resume.session_id = Some(\"00000000-0000-0000-0000-000000000000\".to_string());\n        let built = e.build_command(&resume, \"fake-bin\").unwrap();\n        let args: Vec<String> = built\n            .command\n            .as_std()\n            .get_args()\n            .map(|a| a.to_string_lossy().to_string())\n            .collect();\n        assert!(args.contains(&\"-\".to_string()));\n        assert_eq!(built.stdin_payload.as_deref(), Some(\"hi\"));\n    }\n\n    #[test]\n    fn kimi_prompt_mode_never_combines_interactive_permission_flags() {\n        let e = kimi::KimiEngine;\n        let auto = argv(&e, &req(Some(\"auto\")));\n        assert!(!auto.contains(&\"--yolo\".to_string()));\n        assert!(!auto.contains(&\"--plan\".to_string()));\n\n        assert!(e.build_command(&req(Some(\"plan\")), \"kimi\").is_err());\n\n        let bypass = argv(&e, &req(Some(\"bypass\")));\n        assert!(!bypass.contains(&\"--yolo\".to_string()));\n        assert!(!bypass.contains(&\"--auto\".to_string()));\n\n        // Manual is unsupported: falls back to auto (no flags).\n        let manual = argv(&e, &req(Some(\"manual\")));\n        assert!(!manual.contains(&\"--yolo\".to_string()));\n        assert!(!manual.contains(&\"--plan\".to_string()));\n    }\n\n    #[test]\n    fn plan_capability_matrix_matches_the_adapter_evidence() {\n        // 能力矩阵(验收规格 §2 末行断言的新形态):适配器已接通的引擎声明\n        // Typed(reviewKind 与协议生命周期一致),门禁放行 plan;未接通的\n        // 保持 fail-closed,显式 plan 请求在构建命令与 spawn 之前受控拒绝,\n        // 禁止降级 auto/bypass。各引擎适配器的细节断言(命令行/帧/正文)\n        // 在各自模块的测试里,这里只锁矩阵与门禁。\n        let typed: Vec<(Box<dyn Engine>, plan_review::PlanReviewKind)> = vec![\n            (\n                Box::new(pi_family::omp()),\n                plan_review::PlanReviewKind::NativeRequest,\n            ),\n            (\n                Box::new(codex::CodexEngine),\n                plan_review::PlanReviewKind::NextTurn,\n            ),\n            (\n                Box::new(dsh::DshEngine),\n                plan_review::PlanReviewKind::NativeRequest,\n            ),\n        ];\n        for (engine, kind) in typed {\n            let id = engine.id().to_string();\n            match engine.plan_approval() {\n                PlanApproval::Typed { review_kind, .. } => assert_eq!(review_kind, kind, \"{id}\"),\n                other => panic!(\"{id} must be Typed, got {other:?}\"),\n            }\n            assert!(\n                engine.supported_permissions().contains(&\"plan\"),\n                \"{id} picker must offer plan\"\n            );\n            assert!(\n                ensure_plan_approval(&id, engine.as_ref(), Some(\"plan\")).is_ok(),\n                \"{id} plan request must pass the gate\"\n            );\n            assert!(ensure_plan_approval(&id, engine.as_ref(), Some(\"auto\")).is_ok());\n        }\n\n        let unavailable: Vec<Box<dyn Engine>> = vec![\n            Box::new(pi_family::pi()),\n            Box::new(grok::GrokEngine),\n            Box::new(qoder::QoderEngine::new(qoder::QoderDistribution::Global)),\n            Box::new(qoder::QoderEngine::new(qoder::QoderDistribution::Cn)),\n        ];\n        for engine in unavailable {\n            let id = engine.id().to_string();\n            assert!(\n                matches!(engine.plan_approval(), PlanApproval::Unavailable { .. }),\n                \"{id} must stay fail-closed until its adapter is proven\"\n            );\n            assert!(\n                !engine.supported_permissions().contains(&\"plan\"),\n                \"{id} picker must not offer plan\"\n            );\n            let refusal = ensure_plan_approval(&id, engine.as_ref(), Some(\"plan\"));\n            let Err(message) = refusal else {\n                panic!(\"{id} plan request must be refused before spawn\");\n            };\n            assert!(message.contains(\"cannot run a human-approved plan\"), \"{message}\");\n            assert!(ensure_plan_approval(&id, engine.as_ref(), Some(\"auto\")).is_ok());\n        }\n\n        // omp 计划会话的真实入口是 ACP 传输(--mode acp),不是自动批准的\n        // --plan-yolo;细节断言见 pi_family::tests。\n        let mut plan_req = req(Some(\"plan\"));\n        plan_req.model = Some(\"openai-codex/gpt-5.4\".into());\n        let plan = argv(&pi_family::omp(), &plan_req);\n        assert!(plan.contains(&\"--mode\".to_string()));\n        assert!(!plan.contains(&\"--plan-yolo\".to_string()));\n        assert!(!plan.contains(&\"--plan-yolo-into\".to_string()));\n        assert!(!plan.contains(&\"--auto-approve\".to_string()));\n\n        // auto/bypass 路径不受计划门禁影响:模型原样传递,不强制降级。\n        let mut auto_req = req(Some(\"auto\"));\n        auto_req.model = Some(\"openai-codex/gpt-5.4\".into());\n        let auto = argv(&pi_family::omp(), &auto_req);\n        let pin = auto.iter().position(|a| a == \"--model\").expect(\"model flag\");\n        assert_eq!(auto[pin + 1], \"openai-codex/gpt-5.4\");\n        assert!(!auto.contains(&\"--auto-approve\".to_string()));\n        let bypass = argv(&pi_family::omp(), &req(Some(\"bypass\")));\n        assert!(bypass.contains(&\"--auto-approve\".to_string()));\n        assert!(!bypass.contains(&\"--plan-yolo\".to_string()));\n\n        // pi never receives approval flags either, whatever it is asked for.\n        for mode in [Some(\"plan\"), Some(\"bypass\"), Some(\"manual\")] {\n            let args = argv(&pi_family::pi(), &req(mode));\n            assert!(!args.contains(&\"--plan-yolo\".to_string()), \"{args:?}\");\n            assert!(!args.contains(&\"--auto-approve\".to_string()), \"{args:?}\");\n        }\n    }\n\n    #[test]\n    fn claude_passes_granted_dirs_as_add_dir() {\n        let e = claude::ClaudeEngine::new();\n        let mut r = req(Some(\"auto\"));\n        // Workspace itself, blanks and duplicates must not reach argv.\n        r.additional_dirs = vec![\n            \"/data/shared\".to_string(),\n            \"/tmp\".to_string(),\n            \"   \".to_string(),\n            \"/data/shared\".to_string(),\n        ];\n        let args = argv(&e, &r);\n        let pairs: Vec<&[String]> = args.windows(2).filter(|w| w[0] == \"--add-dir\").collect();\n        assert_eq!(pairs.len(), 1, \"{args:?}\");\n        assert_eq!(pairs[0][1], \"/data/shared\");\n\n        // Other engines have no equivalent flag: the field stays inert.\n        let codex_args = argv(&codex::CodexEngine, &r);\n        assert!(!codex_args.iter().any(|a| a == \"--add-dir\"));\n    }\n\n    #[test]\n    fn grok_always_approves_regardless_of_request() {\n        let e = grok::GrokEngine;\n        for mode in [\n            Some(\"auto\"),\n            Some(\"manual\"),\n            Some(\"plan\"),\n            Some(\"bypass\"),\n            None,\n        ] {\n            assert!(argv(&e, &req(mode)).contains(&\"--always-approve\".to_string()));\n        }\n    }\n}\n#[cfg(test)]\nmod retry_lifecycle_tests {\n    use super::*;\n\n    #[derive(Default)]\n    struct CollectingEmitter(Mutex<Vec<Value>>);\n\n    impl event_sink::Emit for CollectingEmitter {\n        fn emit_json(&self, _name: &str, raw_json: &str) {\n            self.0\n                .lock()\n                .unwrap()\n                .extend(serde_json::from_str::<Vec<Value>>(raw_json).unwrap());\n        }\n    }\n\n    fn test_followup_prefs() -> registry::FollowupPrefs {\n        registry::FollowupPrefs {\n            model: None,\n            effort: None,\n            permission: None,\n            provider_id: None,\n            memory_bot: None,\n            allowed_tools: None,\n            computer_use: false,\n        }\n    }\n\n    /// Done with a background task pending settles the turn but parks the run\n    /// as idle-for-follow-up; the follow-up's first content reopens it, and a\n    /// done with nothing pending closes it for good.\n    #[tokio::test]\n    async fn done_with_pending_background_task_parks_and_resumes_the_run() {\n        let emitter = Arc::new(CollectingEmitter::default());\n        let registry = Arc::new(ProcessRegistry::default());\n        let core = TurnCore {\n            sink: event_sink::EventSink::new(emitter.clone()),\n            registry: Arc::clone(&registry),\n            engine_id: \"claude\".to_string(),\n            run_id: \"bg-run\".to_string(),\n            db: None,\n            followup: Some(test_followup_prefs()),\n        };\n        let mut state = TurnState::new(Some(\"s-1\".to_string()));\n        let done = || EngineEvent::Done {\n            session_id: None,\n            usage: None,\n        };\n\n        core.dispatch_event(&mut state, EngineEvent::BackgroundTasks { pending: 1 });\n        core.dispatch_event(&mut state, done());\n        assert!(!state.saw_done, \"the run must stay open for the follow-up turn\");\n        assert_eq!(\n            registry.take_awaiting_followup(\"s-1\").map(|a| a.run_id).as_deref(),\n            Some(\"bg-run\")\n        );\n        registry.set_awaiting_followup(\"s-1\", \"bg-run\", test_followup_prefs());\n\n        core.dispatch_event(&mut state, EngineEvent::BackgroundTasks { pending: 0 });\n        core.dispatch_event(&mut state, EngineEvent::Delta(\"later\".to_string()));\n        assert!(registry.take_awaiting_followup(\"s-1\").is_none(), \"resumed run is no longer idle\");\n\n        core.dispatch_event(&mut state, done());\n        assert!(state.saw_done);\n        core.sink.flush();\n        let kinds: Vec<_> = emitter\n            .0\n            .lock()\n            .unwrap()\n            .iter()\n            .map(|event| event[\"kind\"].as_str().unwrap().to_string())\n            .collect();\n        assert_eq!(kinds, [\"done\", \"turn_resumed\", \"delta\", \"done\"]);\n    }\n\n    #[tokio::test]\n    async fn terminal_error_cannot_be_followed_by_live_retry_events() {\n        let emitter = Arc::new(CollectingEmitter::default());\n        let core = TurnCore {\n            sink: event_sink::EventSink::new(emitter.clone()),\n            registry: Arc::new(ProcessRegistry::default()),\n            engine_id: \"omp\".to_string(),\n            run_id: \"settled-run\".to_string(),\n            db: None,\n            followup: None,\n        };\n        let mut state = TurnState::new(Some(\"session\".to_string()));\n        for event in [\n            EngineEvent::Error(\"retry exhausted\".to_string()),\n            EngineEvent::Retry {\n                attempt: 1,\n                max: 50,\n                message: \"socket closed\".to_string(),\n            },\n            EngineEvent::Warn(\"late request error\".to_string()),\n            EngineEvent::Done {\n                session_id: None,\n                usage: None,\n            },\n        ] {\n            core.dispatch_event(&mut state, event);\n        }\n        core.sink.flush();\n        let events = emitter.0.lock().unwrap();\n        let kinds: Vec<_> = events\n            .iter()\n            .map(|event| event[\"kind\"].as_str().unwrap())\n            .collect();\n        assert_eq!(kinds, [\"error\"], \"a settled run must not send live events\");\n    }\n\n    async fn replay_cli_output(lines: &[Value]) -> Vec<Value> {\n        replay_engine_output(\"omp\", Box::new(pi_family::omp()), lines).await\n    }\n\n    async fn replay_engine_output(\n        engine_id: &str,\n        engine_impl: Box<dyn Engine>,\n        lines: &[Value],\n    ) -> Vec<Value> {\n        let path = std::env::temp_dir().join(format!(\"ccgui-retry-{}.jsonl\", uuid::Uuid::new_v4()));\n        let mut text = lines\n            .iter()\n            .map(Value::to_string)\n            .collect::<Vec<_>>()\n            .join(\"\\n\");\n        text.push('\\n');\n        std::fs::write(&path, text).unwrap();\n        let mut command = tokio::process::Command::new(if cfg!(windows) { \"cmd\" } else { \"cat\" });\n        if cfg!(windows) {\n            command.args([\"/d\", \"/c\", \"type\"]);\n        }\n        let mut child = command\n            .arg(&path)\n            .stdout(std::process::Stdio::piped())\n            .stderr(std::process::Stdio::null())\n            .spawn()\n            .unwrap();\n        let stdout = child.stdout.take().unwrap();\n        let emitter = Arc::new(CollectingEmitter::default());\n        let ctx = RunContext {\n            core: TurnCore {\n                sink: event_sink::EventSink::new(emitter.clone()),\n                registry: Arc::new(ProcessRegistry::default()),\n                engine_id: engine_id.to_string(),\n                run_id: \"pipe-retry-run\".to_string(),\n                db: None,\n                // Chat-eligible so claude replays exercise follow-up parking.\n                followup: Some(test_followup_prefs()),\n            },\n            engine_impl,\n            pid: child.id().unwrap(),\n            preassigned_session_id: Some(\"session\".to_string()),\n            initial_model: None,\n            comparison_model: None,\n            initial_effort: None,\n            child: Arc::new(TokioMutex::new(child)),\n            killed: Arc::new(std::sync::atomic::AtomicBool::new(false)),\n            cleanup_files: vec![path],\n            mcp_restore: None,\n            stderr_buf: Arc::new(Mutex::new(String::new())),\n            stdout_plain_buf: Arc::new(Mutex::new(String::new())),\n            // Windows-only guard field the production constructor fills; this\n            // test spawns a plain child, so there is no job object to hold.\n            #[cfg(windows)]\n            _tree_guard: None,\n        };\n        run_reader(stdout, ctx).await;\n        let events = std::mem::take(&mut *emitter.0.lock().unwrap());\n        events\n    }\n\n    /// Old CLIs print startup failures (usage/config errors, node crashes)\n    /// to stdout as plain text: parse_line drops non-JSON lines, so the\n    /// settle path must fall back to the captured plain tail when stderr\n    /// is empty — otherwise the banner is a bare exit code.\n    #[tokio::test]\n    async fn plain_stdout_tail_surfaces_on_failed_exit_without_stderr() {\n        let mut command = tokio::process::Command::new(if cfg!(windows) { \"cmd\" } else { \"sh\" });\n        if cfg!(windows) {\n            command.args([\"/c\", \"echo error: unrecognized arguments: --json & exit 1\"]);\n        } else {\n            command.args([\"-c\", \"echo 'error: unrecognized arguments: --json'; exit 1\"]);\n        }\n        let mut child = command\n            .stdin(std::process::Stdio::null())\n            .stdout(std::process::Stdio::piped())\n            .stderr(std::process::Stdio::null())\n            .spawn()\n            .unwrap();\n        let stdout = child.stdout.take().unwrap();\n        let emitter = Arc::new(CollectingEmitter::default());\n        let ctx = RunContext {\n            core: TurnCore {\n                sink: event_sink::EventSink::new(emitter.clone()),\n                registry: Arc::new(ProcessRegistry::default()),\n                engine_id: \"codex\".to_string(),\n                run_id: \"plain-stdout-run\".to_string(),\n                db: None,\n                followup: None,\n            },\n            engine_impl: Box::new(codex::CodexEngine),\n            pid: child.id().unwrap(),\n            preassigned_session_id: None,\n            initial_model: None,\n            comparison_model: None,\n            initial_effort: None,\n            child: Arc::new(TokioMutex::new(child)),\n            killed: Arc::new(std::sync::atomic::AtomicBool::new(false)),\n            cleanup_files: Vec::new(),\n            mcp_restore: None,\n            stderr_buf: Arc::new(Mutex::new(String::new())),\n            stdout_plain_buf: Arc::new(Mutex::new(String::new())),\n            // See the pipe-retry constructor above.\n            #[cfg(windows)]\n            _tree_guard: None,\n        };\n        run_reader(stdout, ctx).await;\n        let events = std::mem::take(&mut *emitter.0.lock().unwrap());\n        let last = events.last().unwrap();\n        assert_eq!(last[\"kind\"], \"error\");\n        let data = last[\"data\"].as_str().unwrap();\n        assert!(data.contains(\"codex exited with status\"), \"{data}\");\n        assert!(data.contains(\"unrecognized arguments\"), \"{data}\");\n    }\n\n    fn claude_text_delta(text: &str) -> Value {\n        serde_json::json!({\"type\":\"stream_event\",\"event\":{\n            \"type\":\"content_block_delta\",\"index\":0,\n            \"delta\":{\"type\":\"text_delta\",\"text\":text}}})\n    }\n\n    fn claude_result() -> Value {\n        serde_json::json!({\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\n            \"usage\":{\"input_tokens\":10,\"output_tokens\":1,\"total_tokens\":11}})\n    }\n\n    fn claude_tasks_changed(task_ids: &[&str]) -> Value {\n        let tasks: Vec<Value> = task_ids\n            .iter()\n            .map(|id| serde_json::json!({\"task_id\":id,\"task_type\":\"local_bash\"}))\n            .collect();\n        serde_json::json!({\"type\":\"system\",\"subtype\":\"background_tasks_changed\",\"tasks\":tasks})\n    }\n\n    /// Event order captured from the real CLI (`run_in_background` Bash):\n    /// result #1 lands while the task still runs, the CLI then starts a\n    /// second turn on its own when the task completes and reports there.\n    #[tokio::test]\n    async fn claude_background_task_followup_turn_is_not_dropped() {\n        let events = replay_engine_output(\n            \"claude\",\n            Box::new(claude::ClaudeEngine::new()),\n            &[\n                serde_json::json!({\"type\":\"system\",\"subtype\":\"init\"}),\n                claude_tasks_changed(&[\"bg1\"]),\n                serde_json::json!({\"type\":\"system\",\"subtype\":\"task_started\",\"task_id\":\"bg1\"}),\n                claude_text_delta(\"started\"),\n                claude_result(),\n                serde_json::json!({\"type\":\"system\",\"subtype\":\"task_notification\",\"task_id\":\"bg1\",\"status\":\"completed\"}),\n                claude_tasks_changed(&[]),\n                serde_json::json!({\"type\":\"system\",\"subtype\":\"init\"}),\n                claude_text_delta(\"background task finished\"),\n                claude_result(),\n            ],\n        )\n        .await;\n        let kinds: Vec<_> = events\n            .iter()\n            .map(|event| event[\"kind\"].as_str().unwrap())\n            .collect();\n        assert_eq!(\n            kinds,\n            [\"delta\", \"done\", \"turn_resumed\", \"delta\", \"done\"],\n            \"{events:?}\"\n        );\n        assert_eq!(events[3][\"data\"], \"background task finished\");\n    }\n\n    /// Raw stream captured from the real CLI (`run_in_background` Bash,\n    /// `sleep 8`): the first result fires while the task runs, the follow-up\n    /// turn arrives after `task_notification` and must reach the user.\n    #[tokio::test]\n    async fn claude_real_cli_background_capture_delivers_followup_text() {\n        let lines: Vec<Value> = include_str!(\"testdata/claude_background_task.jsonl\")\n            .lines()\n            .map(|line| serde_json::from_str(line).unwrap())\n            .collect();\n        let events =\n            replay_engine_output(\"claude\", Box::new(claude::ClaudeEngine::new()), &lines).await;\n        let kinds: Vec<_> = events\n            .iter()\n            .map(|event| event[\"kind\"].as_str().unwrap())\n            .collect();\n        assert_eq!(\n            kinds.iter().filter(|kind| **kind == \"done\").count(),\n            2,\n            \"{events:?}\"\n        );\n        assert_eq!(\n            kinds.iter().filter(|kind| **kind == \"turn_resumed\").count(),\n            1,\n            \"{events:?}\"\n        );\n        assert_eq!(kinds.last(), Some(&\"done\"), \"{events:?}\");\n        let first_done = kinds.iter().position(|kind| *kind == \"done\").unwrap();\n        let resumed = kinds\n            .iter()\n            .position(|kind| *kind == \"turn_resumed\")\n            .unwrap();\n        assert!(first_done < resumed, \"{events:?}\");\n        let text: String = events\n            .iter()\n            .filter(|event| event[\"kind\"] == \"delta\")\n            .filter_map(|event| event[\"data\"].as_str())\n            .collect();\n        assert!(\n            text.contains(\"BGFINISHED\"),\n            \"follow-up turn text lost: {text:?}\"\n        );\n    }\n\n    /// Raw stream captured from a real `--resume` process started while a\n    /// background task of the previous process was still pending: the CLI\n    /// stops that task and emits an empty `num_turns: 0` result before it\n    /// answers the new message. That result is not the end of the user's turn.\n    #[tokio::test]\n    async fn claude_resume_after_background_task_keeps_the_reply() {\n        let lines: Vec<Value> = include_str!(\"testdata/claude_resume_after_background.jsonl\")\n            .lines()\n            .map(|line| serde_json::from_str(line).unwrap())\n            .collect();\n        let events =\n            replay_engine_output(\"claude\", Box::new(claude::ClaudeEngine::new()), &lines).await;\n        let kinds: Vec<_> = events\n            .iter()\n            .map(|event| event[\"kind\"].as_str().unwrap())\n            .collect();\n        let text: String = events\n            .iter()\n            .filter(|event| event[\"kind\"] == \"delta\")\n            .filter_map(|event| event[\"data\"].as_str())\n            .collect();\n        assert_eq!(text, \"PONG2\", \"{events:?}\");\n        assert_eq!(\n            kinds.iter().filter(|kind| **kind == \"done\").count(),\n            1,\n            \"{events:?}\"\n        );\n        assert_eq!(kinds.last(), Some(&\"done\"), \"{events:?}\");\n    }\n\n    /// Raw stream captured from one real process that got a second user\n    /// message while its background task was still running: both replies\n    /// arrive in order, the task is never stopped, and the run is reopened for\n    /// each turn that follows a settled one.\n    #[tokio::test]\n    async fn claude_message_during_background_task_gets_its_own_reply() {\n        let lines: Vec<Value> = include_str!(\"testdata/claude_message_during_background.jsonl\")\n            .lines()\n            .map(|line| serde_json::from_str(line).unwrap())\n            .collect();\n        let events =\n            replay_engine_output(\"claude\", Box::new(claude::ClaudeEngine::new()), &lines).await;\n        let kinds: Vec<_> = events\n            .iter()\n            .map(|event| event[\"kind\"].as_str().unwrap())\n            .collect();\n        let replies: Vec<String> = events\n            .iter()\n            .fold(vec![String::new()], |mut replies, event| {\n                match event[\"kind\"].as_str().unwrap() {\n                    \"delta\" => replies\n                        .last_mut()\n                        .unwrap()\n                        .push_str(event[\"data\"].as_str().unwrap()),\n                    \"done\" => replies.push(String::new()),\n                    _ => {}\n                }\n                replies\n            })\n            .into_iter()\n            .filter(|reply| !reply.is_empty())\n            .collect();\n        assert_eq!(replies, [\"started\", \"PONG2\", \"BGFINISHED\"], \"{events:?}\");\n        assert_eq!(\n            kinds.iter().filter(|kind| **kind == \"done\").count(),\n            3,\n            \"{events:?}\"\n        );\n        assert_eq!(\n            kinds.iter().filter(|kind| **kind == \"turn_resumed\").count(),\n            2,\n            \"{events:?}\"\n        );\n        assert_eq!(kinds.last(), Some(&\"done\"), \"{events:?}\");\n    }\n\n    async fn idle_followup_child(\n        registry: &Arc<ProcessRegistry>,\n        run_id: &str,\n        session_id: &str,\n    ) -> tokio::process::Child {\n        idle_followup_child_with(registry, run_id, session_id, test_followup_prefs()).await\n    }\n\n    async fn idle_followup_child_with(\n        registry: &Arc<ProcessRegistry>,\n        run_id: &str,\n        session_id: &str,\n        prefs: registry::FollowupPrefs,\n    ) -> tokio::process::Child {\n        let mut command = if cfg!(windows) {\n            tokio::process::Command::new(\"sort\")\n        } else {\n            tokio::process::Command::new(\"cat\")\n        };\n        let mut child = command\n            .stdin(std::process::Stdio::piped())\n            .stdout(std::process::Stdio::piped())\n            .stderr(std::process::Stdio::null())\n            .spawn()\n            .unwrap();\n        let stdin = Arc::new(TokioMutex::new(child.stdin.take()));\n        registry.insert(\n            run_id.to_string(),\n            ChildEntry {\n                child: None,\n                pid: child.id().unwrap(),\n                run_id: run_id.to_string(),\n                killed: Arc::new(std::sync::atomic::AtomicBool::new(false)),\n                reader_abort: Arc::new(std::sync::OnceLock::new()),\n                stdin: Some(stdin),\n                questions: Arc::new(Mutex::new(HashMap::new())),\n                plans: Arc::new(Mutex::new(HashMap::new())),\n            },\n        );\n        registry.set_awaiting_followup(session_id, run_id, prefs);\n        child\n    }\n\n    /// A send on a session whose process idles for a background follow-up goes\n    /// into that live process under its own run id, so the task keeps running.\n    #[tokio::test]\n    async fn send_during_idle_followup_is_written_to_the_live_process() {\n        use tokio::io::AsyncReadExt;\n        let registry = Arc::new(ProcessRegistry::default());\n        let mut child = idle_followup_child(&registry, \"idle-run\", \"s-1\").await;\n\n        let delivered =\n            deliver_to_idle_followup(&registry, Some(\"s-1\"), &test_followup_prefs(), || {\n                Ok(\"{\\\"type\\\":\\\"user\\\"}\".to_string())\n            })\n            .await\n            .unwrap();\n        assert_eq!(delivered.as_deref(), Some(\"idle-run\"));\n\n        // EOF the process's stdin so it flushes what it received.\n        registry\n            .get(\"idle-run\")\n            .and_then(|entry| entry.stdin)\n            .unwrap()\n            .lock()\n            .await\n            .take();\n        let mut echoed = String::new();\n        let read = tokio::time::timeout(\n            std::time::Duration::from_secs(20),\n            child.stdout.take().unwrap().read_to_string(&mut echoed),\n        )\n        .await;\n        let _ = child.kill().await;\n        read.expect(\"process echoed its stdin before the timeout\")\n            .unwrap();\n        assert_eq!(echoed.trim(), \"{\\\"type\\\":\\\"user\\\"}\");\n    }\n\n    /// No idle process, or one that can no longer take input, falls back to\n    /// the normal launch; the unwritable one is left unregistered as idle.\n    #[tokio::test]\n    async fn send_without_a_writable_idle_process_falls_back_to_launch() {\n        let registry = Arc::new(ProcessRegistry::default());\n        let make = || Ok(\"{}\".to_string());\n        assert_eq!(\n            deliver_to_idle_followup(&registry, Some(\"s-1\"), &test_followup_prefs(), make)\n                .await\n                .unwrap(),\n            None\n        );\n        assert_eq!(\n            deliver_to_idle_followup(&registry, None, &test_followup_prefs(), make)\n                .await\n                .unwrap(),\n            None\n        );\n\n        let mut child = idle_followup_child(&registry, \"idle-run\", \"s-2\").await;\n        registry\n            .get(\"idle-run\")\n            .and_then(|entry| entry.stdin)\n            .unwrap()\n            .lock()\n            .await\n            .take();\n        assert_eq!(\n            deliver_to_idle_followup(&registry, Some(\"s-2\"), &test_followup_prefs(), make)\n                .await\n                .unwrap(),\n            None\n        );\n        assert!(registry.take_awaiting_followup(\"s-2\").is_none());\n        let _ = child.kill().await;\n    }\n\n    /// A live process cannot take new launch flags: a send whose model (or\n    /// any launch setting) drifted from the parked run's falls back to a\n    /// fresh process, and the idle one is killed so the resume cannot race\n    /// it on the same session. The message closure must not even run.\n    #[tokio::test]\n    async fn send_with_drifted_settings_kills_the_idle_process_and_falls_back() {\n        let registry = Arc::new(ProcessRegistry::default());\n        let mut child = idle_followup_child(&registry, \"idle-run\", \"s-3\").await;\n        let drifted = registry::FollowupPrefs {\n            model: Some(\"opus\".to_string()),\n            ..test_followup_prefs()\n        };\n        let delivered = deliver_to_idle_followup(&registry, Some(\"s-3\"), &drifted, || {\n            panic!(\"the prompt must not be built for a mismatched process\")\n        })\n        .await\n        .unwrap();\n        assert_eq!(delivered, None);\n        assert!(registry.take_awaiting_followup(\"s-3\").is_none());\n        // kill() goes through spawn_blocking; the run's killed flag is how a\n        // child-less entry records it (the real path start_kills the child).\n        let killed = registry.get(\"idle-run\").unwrap().killed;\n        for _ in 0..100 {\n            if killed.load(std::sync::atomic::Ordering::SeqCst) {\n                let _ = child.kill().await;\n                return;\n            }\n            tokio::time::sleep(std::time::Duration::from_millis(50)).await;\n        }\n        panic!(\"idle run was not killed after settings drift\");\n    }\n\n    /// A run launched for computer use has the driver mounted and\n    /// pre-approved. A later ordinary send (desktop or remote) must never be\n    /// written into it: computer use is opted into per send.\n    #[tokio::test]\n    async fn plain_send_never_reuses_a_parked_computer_use_process() {\n        let registry = Arc::new(ProcessRegistry::default());\n        let mut child = idle_followup_child_with(\n            &registry,\n            \"cu-run\",\n            \"s-cu\",\n            registry::FollowupPrefs {\n                computer_use: true,\n                ..test_followup_prefs()\n            },\n        )\n        .await;\n        let delivered = deliver_to_idle_followup(&registry, Some(\"s-cu\"), &test_followup_prefs(), || {\n            panic!(\"the prompt must not reach the computer-use process\")\n        })\n        .await\n        .unwrap();\n        assert_eq!(delivered, None);\n        let killed = registry.get(\"cu-run\").unwrap().killed;\n        for _ in 0..100 {\n            if killed.load(std::sync::atomic::Ordering::SeqCst) {\n                let _ = child.kill().await;\n                return;\n            }\n            tokio::time::sleep(std::time::Duration::from_millis(50)).await;\n        }\n        panic!(\"parked computer-use run was not killed\");\n    }\n\n    /// The first turn settles at its own result even with a task pending, so\n    /// the UI is idle; a CLI that then dies without a follow-up adds nothing.\n    #[tokio::test]\n    async fn claude_pending_background_task_still_settles_on_eof() {\n        let events = replay_engine_output(\n            \"claude\",\n            Box::new(claude::ClaudeEngine::new()),\n            &[\n                claude_tasks_changed(&[\"bg1\"]),\n                claude_text_delta(\"started\"),\n                claude_result(),\n            ],\n        )\n        .await;\n        let kinds: Vec<_> = events\n            .iter()\n            .map(|event| event[\"kind\"].as_str().unwrap())\n            .collect();\n        assert_eq!(kinds, [\"delta\", \"done\"], \"{events:?}\");\n    }\n\n    /// No background task: the first result is the end of the turn, exactly\n    /// as before.\n    #[tokio::test]\n    async fn claude_plain_turn_still_settles_on_first_result() {\n        let events = replay_engine_output(\n            \"claude\",\n            Box::new(claude::ClaudeEngine::new()),\n            &[claude_text_delta(\"hi\"), claude_result()],\n        )\n        .await;\n        let kinds: Vec<_> = events\n            .iter()\n            .map(|event| event[\"kind\"].as_str().unwrap())\n            .collect();\n        assert_eq!(kinds, [\"delta\", \"done\"], \"{events:?}\");\n    }\n\n    #[tokio::test]\n    async fn legacy_agent_end_can_retry_and_recover_before_eof() {\n        let events = replay_cli_output(&[\n            serde_json::json!({\"type\":\"turn_end\",\"message\":{\"role\":\"assistant\",\"stopReason\":\"error\",\"errorMessage\":\"socket closed\"}}),\n            serde_json::json!({\"type\":\"agent_end\",\"messages\":[{\"role\":\"assistant\",\"stopReason\":\"error\",\"errorMessage\":\"socket closed\"}]}),\n            serde_json::json!({\"type\":\"auto_retry_start\",\"attempt\":1,\"maxAttempts\":50}),\n            serde_json::json!({\"type\":\"message_update\",\"assistantMessageEvent\":{\"type\":\"text_delta\",\"delta\":\"recovered\"}}),\n            serde_json::json!({\"type\":\"turn_end\",\"message\":{\"role\":\"assistant\",\"stopReason\":\"stop\"}}),\n            serde_json::json!({\"type\":\"agent_end\",\"messages\":[{\"role\":\"assistant\",\"stopReason\":\"stop\"}]}),\n        ]).await;\n        let kinds: Vec<_> = events\n            .iter()\n            .map(|event| event[\"kind\"].as_str().unwrap())\n            .collect();\n        assert_eq!(kinds, [\"retry\", \"delta\", \"done\"]);\n        assert_eq!(events[1][\"data\"], \"recovered\");\n    }\n\n    #[tokio::test]\n    async fn clean_eof_preserves_a_final_model_failure() {\n        for failure in [\n            serde_json::json!({\"type\":\"turn_end\",\"message\":{\"role\":\"assistant\",\"stopReason\":\"error\",\"errorMessage\":\"401 Invalid token\"}}),\n            serde_json::json!({\"type\":\"auto_retry_end\",\"success\":false,\"finalError\":\"socket closed\"}),\n        ] {\n            let events = replay_cli_output(&[failure]).await;\n            let last = events.last().unwrap();\n            assert_eq!(\n                last[\"kind\"], \"error\",\n                \"clean process exit must not turn a failed request into success\"\n            );\n            assert!(matches!(\n                last[\"data\"].as_str(),\n                Some(\"401 Invalid token\" | \"socket closed\")\n            ));\n            assert!(!events.iter().any(|event| event[\"kind\"] == \"done\"));\n        }\n    }\n    /// A background grandchild inheriting stdout keeps the pipe open after\n    /// the CLI exits, so EOF never comes. The child-exit watch must settle\n    /// the run anyway — drain the buffered lines, emit done, drain the\n    /// registry — instead of parking the reader (and the run's concurrency\n    /// slots) on the held pipe forever.\n    #[cfg(unix)]\n    #[tokio::test]\n    async fn child_exit_settles_run_despite_pipe_holding_grandchild() {\n        let done_lines = [\n            serde_json::json!({\"type\":\"turn_end\",\"message\":{\"role\":\"assistant\",\"stopReason\":\"stop\"}}),\n            serde_json::json!({\"type\":\"agent_end\",\"messages\":[{\"role\":\"assistant\",\"stopReason\":\"stop\"}]}),\n        ];\n        let script = format!(\n            \"printf '%s\\\\n' {}; sleep 600 & exit 0\",\n            done_lines\n                .iter()\n                .map(|line| format!(\"'{line}'\"))\n                .collect::<Vec<_>>()\n                .join(\" \")\n        );\n        let mut command = tokio::process::Command::new(\"sh\");\n        command\n            .arg(\"-c\")\n            .arg(script)\n            .stdin(std::process::Stdio::null())\n            .stdout(std::process::Stdio::piped())\n            .stderr(std::process::Stdio::null());\n        // Match production: own process group, so the settle path's group\n        // sweep also reaps the pipe-holding grandchild.\n        command.process_group(0);\n        let mut child = command.spawn().unwrap();\n        let pid = child.id().unwrap();\n        let stdout = child.stdout.take().unwrap();\n        let child = Arc::new(TokioMutex::new(child));\n        let emitter = Arc::new(CollectingEmitter::default());\n        let registry = Arc::new(ProcessRegistry::default());\n        let killed = Arc::new(std::sync::atomic::AtomicBool::new(false));\n        for key in [\"pipe-held-run\", \"session-held\"] {\n            registry.insert(\n                key.to_string(),\n                ChildEntry {\n                    child: Some(Arc::clone(&child)),\n                    pid,\n                    run_id: \"pipe-held-run\".to_string(),\n                    killed: Arc::clone(&killed),\n                    reader_abort: Arc::new(std::sync::OnceLock::new()),\n                    stdin: None,\n                    questions: Arc::new(Mutex::new(HashMap::new())),\n                    plans: Arc::new(Mutex::new(HashMap::new())),\n                },\n            );\n        }\n        let ctx = RunContext {\n            core: TurnCore {\n                sink: event_sink::EventSink::new(emitter.clone()),\n                registry: Arc::clone(&registry),\n                engine_id: \"omp\".to_string(),\n                run_id: \"pipe-held-run\".to_string(),\n                db: None,\n                followup: None,\n            },\n            engine_impl: Box::new(pi_family::omp()),\n            pid,\n            preassigned_session_id: Some(\"session-held\".to_string()),\n            initial_model: None,\n            comparison_model: None,\n            initial_effort: None,\n            child,\n            killed,\n            cleanup_files: Vec::new(),\n            mcp_restore: None,\n            stderr_buf: Arc::new(Mutex::new(String::new())),\n            stdout_plain_buf: Arc::new(Mutex::new(String::new())),\n            // See the pipe-retry constructor above.\n            #[cfg(windows)]\n            _tree_guard: None,\n        };\n        // Unbounded on the old EOF-only reader: the sleep holds the pipe\n        // for 600s. POST_EXIT_DRAIN settles this in well under a second.\n        tokio::time::timeout(std::time::Duration::from_secs(5), run_reader(stdout, ctx))\n            .await\n            .expect(\"reader must settle after child exit, not park on the held pipe\");\n        let events = std::mem::take(&mut *emitter.0.lock().unwrap());\n        let kinds: Vec<_> = events\n            .iter()\n            .map(|event| event[\"kind\"].as_str().unwrap())\n            .collect();\n        assert_eq!(\n            kinds,\n            [\"done\"],\n            \"buffered turn events must survive the drain\"\n        );\n        assert_eq!(\n            registry.0.lock().unwrap().len(),\n            0,\n            \"settled run must drain its registry entries\"\n        );\n    }\n}\n#[cfg(test)]\nmod codex_home_bin_tests {\n    use super::*;\n\n    #[test]\n    fn engine_bin_prefers_codex_home_bin() {\n        let dir =\n            std::env::temp_dir().join(format!(\"ccgui-codex-home-bin-{}\", uuid::Uuid::new_v4()));\n        std::fs::create_dir_all(dir.join(\"bin\")).unwrap();\n        let candidate = dir.join(\"bin\").join(\"codex\");\n        std::fs::write(&candidate, \"#!/bin/sh\\n\").unwrap();\n        #[cfg(unix)]\n        {\n            use std::os::unix::fs::PermissionsExt;\n            std::fs::set_permissions(&candidate, std::fs::Permissions::from_mode(0o755)).unwrap();\n        }\n        let mut settings = crate::settings::AppSettings::default();\n        settings.codex_home = Some(dir.to_string_lossy().into_owned());\n        let resolved = engine_bin(&settings, \"codex\");\n        assert_eq!(PathBuf::from(&resolved), candidate);\n\n        // An explicit codexBin override (set before the home row existed, or\n        // hand-edited) still wins over $home/bin/codex.\n        #[cfg(unix)]\n        {\n            settings.bin_overrides.insert(\n                \"codexBin\".to_string(),\n                serde_json::Value::String(\"/bin/sh\".to_string()),\n            );\n            assert_eq!(engine_bin(&settings, \"codex\"), \"/bin/sh\");\n        }\n        let _ = std::fs::remove_dir_all(&dir);\n    }\n}\n#[cfg(test)]\nmod plan_respond_tests {\n    //! respond_plan_review 的交付路径测试:批准/修改帧真实写进子进程\n    //! stdin、写失败退回待审、重复提交冲突。停车上下文需要 pub(crate)\n    //! 的 registry insert,故在 crate 内;IPC 形状与 fail-closed 见\n    //! tests/plan_review.rs。\n    use super::*;\n    use crate::engine::plan_review::{self, PlanDecision, PlanReview};\n    use serde_json::json;\n    use std::sync::{Arc, Mutex};\n    use tauri::Manager;\n\n    fn build_state(tag: &str) -> (tauri::App<tauri::test::MockRuntime>, Arc<crate::db::Db>) {\n        let app = tauri::test::mock_builder()\n            .build(tauri::test::mock_context(tauri::test::noop_assets()))\n            .unwrap();\n        let dir = std::env::temp_dir().join(format!(\n            \"ccgui-plan-respond-{tag}-{}-{:?}\",\n            std::process::id(),\n            std::time::SystemTime::now()\n                .duration_since(std::time::UNIX_EPOCH)\n                .map(|d| d.as_millis())\n                .unwrap_or(0)\n        ));\n        std::fs::create_dir_all(&dir).unwrap();\n        let db = Arc::new(crate::db::Db::open_at(&dir.join(\"app.db\")).unwrap());\n        app.manage(crate::AppState {\n            db: Arc::clone(&db),\n            sink: crate::event_sink::EventSink::new(Arc::new(app.handle().clone())),\n            terminal_sink: crate::event_sink::EventSink::with_name(\n                Arc::new(app.handle().clone()),\n                crate::terminal::TERMINAL_OUTPUT_EVENT,\n            ),\n            plugin_sink: crate::event_sink::EventSink::with_name(\n                Arc::new(app.handle().clone()),\n                crate::event_sink::PLUGIN_AGENT_EVENT_NAME,\n            ),\n            mission_sink: crate::event_sink::EventSink::with_name(\n                Arc::new(app.handle().clone()),\n                crate::event_sink::MISSION_AGENT_EVENT_NAME,\n            ),\n            terminals: crate::terminal::TerminalRegistry::default(),\n            processes: Arc::new(registry::ProcessRegistry::default()),\n            emitters: crate::event_sink::BroadcastEmit::new(Arc::new(app.handle().clone())),\n            web: crate::web::WebAccessState::default(),\n            relay: crate::relay::RelayState::default(),\n            dsh_host: Arc::new(crate::dsh_host::DshHostState::default()),\n            opencode_server: Arc::new(opencode_server::OpencodeServerState::default()),\n            worktree_creations: crate::git_worktree::CreationRegistry::default(),\n        });\n        (app, db)\n    }\n\n    fn review(plan_id: &str, session_id: &str) -> PlanReview {\n        PlanReview {\n            plan_id: plan_id.into(),\n            engine: \"dsh\".into(),\n            session_id: session_id.into(),\n            workspace_path: \"/tmp/ccgui-plan-respond-ws\".into(),\n            run_id: None,\n            revision: 0,\n            title: \"Test plan\".into(),\n            content: \"# Plan\\n\\ndo the thing\".into(),\n            content_hash: plan_review::content_hash(\"# Plan\\n\\ndo the thing\"),\n            complete: true,\n            review_kind: plan_review::PlanReviewKind::NativeRequest,\n            native_plan_id: Some(format!(\"native-{plan_id}\")),\n            exec_permission: \"auto\".into(),\n            status: plan_review::PlanStatus::AwaitingReview,\n            execution: plan_review::PlanExecution::NotStarted,\n            decision: None,\n            decision_intent_at: None,\n            applied_at: None,\n            created_at: 0,\n            updated_at: 0,\n            superseded_by: None,\n        }\n    }\n\n    /// 停车一个 native_request 上下文并(可选)接一根真实 stdin。\n    fn park(\n        app: &tauri::App<tauri::test::MockRuntime>,\n        key: &str,\n        plan_id: &str,\n        stdin: Option<Arc<tokio::sync::Mutex<Option<tokio::process::ChildStdin>>>>,\n        extra: serde_json::Value,\n    ) {\n        let state = app.state::<crate::AppState>();\n        let mut parked = json!({\n            \"revision\": 1,\n            \"route\": \"stdin\",\n            \"frames\": {\n                \"approve\": {\"jsonrpc\": \"2.0\", \"id\": 9, \"result\": {\"outcome\": \"approved\"}},\n                \"changes\": {\"jsonrpc\": \"2.0\", \"id\": 9, \"result\": {\"outcome\": \"changes\", \"custom\": PLAN_FEEDBACK_PLACEHOLDER}},\n            },\n        });\n        if let Some(obj) = extra.as_object() {\n            for (k, v) in obj {\n                parked[k] = v.clone();\n            }\n        }\n        let mut plans = std::collections::HashMap::new();\n        plans.insert(plan_id.to_string(), parked);\n        state.processes.insert(\n            key.to_string(),\n            registry::ChildEntry {\n                child: None,\n                pid: 4242,\n                run_id: key.to_string(),\n                killed: Arc::new(std::sync::atomic::AtomicBool::new(false)),\n                reader_abort: Arc::new(std::sync::OnceLock::new()),\n                stdin,\n                questions: Arc::new(Mutex::new(std::collections::HashMap::new())),\n                plans: Arc::new(Mutex::new(plans)),\n            },\n        );\n    }\n\n    /// 一个把 stdin 原样转到 stdout 的子进程；stdout 落进文件，返回\n    /// (child, stdin, 输出路径)。Unix 用 `cat`；Windows 没有 `cat`，而 `more`\n    /// 会分页并把制表符展开——这三个用例断言的是应用写进原生进程的帧，任何改写\n    /// 都会让断言失去意义，所以让 PowerShell 逐字节复制标准流。\n    fn frame_sink_command() -> tokio::process::Command {\n        if cfg!(windows) {\n            let mut command = tokio::process::Command::new(\"powershell\");\n            command.args([\n                \"-NoProfile\",\n                \"-NonInteractive\",\n                \"-Command\",\n                \"[Console]::OpenStandardInput().CopyTo([Console]::OpenStandardOutput())\",\n            ]);\n            command\n        } else {\n            tokio::process::Command::new(\"cat\")\n        }\n    }\n\n    fn spawn_frame_sink(\n        tag: &str,\n    ) -> (\n        tokio::process::Child,\n        Arc<tokio::sync::Mutex<Option<tokio::process::ChildStdin>>>,\n        std::path::PathBuf,\n    ) {\n        let out_path = std::env::temp_dir().join(format!(\n            \"ccgui-plan-frames-{tag}-{}\",\n            std::process::id()\n        ));\n        let out_file = std::fs::File::create(&out_path).unwrap();\n        let mut child = frame_sink_command()\n            .stdin(std::process::Stdio::piped())\n            .stdout(std::process::Stdio::from(out_file))\n            .spawn()\n            .unwrap();\n        let stdin = Arc::new(tokio::sync::Mutex::new(child.stdin.take()));\n        (child, stdin, out_path)\n    }\n\n    async fn drain_frames(\n        app: &tauri::App<tauri::test::MockRuntime>,\n        key: &str,\n        mut child: tokio::process::Child,\n        out_path: &std::path::Path,\n    ) -> String {\n        let entry = app.state::<crate::AppState>().processes.get(key).unwrap();\n        if let Some(stdin) = entry.stdin {\n            *stdin.lock().await = None;\n        }\n        child.wait().await.unwrap();\n        std::fs::read_to_string(out_path).unwrap()\n    }\n\n    #[tokio::test]\n    async fn approve_delivers_the_native_frame_then_conflicts_on_repeat() {\n        let (app, db) = build_state(\"approve\");\n        plan_review::record_review(&db, &review(\"plan-a\", \"sess-a\")).unwrap();\n        let (child, stdin, out_path) = spawn_frame_sink(\"approve\");\n        park(&app, \"sess-a\", \"plan-a\", Some(stdin), json!({}));\n\n        let outcome = respond_plan_review(\n            app.state::<crate::AppState>(),\n            \"plan-a\".to_string(),\n            1,\n            PlanDecision::Approve,\n            None,\n        )\n        .await\n        .expect(\"approve must apply\");\n        let PlanRespondOutcome::Applied { review } = outcome else {\n            panic!(\"approve must apply, got {outcome:?}\");\n        };\n        assert_eq!(review.status, plan_review::PlanStatus::Approved);\n        assert_eq!(review.execution, plan_review::PlanExecution::Starting);\n\n        let written = drain_frames(&app, \"sess-a\", child, &out_path).await;\n        assert!(written.contains(\"\\\"outcome\\\":\\\"approved\\\"\"), \"{written}\");\n\n        // 停住的上下文已移除;重复提交同一 revision 返回冲突而非重复执行。\n        let entry = app.state::<crate::AppState>().processes.get(\"sess-a\").unwrap();\n        assert!(entry.plans.lock().unwrap().is_empty());\n        let again = respond_plan_review(\n            app.state::<crate::AppState>(),\n            \"plan-a\".to_string(),\n            1,\n            PlanDecision::Approve,\n            None,\n        )\n        .await\n        .expect(\"repeat respond must not error\");\n        assert!(\n            matches!(again, PlanRespondOutcome::Conflict { .. }),\n            \"double submit must conflict: {again:?}\"\n        );\n    }\n\n    #[tokio::test]\n    async fn request_changes_substitutes_feedback_into_the_frame() {\n        let (app, db) = build_state(\"changes\");\n        plan_review::record_review(&db, &review(\"plan-b\", \"sess-b\")).unwrap();\n        let (child, stdin, out_path) = spawn_frame_sink(\"changes\");\n        park(&app, \"sess-b\", \"plan-b\", Some(stdin), json!({}));\n\n        let outcome = respond_plan_review(\n            app.state::<crate::AppState>(),\n            \"plan-b\".to_string(),\n            1,\n            PlanDecision::RequestChanges,\n            Some(\"收紧范围,别动鉴权模块\".to_string()),\n        )\n        .await\n        .expect(\"changes must apply\");\n        let PlanRespondOutcome::Applied { review } = outcome else {\n            panic!(\"changes must apply, got {outcome:?}\");\n        };\n        assert_eq!(review.status, plan_review::PlanStatus::ChangesRequested);\n\n        let written = drain_frames(&app, \"sess-b\", child, &out_path).await;\n        assert!(written.contains(\"收紧范围,别动鉴权模块\"), \"{written}\");\n        assert!(!written.contains(PLAN_FEEDBACK_PLACEHOLDER), \"{written}\");\n    }\n\n    #[tokio::test]\n    async fn a_closed_stdin_reverts_to_pending_and_keeps_the_intent() {\n        let (app, db) = build_state(\"revert\");\n        plan_review::record_review(&db, &review(\"plan-c\", \"sess-c\")).unwrap();\n        // stdin 已关闭:写管道失败,批准绝不显示成功。\n        park(\n            &app,\n            \"sess-c\",\n            \"plan-c\",\n            Some(Arc::new(tokio::sync::Mutex::new(None))),\n            json!({}),\n        );\n\n        let result = respond_plan_review(\n            app.state::<crate::AppState>(),\n            \"plan-c\".to_string(),\n            1,\n            PlanDecision::Approve,\n            None,\n        )\n        .await;\n        let Err(message) = result else {\n            panic!(\"a closed stdin must fail the respond\");\n        };\n        assert!(message.contains(\"NOT delivered\"), \"{message}\");\n\n        let reverted = plan_review::get_review(&db, \"plan-c\", 1).unwrap().unwrap();\n        assert_eq!(reverted.status, plan_review::PlanStatus::AwaitingReview);\n        assert_eq!(reverted.execution, plan_review::PlanExecution::NotStarted);\n        assert!(reverted.decision_intent_at.is_some());\n        assert!(reverted.applied_at.is_none());\n        // 停住的上下文保留,用户可重试。\n        let entry = app.state::<crate::AppState>().processes.get(\"sess-c\").unwrap();\n        assert!(entry.plans.lock().unwrap().contains_key(\"plan-c\"));\n    }\n\n    #[tokio::test]\n    async fn a_changed_body_expires_the_revision_instead_of_executing() {\n        let (app, db) = build_state(\"stale-body\");\n        plan_review::record_review(&db, &review(\"plan-d\", \"sess-d\")).unwrap();\n        let (_child, stdin, _out) = spawn_frame_sink(\"stale-body\");\n        // 停车上下文记录的正文哈希与落盘记录不一致:审批期间正文已变,\n        // 先失效再要求重新审阅,绝不带着旧正文执行(PRD §4.2 末条)。\n        park(\n            &app,\n            \"sess-d\",\n            \"plan-d\",\n            Some(stdin),\n            json!({\"contentHash\": \"different-hash\"}),\n        );\n\n        let result = respond_plan_review(\n            app.state::<crate::AppState>(),\n            \"plan-d\".to_string(),\n            1,\n            PlanDecision::Approve,\n            None,\n        )\n        .await;\n        let Err(message) = result else {\n            panic!(\"a changed body must not execute\");\n        };\n        assert!(message.contains(\"expired\"), \"{message}\");\n        let expired = plan_review::get_review(&db, \"plan-d\", 1).unwrap().unwrap();\n        assert_eq!(expired.status, plan_review::PlanStatus::Expired);\n    }\n}\n"
    },
    {
      "path": "src-tauri/src/engine/dsh_session.rs",
      "content": "//! DSH host-session turn driver: one codemoss send = one host turn, streamed\n//! over the gateway mux.\n//!\n//! Wire (verified live against dsh 0.1.2):\n//! - RPC is plain HTTP ([`crate::dsh_host::host_call`], cookie-authenticated):\n//!   `workspace/create` → `session/create` (resume passes the known\n//!   sessionId) → `session/selectModel`? → `session/prompt` (mode \"queue\");\n//!   interrupt sends `session/cancel`. Attachments ride the prompt as base64\n//!   image content parts, after [`super::dsh_images`] declares the input\n//!   modality on hand-declared `llm-pi-ai` routes (`settings/mutate`).\n//! - Streams share one WebSocket, `ws://<origin>/api/remote.mux` with the\n//!   auth cookie: open `$events` (the ready frame yields the events clientId;\n//!   waterfall frames are approval/question calls, answered via\n//!   `$events/result`) and `session/follow` with **`assistantStream: true`** —\n//!   the opt-in that adds live `assistant-stream` frames (start / chunk\n//!   {block-start, text-delta, reasoning-delta, usage, finish, block-end} /\n//!   end committed). Without the opt-in only durable session events flow\n//!   (assistant/message lands whole — that is tmd-cli's subscription).\n//! - Durable follow events project to tool rows; durable `assistant/message`\n//!   renders only when an attempt streamed no deltas (fallback), so live\n//!   text never doubles.\n\nuse std::collections::HashMap;\nuse std::sync::atomic::{AtomicBool, Ordering};\nuse std::sync::Arc;\nuse std::time::Duration;\n\nuse futures_util::{SinkExt, StreamExt};\nuse serde_json::{json, Value};\nuse tokio_tungstenite::tungstenite::client::IntoClientRequest;\nuse tokio_tungstenite::tungstenite::Message;\n\nuse super::{dsh_images, EngineEvent, SendRequest, TurnCore, TurnState, VirtualRunGuard};\nuse crate::dsh_host::host_call;\n\n/// 提取并规范化上下文窗口字段。DSH 的 `TokenUsage` 不带窗口，窗口只在\n/// `request/context` 事件里（`RequestContext.contextWindow`），所以调用方把\n/// 该事件缓存下来的值作为 `fallback` 传进来：usage 报告自带窗口时以它为准，\n/// 否则补上 host 声明的真实窗口——缺了它前端只剩 200k 假定值。\nfn attach_context_window(mut usage: Value, fallback: Option<i64>) -> Value {\n    if usage.get(\"model_context_window\").is_some() {\n        return usage;\n    }\n\n    let window = usage\n        .get(\"context_window\")\n        .or_else(|| usage.get(\"contextWindow\"))\n        .or_else(|| usage.get(\"model_context_window\"))\n        .and_then(|v| match v {\n            Value::Number(n) => n.as_i64(),\n            Value::String(s) => s.parse().ok(),\n            _ => None,\n        })\n        .filter(|&w| w > 0)\n        .or(fallback.filter(|&w| w > 0));\n\n    if let Some(w) = window {\n        if let Some(obj) = usage.as_object_mut() {\n            obj.insert(\"model_context_window\".to_string(), Value::Number(w.into()));\n        }\n    }\n\n    usage\n}\n\n/// `request/context` 的窗口通告（`RequestContext { provider, model,\n/// contextWindow? }`）：DSH 已发布事件里唯一的窗口来源。读出来缓存到 view，\n/// 供本轮的 usage 事件与 done 载荷补窗口。\nfn context_window_of(data: &Value) -> Option<i64> {\n    data.get(\"contextWindow\")\n        .or_else(|| data.get(\"context_window\"))\n        .and_then(|v| match v {\n            Value::Number(n) => n.as_i64(),\n            Value::String(s) => s.parse().ok(),\n            _ => None,\n        })\n        .filter(|&w| w > 0)\n}\n\nconst STREAM_EVENTS: &str = \"events\";\nconst STREAM_FOLLOW: &str = \"follow\";\n/// Follow history replay is useless here (codemoss renders its own stored\n/// conversation); the smallest window keeps the opening snapshot light.\nconst FOLLOW_MAX_MESSAGES: u32 = 1;\n/// The killed-flag poll cadence inside the WS select loop.\nconst KILL_POLL: Duration = Duration::from_millis(150);\n/// Wait for the follow snapshot (proof the subscription is live) at most\n/// this long before dispatching the prompt.\nconst FOLLOW_READY_TIMEOUT: Duration = Duration::from_secs(5);\n/// plan 权限下等待 host 回读 plan/mode{active:true} 的上限：无 open turn\n/// 时 /plan 立即 committed 并追加该日志事件，超时即 host 未确认。\nconst PLAN_MODE_CONFIRM_TIMEOUT: Duration = Duration::from_secs(10);\n\ntype Ws =\n    tokio_tungstenite::WebSocketStream<tokio_tungstenite::MaybeTlsStream<tokio::net::TcpStream>>;\n\n/// Per-turn view state: live deltas arrive per assistant attempt, and the\n/// durable `assistant/message` settlement must not double-render them.\n#[derive(Default)]\nstruct TurnView {\n    attempt_streamed_text: bool,\n    last_usage: Option<Value>,\n    turn_ended: bool,\n    /// `request/context` 通告的上下文窗口（本轮内有效）。usage 报告自带窗口时\n    /// 由它兜底，done 载荷也要带上，否则前端在回合结束时丢回 200k 假定值。\n    context_window: Option<i64>,\n    /// `$events` clientId from the ready frame; required on every answer.\n    events_client_id: Option<String>,\n    /// callId → tool name from dispatched `tool/call` rows, so the matching\n    /// `tool/result` patch can find the row it belongs to.\n    tool_names: HashMap<String, String>,\n    /// 工作区路径：plan-review 记录的身份字段（record.workspace_path）。\n    workspace: String,\n}\n\n/// Drive one send as a host turn. Mirrors `run_reader`'s settle contract:\n/// dispatch events until a terminal done/error, then drain this run's\n/// registry entries. Transport/rpc failures surface as `EngineEvent::Error`.\npub(crate) async fn run_host_turn(\n    core: TurnCore,\n    req: SendRequest,\n    host: Arc<crate::dsh_host::DshHostState>,\n    killed: Arc<AtomicBool>,\n    virtual_pid: u32,\n) {\n    let mut state = TurnState::new(req.session_id.clone());\n    let mut view = TurnView::default();\n    let preassigned_session_id = req.session_id.clone();\n    view.workspace = req.workspace.to_string_lossy().into_owned();\n    // Abort-safe backstop: the by-name removals below only run when the task\n    // finishes normally. An abort or a panic would otherwise leave this run's\n    // keys pinning a concurrency slot until app exit.\n    let _registry_guard =\n        VirtualRunGuard::new(Arc::clone(&core.registry), core.run_id.clone(), virtual_pid);\n    let result = turn_inner(&core, &mut state, &mut view, &req, &host, &killed).await;\n    // Pending questions die with the turn: settle their cards BEFORE any\n    // terminal dispatch, or the monotonic saw_done/saw_error guard in\n    // dispatch_event would drop these and leave answerable cards pointing at\n    // a settled turn.\n    for key in [\n        state.native_session_id.clone(),\n        Some(core.run_id.clone()),\n        preassigned_session_id.clone(),\n    ]\n    .into_iter()\n    .flatten()\n    {\n        for request_id in core.registry.take_questions(&key) {\n            core.dispatch_event(&mut state, EngineEvent::QuestionSettled { request_id });\n        }\n        // 停住的计划审批随运行消亡即过期（P1 收尾义务，PRD §8 防线 3）。\n        super::reader::expire_parked_plans(&core, &mut state, &key);\n    }\n    if let Err(error) = result {\n        core.dispatch_event(&mut state, EngineEvent::Error(error));\n    }\n    // An interrupted run commits its partial output as a normal turn end —\n    // the same contract as the SIGKILL'd process path.\n    if !state.saw_done && !state.saw_error {\n        let usage = if killed.load(Ordering::SeqCst) {\n            None\n        } else {\n            // 没有 usage 分片但 host 通告过窗口时，done 也要把窗口带上，\n            // 否则回合结束前端又掉回 200k 假定值。\n            view.last_usage\n                .clone()\n                .or_else(|| view.context_window.map(|window| json!({ \"contextWindow\": window })))\n                .map(|usage| attach_context_window(usage, view.context_window))\n        };\n        let session_id = state.native_session_id.clone();\n        core.dispatch_event(&mut state, EngineEvent::Done { session_id, usage });\n    }\n    core.registry.remove_if_pid(&core.run_id, virtual_pid);\n    // Clean up both the native session id (if the engine reported one) and\n    // the preassigned session id (if we resumed an existing conversation).\n    // A resumed session was keyed at spawn under req.session_id, so we must\n    // remove that alias even if the native id differs or never arrived.\n    if let Some(session_id) = state.native_session_id.clone() {\n        core.registry.remove_if_pid(&session_id, virtual_pid);\n    }\n    if let Some(session_id) = preassigned_session_id {\n        core.registry.remove_if_pid(&session_id, virtual_pid);\n    }\n    core.sink.flush();\n}\n\nasync fn turn_inner(\n    core: &TurnCore,\n    state: &mut TurnState,\n    view: &mut TurnView,\n    req: &SendRequest,\n    host: &Arc<crate::dsh_host::DshHostState>,\n    killed: &Arc<AtomicBool>,\n) -> Result<(), String> {\n    // The host must be up before anything else: ensure adopts or spawns it\n    // (serialized internally, so a chat send racing autostart is safe).\n    let settings = crate::settings::read_settings().unwrap_or_default();\n    let origin = crate::dsh_host::configured_origin(&settings);\n    crate::dsh_host::ensure_host(host, &settings).await?;\n    let cookie = crate::dsh_host::host_cookie(&origin);\n\n    // Workspace: registered by path so resumed sessions keep their identity.\n    let workspace = host_call(\n        &origin,\n        \"workspace/create\",\n        json!({ \"request\": { \"path\": req.workspace.to_string_lossy() } }),\n    )\n    .await?\n    .pointer(\"/workspace/workspaceId\")\n    .and_then(Value::as_str)\n    .map(str::to_string)\n    .ok_or(\"workspace/create 未返回 workspaceId\")?;\n\n    // Session continuity: codemoss passes back the native id it received via\n    // the \"session\" event; a fresh id comes back for a new conversation.\n    let mut create_args = json!({ \"request\": { \"workspaceId\": workspace } });\n    if let Some(session_id) = req.session_id.as_deref() {\n        create_args[\"request\"][\"sessionId\"] = Value::String(session_id.to_string());\n    }\n    let session_id = host_call(&origin, \"session/create\", create_args)\n        .await?\n        .pointer(\"/sessionId\")\n        .and_then(Value::as_str)\n        .map(str::to_string)\n        .ok_or(\"session/create 未返回 sessionId\")?;\n    core.dispatch_event(state, EngineEvent::SessionId(session_id.clone()));\n    // 计划审批模式（PRD §5-DSH.2）：先经 commands/list 探测 host 是否组合了\n    // plan-mode 插件，缺失即受控报错——HTTP 200 不等于命令存在，绝不降级\n    // auto 执行。\n    let plan_mode = req.permission.as_deref() == Some(\"plan\");\n    if plan_mode {\n        ensure_plan_command(&origin, &session_id).await?;\n    }\n\n    // Model: the picker's ids are `provider/model` selector ids (models.rs).\n    if let Some(model) = req.model.as_deref().filter(|m| m.contains('/')) {\n        let (provider, model) = model.split_once('/').unwrap_or((\"\", model));\n        if !provider.is_empty() && !model.is_empty() {\n            let mut select_args = json!({ \"request\": { \"sessionId\": session_id, \"provider\": provider, \"model\": model } });\n            if let Some(effort) = req\n                .effort\n                .as_deref()\n                .map(str::trim)\n                .filter(|e| !e.is_empty())\n            {\n                select_args[\"request\"][\"effort\"] = json!(effort);\n                select_args[\"request\"][\"reasoningEffort\"] = json!(effort);\n            }\n            let selected = host_call(&origin, \"session/selectModel\", select_args).await;\n            if selected.is_err() {\n                core.dispatch_event(\n                    state,\n                    EngineEvent::Warn(format!(\"模型切换未生效，继续使用会话当前模型：{model}\")),\n                );\n            }\n        }\n    }\n\n    // Attachments: load through the shared image pipeline, then make sure\n    // the session's route actually admits images — hand-declared llm-pi-ai\n    // routes default to text-only until ccgui writes the modality claim.\n    let prompt_images = dsh_images::load_prompt_images(&req.images, &req.workspace)?;\n    if !prompt_images.is_empty() {\n        let Some((provider, model)) =\n            dsh_images::current_selection(&origin, req.model.as_deref()).await\n        else {\n            return Err(\n                \"DSH 需要先选定模型才能发送图片：host 未报告当前 provider/model\".to_string(),\n            );\n        };\n        dsh_images::ensure_image_admission(&origin, &provider, &model).await?;\n    }\n\n    let mut ws = mux_connect(&origin, cookie.as_deref()).await?;\n    // Streams must be live before the prompt so no turn event races the\n    // subscription: the follow snapshot proves the follow subscription landed,\n    // and the $events ready frame carries the clientId every question answer\n    // needs. Waiting for both kills the race where a waterfall frame arrived\n    // before the ready frame and the question was skipped as \"未就绪\".\n    let opened = ws_open_and_wait(&mut ws, &session_id).await;\n    view.events_client_id = opened.events_client_id;\n    if view.events_client_id.is_none() {\n        core.dispatch_event(\n            state,\n            EngineEvent::Warn(\"提问通道未就绪，本轮中的提问请求将被跳过\".to_string()),\n        );\n    }\n    if plan_mode {\n        // 进入 plan 模式：commands/execute \"/plan\"，并等 follow 流回读\n        // plan/mode{active:true} 提交后才允许下发 prompt（事件回读确认）。\n        enter_plan_mode(&origin, &session_id, &mut ws, opened.plan_active).await?;\n    }\n\n    let mut prompt_request = json!({\n        \"requestId\": format!(\"codemoss-{}\", uuid::Uuid::new_v4()),\n        \"sessionId\": session_id,\n        \"mode\": \"queue\",\n        \"content\": dsh_images::build_prompt_content(&req.prompt, &prompt_images),\n        \"clientTimeZone\": client_time_zone(),\n    });\n    if let Some(effort) = req\n        .effort\n        .as_deref()\n        .map(str::trim)\n        .filter(|e| !e.is_empty())\n    {\n        prompt_request[\"effort\"] = json!(effort);\n        prompt_request[\"reasoningEffort\"] = json!(effort);\n    }\n    let prompt = crate::dsh_host::host_call_rpc(\n        &origin,\n        \"session/prompt\",\n        json!({ \"request\": prompt_request }),\n    )\n    .await;\n    if let Err(error) = prompt {\n        let _ = ws.close(None).await;\n        return Err(format!(\n            \"任务下发失败：{}\",\n            dsh_images::format_prompt_refusal(&error)\n        ));\n    }\n\n    let (mut write, mut read) = ws.split();\n    let mut kill_poll = tokio::time::interval(KILL_POLL);\n    kill_poll.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);\n    loop {\n        tokio::select! {\n            frame = read.next() => match frame {\n                Some(Ok(Message::Text(text))) => {\n                    let Ok(parsed) = serde_json::from_str::<Value>(text.as_str()) else {\n                        continue;\n                    };\n                    if parsed.get(\"type\").and_then(Value::as_str) != Some(\"item\") {\n                        continue;\n                    }\n                    let stream_id = parsed.get(\"streamId\").and_then(Value::as_str).unwrap_or(\"\");\n                    let value = parsed.get(\"value\").cloned().unwrap_or(Value::Null);\n                    match stream_id {\n                        STREAM_FOLLOW => handle_follow(core, state, view, &value),\n                        STREAM_EVENTS => {\n                            handle_events_frame(core, state, view, &value, &origin).await;\n                        }\n                        _ => {}\n                    }\n                    if view.turn_ended {\n                        break;\n                    }\n                }\n                Some(Ok(_)) => {} // ping/pong/binary: keep the loop going\n                Some(Err(error)) => {\n                    if killed.load(Ordering::SeqCst) || view.turn_ended {\n                        break;\n                    }\n                    return Err(format!(\"dsh 会话流中断：{error}\"));\n                }\n                None => {\n                    if killed.load(Ordering::SeqCst) || view.turn_ended {\n                        break;\n                    }\n                    return Err(\"dsh 会话流已关闭\".to_string());\n                }\n            },\n            _ = kill_poll.tick() => {\n                if killed.load(Ordering::SeqCst) {\n                    // Best-effort server-side cancel; if this races the\n                    // turn's completion the host simply ignores it.\n                    let _ = host_call(\n                        &origin,\n                        \"session/cancel\",\n                        json!({ \"request\": { \"sessionId\": session_id } }),\n                    )\n                    .await;\n                    break;\n                }\n            }\n        }\n    }\n    let _ = write.close().await;\n    Ok(())\n}\n\n// ==================== plan mode entry ====================\n\n/// 前置探测（PRD §5-DSH.1/2）：commands/list 确认 plan 命令存在。缺插件\n/// （列表无 plan）或探测失败都受控报错，不降级 auto。\nasync fn ensure_plan_command(origin: &str, session_id: &str) -> Result<(), String> {\n    let listed = host_call(origin, \"commands/list\", json!({ \"agentId\": session_id }))\n        .await\n        .map_err(|error| format!(\"无法确认 host 的 plan 命令（commands/list 失败）：{error}\"))?;\n    if !plan_command_listed(&listed) {\n        return Err(\n            \"当前 dsh host 未组合 plan-mode 插件（commands/list 无 plan 命令），无法进入计划审批模式；不会降级为 auto 执行\"\n                .to_string(),\n        );\n    }\n    Ok(())\n}\n\n/// commands/list 应答里的 plan 命令存在性（纯函数，便于单测）。\nfn plan_command_listed(listed: &Value) -> bool {\n    listed\n        .as_array()\n        .map(|commands| {\n            commands\n                .iter()\n                .any(|command| command.get(\"name\").and_then(Value::as_str) == Some(\"plan\"))\n        })\n        .unwrap_or(false)\n}\n\n/// commands/execute 的应答分类（纯函数，便于单测）：未知命令返回\n/// undefined（线上为 null/缺 commandId）——HTTP 200 不算成功；handler 级\n/// 错误（result.kind==\"error\"）同样受控拒绝。\nfn plan_execute_outcome(result: &Value) -> Result<(), String> {\n    if result.get(\"commandId\").and_then(Value::as_str).is_none() {\n        return Err(\n            \"host 未确认 /plan 命令（应答为 undefined）：plan-mode 插件可能未组合，无法进入计划审批模式\"\n                .to_string(),\n        );\n    }\n    if result.pointer(\"/result/kind\").and_then(Value::as_str) == Some(\"error\") {\n        let text = result\n            .pointer(\"/result/text\")\n            .and_then(Value::as_str)\n            .unwrap_or(\"\");\n        return Err(format!(\"/plan 命令执行失败：{text}\"));\n    }\n    Ok(())\n}\n\n/// plan 权限的进入序列（PRD §5-DSH.2，P0 取证 DSH 节）：commands/execute\n/// {agentId, line:\"/plan\", submittedAttachments:[]}，然后等 follow 流回读\n/// plan/mode{active:true} 才返回。任何一步失败都受控报错，不降级 auto。\nasync fn enter_plan_mode(\n    origin: &str,\n    session_id: &str,\n    ws: &mut Ws,\n    already_active: bool,\n) -> Result<(), String> {\n    let result = host_call(\n        origin,\n        \"commands/execute\",\n        json!({\n            \"agentId\": session_id,\n            \"line\": \"/plan\",\n            \"submittedAttachments\": [],\n        }),\n    )\n    .await\n    .map_err(|error| format!(\"进入 plan 模式失败（commands/execute /plan）：{error}\"))?;\n    plan_execute_outcome(&result)?;\n    if already_active {\n        // 快照投影已显示 plan.active：本次 /plan 是 noop，不会再追加\n        // plan/mode 事件，无需等待回读。\n        return Ok(());\n    }\n    await_plan_mode_active(ws).await\n}\n\n/// 等 follow 流回读 plan/mode{active:true}（P0：无 open turn 时 /plan 立即\n/// committed 并向会话日志追加该事件，随 follow 流下行）。超时/断流 =\n/// host 未确认，受控报错；期间到达的其它事件（含 plan/mode:false）按\n/// 正常事件忽略。\nasync fn await_plan_mode_active(ws: &mut Ws) -> Result<(), String> {\n    let started = tokio::time::Instant::now();\n    while started.elapsed() < PLAN_MODE_CONFIRM_TIMEOUT {\n        let remaining = PLAN_MODE_CONFIRM_TIMEOUT - started.elapsed();\n        match tokio::time::timeout(remaining, ws.next()).await {\n            Ok(Some(Ok(Message::Text(text)))) => {\n                let Ok(value) = serde_json::from_str::<Value>(text.as_str()) else {\n                    continue;\n                };\n                if value.get(\"type\").and_then(Value::as_str) != Some(\"item\")\n                    || value.get(\"streamId\").and_then(Value::as_str) != Some(STREAM_FOLLOW)\n                {\n                    continue;\n                }\n                if value.pointer(\"/value/event/type\").and_then(Value::as_str)\n                    == Some(\"plan/mode\")\n                    && value.pointer(\"/value/event/data/active\").and_then(Value::as_bool)\n                        == Some(true)\n                {\n                    return Ok(());\n                }\n            }\n            Ok(Some(Ok(_))) => {} // ping/pong/binary: keep waiting\n            _ => break,\n        }\n    }\n    Err(\n        \"等待 plan/mode active 确认超时：host 未确认进入 plan 模式，已中止发送（不降级 auto）\"\n            .to_string(),\n    )\n}\n\n// ==================== frame projection ====================\n\n/// One follow-stream item: durable session events + the opted-in\n/// `assistant-stream` live frames.\nfn handle_follow(core: &TurnCore, state: &mut TurnState, view: &mut TurnView, value: &Value) {\n    match value.get(\"type\").and_then(Value::as_str) {\n        Some(\"snapshot\") => {} // history replay: codemoss renders its own log\n        Some(\"event\") => {\n            let event = value.get(\"event\").cloned().unwrap_or(Value::Null);\n            let event_type = event.get(\"type\").and_then(Value::as_str).unwrap_or(\"\");\n            let data = event.get(\"data\").cloned().unwrap_or(Value::Null);\n            handle_session_event(core, state, view, event_type, &data);\n        }\n        Some(\"assistant-stream\") => handle_assistant_stream(core, state, view, value),\n        _ => {}\n    }\n}\n\nfn handle_session_event(\n    core: &TurnCore,\n    state: &mut TurnState,\n    view: &mut TurnView,\n    event_type: &str,\n    data: &Value,\n) {\n    match event_type {\n        \"tool/call\" => {\n            let name = data.get(\"name\").and_then(Value::as_str).unwrap_or(\"tool\");\n            if let Some(call_id) = data.get(\"callId\").and_then(Value::as_str) {\n                view.tool_names\n                    .insert(call_id.to_string(), name.to_string());\n            }\n            let args = data\n                .get(\"arguments\")\n                .and_then(Value::as_str)\n                .and_then(|text| serde_json::from_str::<Value>(text).ok())\n                .or_else(|| data.get(\"arguments\").cloned());\n            core.dispatch_event(\n                state,\n                super::tool_call_message_with_id(\n                    name,\n                    args.as_ref(),\n                    data.get(\"callId\").and_then(Value::as_str),\n                ),\n            );\n        }\n        \"tool/result\" => {\n            let call_id = data\n                .pointer(\"/message/source/callId\")\n                .and_then(Value::as_str)\n                .unwrap_or(\"\");\n            let name = view\n                .tool_names\n                .get(call_id)\n                .cloned()\n                .unwrap_or_else(|| \"tool\".to_string());\n            let content = data\n                .pointer(\"/message/content\")\n                .and_then(Value::as_array)\n                .cloned()\n                .unwrap_or_default();\n            let text = content\n                .iter()\n                .filter_map(|block| block.get(\"text\").and_then(Value::as_str))\n                .collect::<Vec<_>>()\n                .join(\"\\n\");\n            let is_error = content\n                .iter()\n                .any(|block| block.get(\"isError\").and_then(Value::as_bool) == Some(true));\n            core.dispatch_event(\n                state,\n                super::tool_result_patch_with_id(\n                    &name,\n                    Some(&json!({ \"text\": text, \"isError\": is_error })),\n                    (!call_id.is_empty()).then_some(call_id),\n                ),\n            );\n        }\n        \"assistant/message\" => {\n            // Settlement of the streamed attempt: render only when the live\n            // deltas never flowed, else the message would appear twice.\n            if !view.attempt_streamed_text {\n                let text = message_text(data);\n                if !text.is_empty() {\n                    core.dispatch_event(state, EngineEvent::Delta(format!(\"{text}\\n\\n\")));\n                }\n            }\n            view.attempt_streamed_text = false;\n        }\n        \"turn/end\" => {\n            view.turn_ended = true;\n            let kind = data\n                .pointer(\"/reason/kind\")\n                .and_then(Value::as_str)\n                .unwrap_or(\"completed\");\n            if kind != \"completed\" {\n                core.dispatch_event(state, EngineEvent::Warn(format!(\"本轮结束（{kind}）\")));\n            }\n        }\n        // 计划审批的配套状态事件：批准后的 plan/mode:false 与 pending\n        // inactive 投影都是正常会话日志事件（PRD §5-DSH.6/7）——既不是\n        // 审批退出路径（/plan off 不实现为退出捷径），也不是错误。\n        \"plan/mode\" => {}\n        // 请求上下文：DSH 在这里通告本次请求的真实窗口（provider/model/\n        // contextWindow），是已发布事件里唯一的窗口来源——TokenUsage 与\n        // session/modelCatalog 都不带窗口。按请求配对：每个通告都覆盖缓存\n        // （不带窗口的通告清掉上一请求的值，窗口不会错配给下一个请求），\n        // 供本轮 usage/done 补窗口；丢掉它前端就只剩 200k 假定值（mify 的\n        // 1M 模型因此显示成 200k）。\n        \"request/context\" => {\n            view.context_window = context_window_of(data);\n        }\n        _ => {} // user/message / step/* / system/message / title: UI noise here\n    }\n}\n\n/// `assistant-stream` live frames: start / chunk / end. Chunks carry the\n/// model's raw deltas (text-delta, reasoning-delta, usage, finish, …).\nfn handle_assistant_stream(\n    core: &TurnCore,\n    state: &mut TurnState,\n    view: &mut TurnView,\n    value: &Value,\n) {\n    let frame = value.get(\"frame\").cloned().unwrap_or(Value::Null);\n    match frame.get(\"type\").and_then(Value::as_str) {\n        Some(\"start\") => view.attempt_streamed_text = false,\n        Some(\"chunk\") => {\n            let chunk = frame.get(\"chunk\").cloned().unwrap_or(Value::Null);\n            match chunk.get(\"type\").and_then(Value::as_str) {\n                Some(\"text-delta\") => {\n                    let text = chunk.get(\"text\").and_then(Value::as_str).unwrap_or(\"\");\n                    if !text.is_empty() {\n                        view.attempt_streamed_text = true;\n                        core.dispatch_event(state, EngineEvent::Delta(text.to_string()));\n                    }\n                }\n                Some(\"reasoning-delta\") => {\n                    let text = chunk.get(\"text\").and_then(Value::as_str).unwrap_or(\"\");\n                    if !text.is_empty() {\n                        core.dispatch_event(state, EngineEvent::Thinking(text.to_string()));\n                    }\n                }\n                Some(\"usage\") => {\n                    if let Some(usage) = chunk.get(\"usage\") {\n                        let usage = attach_context_window(usage.clone(), view.context_window);\n                        view.last_usage = Some(usage.clone());\n                        core.dispatch_event(state, EngineEvent::Usage(usage));\n                    }\n                }\n                _ => {} // block-start / block-end / tool-call-delta / finish\n            }\n        }\n        _ => {} // end frames: the durable events settle the turn\n    }\n}\n\n// ==================== $events (approvals / questions) ====================\n\nasync fn handle_events_frame(\n    core: &TurnCore,\n    state: &mut TurnState,\n    view: &mut TurnView,\n    value: &Value,\n    origin: &str,\n) {\n    match value.get(\"type\").and_then(Value::as_str) {\n        // The events client id, required on every $events/result answer.\n        Some(\"ready\") => {\n            if let Some(client_id) = value.get(\"clientId\").and_then(Value::as_str) {\n                view.events_client_id = Some(client_id.to_string());\n            }\n        }\n        Some(\"waterfall\") => {\n            let Some(event_id) = value.get(\"eventId\").and_then(Value::as_str) else {\n                return;\n            };\n            let kind = value.get(\"event\").and_then(Value::as_str).unwrap_or(\"\");\n            let Some(client_id) = view.events_client_id.clone() else {\n                core.dispatch_event(\n                    state,\n                    EngineEvent::Warn(\"收到审批/提问请求但事件通道未就绪，已跳过\".to_string()),\n                );\n                return;\n            };\n            // Questions park host-side until the user answers from the card\n            // (answer_question posts the outcome); approvals keep the v1\n            // auto-allow policy; unknown waterfall kinds reject as before.\n            if kind == \"user-questions/request\" {\n                park_question(core, state, view, value, origin, &client_id, event_id).await;\n                return;\n            }\n            // v1 policy: approvals auto-allow — API-created sessions already\n            // run tools without a permission flow (the headless engine had\n            // the same implicit behavior), and codemoss has no approval UI\n            // for host sessions yet.\n            let (outcome, notice) = if kind == \"approval/request\" {\n                (json!({ \"kind\": \"result\", \"value\": \"allowed-once\" }), None)\n            } else {\n                (\n                    json!({\n                        \"kind\": \"rejected\",\n                        \"error\": { \"code\": \"cancelled\", \"message\": \"the user cancelled ask_user_question\" },\n                    }),\n                    Some(\"已取消一个未识别的交互请求\".to_string()),\n                )\n            };\n            let answered = host_call(\n                origin,\n                \"$events/result\",\n                json!({ \"clientId\": client_id, \"eventId\": event_id, \"outcome\": outcome }),\n            )\n            .await;\n            match (answered, notice) {\n                (Err(_), _) => core.dispatch_event(\n                    state,\n                    EngineEvent::Warn(\"审批/提问应答失败，本轮可能被阻塞\".to_string()),\n                ),\n                (Ok(_), Some(notice)) => {\n                    core.dispatch_event(state, EngineEvent::Warn(notice));\n                }\n                (Ok(_), None) => {}\n            }\n        }\n        // Cancellation of a pending waterfall previously delivered under the\n        // same id: settle the card so it never stays answerable against a\n        // request the host already withdrew.\n        Some(\"cancel\") => {\n            if let Some(event_id) = value.get(\"eventId\").and_then(Value::as_str) {\n                core.dispatch_event(\n                    state,\n                    EngineEvent::QuestionSettled {\n                        request_id: event_id.to_string(),\n                    },\n                );\n            }\n        }\n        _ => {}\n    }\n}\n\n/// Park a `user-questions/request` waterfall: surface the question card and\n/// stash the answer context under the same request id. `$events/result` needs\n/// the origin + clientId + eventId triple plus the original request (question\n/// ids), none of which the UI projection carries — so the parked value is the\n/// answer context, not the render input.\nasync fn park_question(\n    core: &TurnCore,\n    state: &mut TurnState,\n    view: &TurnView,\n    value: &Value,\n    origin: &str,\n    client_id: &str,\n    event_id: &str,\n) {\n    let request = value.get(\"request\").cloned().unwrap_or(Value::Null);\n    // plan-review presentation intent（PRD §5-DSH.6：仅以 intent.kind 识别\n    // 计划）走类型化审批主干，不再折叠进普通问题卡。\n    if let Some(question) = plan_review_question(&request) {\n        park_plan_review(core, state, view, &question, origin, client_id, event_id).await;\n        return;\n    }\n    let questions = render_questions(&request);\n    if questions.is_empty() {\n        // A question nobody can see must not park the host forever: reject\n        // the waterfall and say so.\n        reject_waterfall(origin, client_id, event_id, \"empty question request\").await;\n        core.dispatch_event(\n            state,\n            EngineEvent::Warn(\"收到空的提问请求，已跳过\".to_string()),\n        );\n        return;\n    }\n    core.dispatch_event(\n        state,\n        EngineEvent::Question {\n            request_id: event_id.to_string(),\n            tool_use_id: None,\n            input: json!({ \"questions\": questions }),\n        },\n    );\n    // dispatch_event parked the render input under this request id; overwrite\n    // it with the answer context the answer command actually needs.\n    if let Some(entry) = core.registry.get(&core.run_id) {\n        if let Ok(mut parked) = entry.questions.lock() {\n            parked.insert(\n                event_id.to_string(),\n                json!({\n                    \"dsh\": {\n                        \"origin\": origin,\n                        \"clientId\": client_id,\n                        \"eventId\": event_id,\n                        \"request\": request,\n                    }\n                }),\n            );\n        }\n    }\n}\n/// Reject a waterfall the UI can never answer, so the host does not park\n/// forever on a request we refuse to surface.\nasync fn reject_waterfall(origin: &str, client_id: &str, event_id: &str, message: &str) {\n    let _ = host_call(\n        origin,\n        \"$events/result\",\n        json!({\n            \"clientId\": client_id,\n            \"eventId\": event_id,\n            \"outcome\": {\n                \"kind\": \"rejected\",\n                \"error\": { \"name\": \"UserQuestionError\", \"code\": \"cancelled\", \"message\": message },\n            },\n        }),\n    )\n    .await;\n}\n\n/// plan-review intent 识别（PRD §5-DSH.6：仅以 intent.kind==\"plan-review\"\n/// 识别计划；P0 取证的结构里它是 questions[0]）。\nfn plan_review_question(request: &Value) -> Option<Value> {\n    request\n        .get(\"questions\")?\n        .as_array()?\n        .first()\n        .filter(|question| {\n            question.pointer(\"/intent/kind\").and_then(Value::as_str) == Some(\"plan-review\")\n        })\n        .cloned()\n}\n\n/// 正文首个 markdown 标题（与 dsh-plan-mode firstHeading 同规则：行首\n/// 1-6 个 # + 空白 + 非空文本）；无标题返回 None，调用方给默认名。\nfn first_heading(plan: &str) -> Option<String> {\n    plan.lines().find_map(|line| {\n        let line = line.trim_end();\n        let hashes = line.chars().take_while(|c| *c == '#').count();\n        if !(1..=6).contains(&hashes) {\n            return None;\n        }\n        let rest = &line[hashes..];\n        if !rest.starts_with(char::is_whitespace) {\n            return None;\n        }\n        let title = rest.trim();\n        (!title.is_empty()).then(|| title.to_string())\n    })\n}\n\n/// plan-review presentation intent（P0 取证：dsh-plan-mode exit_plan_mode\n/// 经 userQuestions.ask 下行，questions[0] 的 detail 是完整 markdown、\n/// intent.approve 是原生批准标签）：构造类型化 PlanReview 并 dispatch\n/// PlanReviewReady——落盘赋 revision、native_request 停车由 reader 统一\n/// 处理。原生回复上下文（$events/result 帧）随 context 停在后端注册表，\n/// 事件载荷永不含它。\nasync fn park_plan_review(\n    core: &TurnCore,\n    state: &mut TurnState,\n    view: &TurnView,\n    question: &Value,\n    origin: &str,\n    client_id: &str,\n    event_id: &str,\n) {\n    let content = question\n        .get(\"detail\")\n        .and_then(Value::as_str)\n        .filter(|detail| !detail.trim().is_empty());\n    let approve = question\n        .pointer(\"/intent/approve\")\n        .and_then(Value::as_str)\n        .filter(|label| !label.is_empty());\n    let question_id = question\n        .get(\"id\")\n        .and_then(Value::as_str)\n        .filter(|id| !id.is_empty());\n    let (Some(content), Some(approve), Some(question_id)) = (content, approve, question_id)\n    else {\n        // fail-closed：正文/批准标签/问题 id 缺一都无法构造忠实于原生语义\n        // 的审批——拒绝该 waterfall 让 host 解除阻塞并警告，绝不降级为普通\n        // 问题卡（那会丢失审批语义）。\n        reject_waterfall(origin, client_id, event_id, \"malformed plan-review request\").await;\n        core.dispatch_event(\n            state,\n            EngineEvent::Warn(\n                \"收到残缺的计划评审请求（缺正文/批准标签/问题 id），已拒绝\".to_string(),\n            ),\n        );\n        return;\n    };\n    let title = first_heading(content).unwrap_or_else(|| \"计划评审\".to_string());\n    let content_hash = super::plan_review::content_hash(content);\n    // 回复帧照 question_outcome/answer_question 的既有 $events/result 形状\n    // （{clientId, eventId, outcome:{kind:\"result\", value:{answers:[…]}}}）。\n    // 批准帧：selected=[intent.approve 的真实标签] 且绝不携带 custom 键\n    // （Host 严格判定 selected.length===1 && selected[0]===approve &&\n    // custom===void 0）；反馈帧：selected:[] + custom 占位符，发送时由\n    // respond_plan_review 把占位符替换为用户反馈文本。\n    let outcome = |answers: Value| {\n        json!({\n            \"clientId\": client_id,\n            \"eventId\": event_id,\n            \"outcome\": { \"kind\": \"result\", \"value\": { \"answers\": [answers] } },\n        })\n    };\n    let approve_frame = outcome(json!({ \"id\": question_id, \"selected\": [approve] }));\n    let changes_frame = outcome(\n        json!({ \"id\": question_id, \"selected\": [], \"custom\": super::PLAN_FEEDBACK_PLACEHOLDER }),\n    );\n    let now = super::plan_review::now_ms();\n    let record = super::plan_review::PlanReview {\n        plan_id: format!(\"dsh-plan-{event_id}\"),\n        engine: core.engine_id.clone(),\n        session_id: state.native_session_id.clone().unwrap_or_default(),\n        workspace_path: view.workspace.clone(),\n        run_id: Some(core.run_id.clone()),\n        revision: 0, // dispatch 落盘时赋 revision，适配器不自带\n        title,\n        content: content.to_string(),\n        content_hash: content_hash.clone(),\n        complete: true,\n        review_kind: super::plan_review::PlanReviewKind::NativeRequest,\n        native_plan_id: Some(question_id.to_string()),\n        // plan 是软行为引导：批准后 plan mode 退出，工具调用回到 host 会话\n        // 既有策略（v1 auto-allow），审批本身不改变执行权限。\n        exec_permission: \"auto\".to_string(),\n        status: super::plan_review::PlanStatus::AwaitingReview,\n        execution: super::plan_review::PlanExecution::NotStarted,\n        decision: None,\n        decision_intent_at: None,\n        applied_at: None,\n        created_at: now,\n        updated_at: now,\n        superseded_by: None,\n    };\n    // 停车上下文（respond_plan_review 的读取约定）：route/origin/path/\n    // contentHash/frames 顶层平铺；revision 键由 dispatch 注入，适配器不占。\n    let context = json!({\n        \"route\": \"http\",\n        \"origin\": origin,\n        \"path\": \"$events/result\",\n        \"contentHash\": content_hash,\n        \"frames\": { \"approve\": approve_frame, \"changes\": changes_frame },\n    });\n    core.dispatch_event(\n        state,\n        EngineEvent::PlanReviewReady {\n            record: Box::new(record),\n            context,\n        },\n    );\n}\n\n/// Project a dsh `user-questions/request` payload onto the QuestionSpec shape\n/// the UI renders (the claude control-protocol shape): `header` defaults,\n/// `detail` folds into the question text, options pass through unchanged.\n/// (plan-review intent 的请求在 park_question 入口就被拦截去审批主干，\n/// 永不经过这个映射。) The answer command\n/// re-derives answer keys from the parked original request through this same\n/// mapping, so the two must never drift apart.\npub(crate) fn render_questions(request: &Value) -> Vec<Value> {\n    let Some(questions) = request.get(\"questions\").and_then(Value::as_array) else {\n        return Vec::new();\n    };\n    questions\n        .iter()\n        .map(|question| {\n            let mut text = question\n                .get(\"question\")\n                .and_then(Value::as_str)\n                .unwrap_or(\"\")\n                .to_string();\n            if let Some(detail) = question\n                .get(\"detail\")\n                .and_then(Value::as_str)\n                .filter(|detail| !detail.trim().is_empty())\n            {\n                text = format!(\"{text}\\n\\n{detail}\");\n            }\n            json!({\n                \"question\": text,\n                \"header\": question.get(\"header\").and_then(Value::as_str).unwrap_or(\"提问\"),\n                \"multiSelect\": question.get(\"multiSelect\").and_then(Value::as_bool).unwrap_or(false),\n                \"options\": question.get(\"options\").cloned().unwrap_or_else(|| json!([])),\n            })\n        })\n        .collect()\n}\n\n/// Build the `$events/result` outcome for a parked dsh question. `answers` is\n/// the UI's map (rendered question text → picked label(s)); a free-form\n/// string matching no option label travels as `custom`. `None` (or a\n/// non-object) means the user dismissed the card.\npub(crate) fn question_outcome(request: &Value, answers: Option<&Value>) -> Value {\n    let Some(answers) = answers.and_then(Value::as_object) else {\n        return json!({\n            \"kind\": \"rejected\",\n            \"error\": { \"name\": \"UserQuestionError\", \"code\": \"cancelled\", \"message\": \"the user cancelled ask_user_question\" },\n        });\n    };\n    let rendered = render_questions(request);\n    let questions = request\n        .get(\"questions\")\n        .and_then(Value::as_array)\n        .cloned()\n        .unwrap_or_default();\n    let mut items = Vec::new();\n    for (index, question) in questions.iter().enumerate() {\n        let id = question\n            .get(\"id\")\n            .and_then(Value::as_str)\n            .unwrap_or(\"\")\n            .to_string();\n        // Answers key on the rendered question text (detail folded in), so\n        // re-derive the same key rather than trusting the raw question.\n        let key = rendered\n            .get(index)\n            .and_then(|r| r.get(\"question\"))\n            .and_then(Value::as_str)\n            .unwrap_or(\"\");\n        let known_labels: Vec<&str> = question\n            .get(\"options\")\n            .and_then(Value::as_array)\n            .map(|options| {\n                options\n                    .iter()\n                    .filter_map(|o| o.get(\"label\").and_then(Value::as_str))\n                    .collect()\n            })\n            .unwrap_or_default();\n        let item = match answers.get(key) {\n            Some(Value::Array(labels)) => json!({ \"id\": id, \"selected\": labels }),\n            Some(Value::String(text)) if known_labels.contains(&text.as_str()) => {\n                json!({ \"id\": id, \"selected\": [text] })\n            }\n            Some(Value::String(text)) => {\n                json!({ \"id\": id, \"selected\": [], \"custom\": text })\n            }\n            _ => json!({ \"id\": id, \"selected\": [] }),\n        };\n        items.push(item);\n    }\n    json!({ \"kind\": \"result\", \"value\": { \"answers\": items } })\n}\n\n// ==================== transport helpers ====================\n\nasync fn mux_connect(origin: &str, cookie: Option<&str>) -> Result<Ws, String> {\n    let authority = origin\n        .strip_prefix(\"http://\")\n        .or_else(|| origin.strip_prefix(\"https://\"))\n        .unwrap_or(origin);\n    let mut request = format!(\"ws://{authority}/api/remote.mux\")\n        .into_client_request()\n        .map_err(|error| format!(\"dsh 会话流地址无效：{error}\"))?;\n    if let Some(value) = cookie.and_then(|cookie| cookie.parse().ok()) {\n        request\n            .headers_mut()\n            .insert(tokio_tungstenite::tungstenite::http::header::COOKIE, value);\n    }\n    let (stream, _response) = tokio_tungstenite::connect_async(request)\n        .await\n        .map_err(|error| format!(\"dsh 会话流连接失败（{origin}）：{error}\"))?;\n    Ok(stream)\n}\n\nasync fn ws_send(ws: &mut Ws, payload: Value) -> Result<(), String> {\n    ws.send(Message::Text(payload.to_string().into()))\n        .await\n        .map_err(|error| format!(\"dsh 会话流发送失败：{error}\"))\n}\n\n/// Streams opened on the mux: the events clientId plus the plan projection\n/// read off the follow snapshot (plan 权限下区分 /plan noop 与 committed —\n/// 已激活时不会再有 plan/mode 事件可回读）。\nstruct StreamsOpened {\n    events_client_id: Option<String>,\n    /// follow 快照里 plan 投影的 active 位（dsh-plan-mode wire view\n    /// {active, pending}）；快照缺失或投影未注册时为 false。\n    plan_active: bool,\n}\n\n/// Open both logical streams and wait for the follow snapshot (proof the\n/// follow subscription is live) AND the `$events` ready frame (its clientId\n/// heads every `$events/result` answer) before the caller dispatches the\n/// prompt — with a bounded fallback so a gateway that skips either cannot\n/// stall sends. Returns the events clientId when the ready frame arrived in\n/// time; a late ready frame is still picked up by the main loop.\nasync fn ws_open_and_wait(ws: &mut Ws, session_id: &str) -> StreamsOpened {\n    let opened = async {\n        ws_send(\n            ws,\n            json!({\n                \"type\": \"open\",\n                \"streamId\": STREAM_FOLLOW,\n                \"endpoint\": \"session/follow\",\n                \"payload\": { \"args\": { \"request\": {\n                    \"address\": { \"kind\": \"session\", \"sessionId\": session_id },\n                    \"maxMessages\": FOLLOW_MAX_MESSAGES,\n                    \"assistantStream\": true,\n                } } },\n            }),\n        )\n        .await?;\n        ws_send(\n            ws,\n            json!({\n                \"type\": \"open\",\n                \"streamId\": STREAM_EVENTS,\n                \"endpoint\": \"$events\",\n                \"payload\": { \"args\": {} },\n            }),\n        )\n        .await\n    };\n    if let Err(error) = opened.await {\n        eprintln!(\"[dsh] mux stream open failed: {error}\");\n        return StreamsOpened {\n            events_client_id: None,\n            plan_active: false,\n        };\n    }\n    let mut follow_ready = false;\n    let mut events_client_id: Option<String> = None;\n    let mut plan_active = false;\n    let started = tokio::time::Instant::now();\n    while started.elapsed() < FOLLOW_READY_TIMEOUT && !(follow_ready && events_client_id.is_some())\n    {\n        let next = tokio::time::timeout(FOLLOW_READY_TIMEOUT - started.elapsed(), ws.next()).await;\n        match next {\n            Ok(Some(Ok(Message::Text(text)))) => {\n                let Ok(value) = serde_json::from_str::<Value>(text.as_str()) else {\n                    continue;\n                };\n                if value.get(\"type\").and_then(Value::as_str) != Some(\"item\") {\n                    continue;\n                }\n                match value.get(\"streamId\").and_then(Value::as_str) {\n                    Some(STREAM_FOLLOW)\n                        if value.pointer(\"/value/type\").and_then(Value::as_str)\n                            == Some(\"snapshot\") =>\n                    {\n                        follow_ready = true;\n                        // plan 投影的裁剪视图 {active, pending}（dsh-plan-mode\n                        // planProjectionDefinition wire）；缺失即未注册插件。\n                        plan_active = value\n                            .pointer(\"/value/projections/values/plan/active\")\n                            .and_then(Value::as_bool)\n                            .unwrap_or(false);\n                    }\n                    Some(STREAM_EVENTS)\n                        if value.pointer(\"/value/type\").and_then(Value::as_str)\n                            == Some(\"ready\") =>\n                    {\n                        events_client_id = value\n                            .pointer(\"/value/clientId\")\n                            .and_then(Value::as_str)\n                            .map(str::to_string);\n                    }\n                    _ => {}\n                }\n            }\n            Ok(Some(Ok(_))) | Ok(Some(Err(_))) | Ok(None) | Err(_) => break,\n        }\n    }\n    StreamsOpened {\n        events_client_id,\n        plan_active,\n    }\n}\n\nfn message_text(data: &Value) -> String {\n    data.pointer(\"/message/content\")\n        .and_then(Value::as_array)\n        .map(|blocks| {\n            blocks\n                .iter()\n                .filter(|block| block.get(\"type\").and_then(Value::as_str) == Some(\"text\"))\n                .filter_map(|block| block.get(\"text\").and_then(Value::as_str))\n                .collect::<Vec<_>>()\n                .join(\"\")\n        })\n        .unwrap_or_default()\n}\n\nfn client_time_zone() -> String {\n    std::env::var(\"TZ\")\n        .ok()\n        .map(|tz| tz.trim_matches('\"').trim().to_string())\n        .filter(|tz| !tz.is_empty() && tz.contains('/'))\n        .unwrap_or_else(|| \"UTC\".to_string())\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use crate::engine::ProcessRegistry;\n    use crate::event_sink::{Emit, EventSink};\n    use std::path::PathBuf;\n    use std::sync::Mutex as StdMutex;\n\n    /// Test emitter collecting flushed event JSON for assertions.\n    struct CollectingEmitter(StdMutex<Vec<String>>);\n\n    impl Emit for CollectingEmitter {\n        fn emit_json(&self, _name: &str, raw_json: &str) {\n            self.0.lock().unwrap().push(raw_json.to_string());\n        }\n    }\n\n    #[tokio::test]\n    async fn tool_messages_preserve_call_id_in_emitted_payloads() {\n        let emitter = Arc::new(CollectingEmitter(StdMutex::new(Vec::new())));\n        let core = TurnCore {\n            sink: EventSink::new(emitter.clone()),\n            registry: Arc::new(ProcessRegistry::default()),\n            engine_id: \"dsh\".to_string(),\n            run_id: \"test-run\".to_string(),\n            db: None,\n            followup: None,\n        };\n        let mut state = TurnState::new(None);\n        let mut view = TurnView::default();\n\n        handle_session_event(\n            &core,\n            &mut state,\n            &mut view,\n            \"tool/call\",\n            &json!({\n                \"callId\": \"call-17\",\n                \"name\": \"bash\",\n                \"arguments\": { \"command\": \"pnpm test\" }\n            }),\n        );\n        handle_session_event(\n            &core,\n            &mut state,\n            &mut view,\n            \"tool/result\",\n            &json!({\n                \"message\": {\n                    \"source\": { \"callId\": \"call-17\" },\n                    \"content\": [{ \"type\": \"text\", \"text\": \"done\", \"isError\": false }]\n                }\n            }),\n        );\n        core.sink.flush();\n\n        let events = emitter.0.lock().unwrap().clone();\n        let messages: Vec<Value> = collect_kinds(&events)\n            .into_iter()\n            .filter_map(|(kind, data)| (kind == \"message\").then_some(data))\n            .collect();\n        assert_eq!(messages.len(), 2);\n        assert!(messages\n            .iter()\n            .all(|data| data.get(\"toolCallId\").and_then(Value::as_str) == Some(\"call-17\")));\n    }\n\n    /// End-to-end against the configured local host (skipped by default):\n    /// `cargo test --lib dsh_session -- --ignored --nocapture`.\n    /// Proves the full chain: ensure host → workspace/session → prompt →\n    /// assistantStream deltas → done, with session + usage events present.\n    #[tokio::test]\n    #[ignore = \"needs a running dsh host at the configured origin\"]\n    async fn streams_a_live_host_turn() {\n        let emitter = Arc::new(CollectingEmitter(StdMutex::new(Vec::new())));\n        let sink = EventSink::new(emitter.clone());\n        let core = TurnCore {\n            sink,\n            registry: Arc::new(ProcessRegistry::default()),\n            engine_id: \"dsh\".to_string(),\n            run_id: \"test-run\".to_string(),\n            db: None,\n            followup: None,\n        };\n        let req = SendRequest {\n            session_id: None,\n            workspace: PathBuf::from(\"/tmp\"),\n            prompt: \"用一句话回答：1+1等于几？\".to_string(),\n            prompt_contributions: Vec::new(),\n            native_compact: false,\n            images: Vec::new(),\n            model: None,\n            effort: None,\n            service_tier: None,\n            permission: None,\n            additional_dirs: Vec::new(),\n            provider_id: None,\n            computer_use: None,\n            memory_bot: None,\n            allowed_tools: None,\n        };\n        run_host_turn(\n            core,\n            req,\n            Arc::new(crate::dsh_host::DshHostState::default()),\n            Arc::new(AtomicBool::new(false)),\n            4_000_000_001,\n        )\n        .await;\n\n        let events = emitter.0.lock().unwrap().clone();\n        for raw in &events {\n            println!(\"event: {raw}\");\n        }\n        assert!(!events.is_empty(), \"no events flushed\");\n        // The sink batches each flush as a JSON array of events.\n        let mut kinds: Vec<(String, Value)> = Vec::new();\n        for raw in &events {\n            let flushed: Value = serde_json::from_str(raw).expect(\"flushed batch must be JSON\");\n            let batch = flushed.as_array().cloned().unwrap_or_else(|| vec![flushed]);\n            for value in batch {\n                kinds.push((\n                    value\n                        .get(\"kind\")\n                        .and_then(Value::as_str)\n                        .unwrap_or(\"\")\n                        .to_string(),\n                    value.get(\"data\").cloned().unwrap_or(Value::Null),\n                ));\n            }\n        }\n        let session = kinds\n            .iter()\n            .find(|(kind, _)| kind == \"session\")\n            .map(|(_, data)| data.as_str().unwrap_or(\"\").to_string());\n        let session = session.expect(\"session id must be announced\");\n        assert!(\n            session.starts_with(\"session-\"),\n            \"unexpected session id {session}\"\n        );\n        let deltas: String = kinds\n            .iter()\n            .filter(|(kind, _)| kind == \"delta\")\n            .filter_map(|(_, data)| data.as_str())\n            .collect();\n        assert!(!deltas.trim().is_empty(), \"no streamed deltas: {kinds:?}\");\n        assert!(\n            kinds.iter().any(|(kind, _)| kind == \"done\"),\n            \"turn never settled: {kinds:?}\"\n        );\n        assert!(\n            !kinds.iter().any(|(kind, _)| kind == \"error\"),\n            \"unexpected error event: {kinds:?}\"\n        );\n    }\n\n    /// Resume + tools: turn 2 reuses turn 1's session id (codemoss passes it\n    /// back as `session_id`), runs a tool, and projects a tool row plus its\n    /// result patch. Same live-host gate as `streams_a_live_host_turn`.\n    #[tokio::test]\n    #[ignore = \"needs a running dsh host at the configured origin\"]\n    async fn resumes_session_and_streams_tool_rows() {\n        let run = |session_id: Option<String>, prompt: &str| {\n            let prompt = prompt.to_string();\n            async move {\n                let emitter = Arc::new(CollectingEmitter(StdMutex::new(Vec::new())));\n                let core = TurnCore {\n                    sink: EventSink::new(emitter.clone()),\n                    registry: Arc::new(ProcessRegistry::default()),\n                    engine_id: \"dsh\".to_string(),\n                    run_id: \"test-run\".to_string(),\n                    db: None,\n                    followup: None,\n                };\n                let req = SendRequest {\n                    session_id,\n                    workspace: PathBuf::from(\"/tmp\"),\n                    prompt,\n                    prompt_contributions: Vec::new(),\n                    native_compact: false,\n                    images: Vec::new(),\n                    model: None,\n                    effort: None,\n                    service_tier: None,\n                    permission: None,\n                    additional_dirs: Vec::new(),\n                    provider_id: None,\n                    computer_use: None,\n                    memory_bot: None,\n                    allowed_tools: None,\n                };\n                run_host_turn(\n                    core,\n                    req,\n                    Arc::new(crate::dsh_host::DshHostState::default()),\n                    Arc::new(AtomicBool::new(false)),\n                    4_000_000_002,\n                )\n                .await;\n                let events = emitter.0.lock().unwrap().clone();\n                let kinds = collect_kinds(&events);\n                (kinds, announced_session(&events))\n            }\n        };\n\n        let (kinds1, session_id) = run(None, \"用一句话回答：天空为什么是蓝色的？\").await;\n        assert!(\n            !session_id.is_empty(),\n            \"turn 1 announced no session: {kinds1:?}\"\n        );\n        assert!(\n            !kinds1.iter().any(|(kind, _)| kind == \"error\"),\n            \"turn 1 errored: {kinds1:?}\"\n        );\n\n        // Resume: every payload must carry the session id from the first\n        // event on (TurnState preseeded), and the tool row must stream.\n        let (kinds2, session_id2) = run(\n            Some(session_id.clone()),\n            \"请用 bash 工具执行命令 echo codemoss-stream-check，然后告诉我输出内容。\",\n        )\n        .await;\n        assert_eq!(\n            session_id2, session_id,\n            \"resumed turn changed the session id\"\n        );\n        assert!(\n            kinds2.iter().any(|(kind, data)| kind == \"message\"\n                && data.get(\"role\").and_then(Value::as_str) == Some(\"tool\")),\n            \"no tool row streamed: {kinds2:?}\"\n        );\n        assert!(\n            kinds2.iter().any(|(kind, data)| kind == \"message\"\n                && data.get(\"patch\").and_then(Value::as_bool) == Some(true)\n                && data.get(\"result\").is_some()),\n            \"no tool result patch: {kinds2:?}\"\n        );\n        assert!(kinds2.iter().any(|(kind, _)| kind == \"done\"), \"{kinds2:?}\");\n        assert!(\n            !kinds2.iter().any(|(kind, _)| kind == \"error\"),\n            \"turn 2 errored: {kinds2:?}\"\n        );\n    }\n\n    /// A TurnCore with a registry entry under its run id (so question parking\n    /// has somewhere to land) plus the collected flushes for assertions.\n    fn test_core() -> (TurnCore, Arc<ProcessRegistry>, Arc<CollectingEmitter>) {\n        let emitter = Arc::new(CollectingEmitter(StdMutex::new(Vec::new())));\n        let registry = Arc::new(ProcessRegistry::default());\n        registry.insert(\n            \"test-run\".to_string(),\n            crate::engine::registry::ChildEntry {\n                child: None,\n                pid: 4_000_000_099,\n                run_id: \"test-run\".to_string(),\n                killed: Arc::new(AtomicBool::new(false)),\n                reader_abort: Arc::new(std::sync::OnceLock::new()),\n                stdin: None,\n                questions: Arc::new(StdMutex::new(HashMap::new())),\n                plans: Arc::new(StdMutex::new(HashMap::new())),\n            },\n        );\n        let core = TurnCore {\n            sink: EventSink::new(emitter.clone()),\n            registry: Arc::clone(&registry),\n            engine_id: \"dsh\".to_string(),\n            run_id: \"test-run\".to_string(),\n            db: None,\n            followup: None,\n        };\n        (core, registry, emitter)\n    }\n\n    #[test]\n    fn render_questions_maps_the_dsh_shape_onto_the_card_spec() {\n        let request = json!({\n            \"questions\": [\n                {\n                    \"id\": \"q1\",\n                    \"question\": \"选哪个？\",\n                    \"header\": \"方案\",\n                    \"multiSelect\": true,\n                    \"options\": [{ \"label\": \"A\", \"description\": \"a\" }, { \"label\": \"B\" }],\n                },\n                {\n                    \"id\": \"q2\",\n                    \"question\": \"为什么选这个方案？\",\n                    \"detail\": \"背景：上一轮评审要求收紧范围\",\n                    // no header / options: defaults kick in\n                },\n            ]\n        });\n        let rendered = render_questions(&request);\n        assert_eq!(rendered.len(), 2);\n        assert_eq!(rendered[0][\"question\"], \"选哪个？\");\n        assert_eq!(rendered[0][\"header\"], \"方案\");\n        assert_eq!(rendered[0][\"multiSelect\"], true);\n        assert_eq!(rendered[0][\"options\"][0][\"label\"], \"A\");\n        // 普通问题的 detail 仍折叠进问题文本；plan-review intent 的请求不\n        // 走这个映射（park_question 入口拦截，见审批主干测试）。\n        assert_eq!(\n            rendered[1][\"question\"],\n            \"为什么选这个方案？\\n\\n背景：上一轮评审要求收紧范围\"\n        );\n        assert_eq!(rendered[1][\"header\"], \"提问\");\n        assert_eq!(rendered[1][\"multiSelect\"], false);\n        assert_eq!(rendered[1][\"options\"], json!([]));\n        assert_eq!(render_questions(&json!({})), Vec::<Value>::new());\n        // 仅 intent.kind==\"plan-review\" 被识别为计划评审；普通 intent 或缺\n        // intent 的请求仍走旧问题路径。\n        assert!(plan_review_question(&request).is_none());\n        let review_request = json!({\n            \"questions\": [{\n                \"id\": \"plan-review\",\n                \"question\": \"Approve this plan and leave plan mode?\",\n                \"detail\": \"# 计划\\nstep 1\",\n                \"intent\": { \"kind\": \"plan-review\", \"approve\": \"Approve\" },\n            }]\n        });\n        assert!(plan_review_question(&review_request).is_some());\n        let other_intent = json!({\n            \"questions\": [{ \"id\": \"q\", \"question\": \"x\", \"intent\": { \"kind\": \"confirm\" } }]\n        });\n        assert!(plan_review_question(&other_intent).is_none());\n    }\n\n    #[test]\n    fn question_outcome_maps_labels_custom_and_dismiss() {\n        let request = json!({\n            \"questions\": [\n                { \"id\": \"q1\", \"question\": \"单选\", \"options\": [{ \"label\": \"A\" }, { \"label\": \"B\" }] },\n                { \"id\": \"q2\", \"question\": \"多选\", \"multiSelect\": true,\n                  \"options\": [{ \"label\": \"x\" }, { \"label\": \"y\" }] },\n                { \"id\": \"q3\", \"question\": \"自由\", \"options\": [{ \"label\": \"A\" }] },\n            ]\n        });\n        let answers = json!({ \"单选\": \"A\", \"多选\": [\"x\", \"y\"], \"自由\": \"随便写写\" });\n        let outcome = question_outcome(&request, Some(&answers));\n        assert_eq!(outcome[\"kind\"], \"result\");\n        assert_eq!(\n            outcome[\"value\"][\"answers\"][0],\n            json!({ \"id\": \"q1\", \"selected\": [\"A\"] })\n        );\n        assert_eq!(\n            outcome[\"value\"][\"answers\"][1],\n            json!({ \"id\": \"q2\", \"selected\": [\"x\", \"y\"] })\n        );\n        // Free-form text matching no option label travels as custom.\n        assert_eq!(\n            outcome[\"value\"][\"answers\"][2],\n            json!({ \"id\": \"q3\", \"selected\": [], \"custom\": \"随便写写\" })\n        );\n        // Dismissed card → cancelled rejection.\n        let dismissed = question_outcome(&request, None);\n        assert_eq!(dismissed[\"kind\"], \"rejected\");\n        assert_eq!(dismissed[\"error\"][\"code\"], \"cancelled\");\n        // An unanswered question still echoes its id with an empty selection.\n        let partial = question_outcome(&request, Some(&json!({})));\n        assert_eq!(\n            partial[\"value\"][\"answers\"][0],\n            json!({ \"id\": \"q1\", \"selected\": [] })\n        );\n    }\n\n    #[tokio::test]\n    async fn question_waterfall_emits_card_and_parks_answer_context() {\n        let (core, registry, emitter) = test_core();\n        let mut state = TurnState::new(None);\n        let mut view = TurnView {\n            events_client_id: Some(\"client-1\".to_string()),\n            ..TurnView::default()\n        };\n        let frame = json!({\n            \"type\": \"waterfall\",\n            \"event\": \"user-questions/request\",\n            \"eventId\": \"evt-1\",\n            \"agentId\": \"agent-1\",\n            \"request\": {\n                \"questions\": [\n                    { \"id\": \"q1\", \"question\": \"选哪个？\", \"options\": [{ \"label\": \"A\" }, { \"label\": \"B\" }] }\n                ]\n            },\n        });\n        handle_events_frame(\n            &core,\n            &mut state,\n            &mut view,\n            &frame,\n            \"http://127.0.0.1:3080\",\n        )\n        .await;\n        core.sink.flush();\n\n        // Card pushed to the UI…\n        let kinds = collect_kinds(&emitter.0.lock().unwrap());\n        let question = kinds\n            .iter()\n            .find(|(kind, _)| kind == \"question\")\n            .map(|(_, data)| data.clone())\n            .expect(\"no question event pushed\");\n        assert_eq!(question[\"requestId\"], \"evt-1\");\n        assert_eq!(question[\"input\"][\"questions\"][0][\"question\"], \"选哪个？\");\n        // …and the answer context parked under the same request id.\n        let parked = registry\n            .get(\"test-run\")\n            .and_then(|entry| {\n                entry\n                    .questions\n                    .lock()\n                    .ok()\n                    .and_then(|q| q.get(\"evt-1\").cloned())\n            })\n            .expect(\"answer context not parked\");\n        assert_eq!(parked[\"dsh\"][\"origin\"], \"http://127.0.0.1:3080\");\n        assert_eq!(parked[\"dsh\"][\"clientId\"], \"client-1\");\n        assert_eq!(parked[\"dsh\"][\"eventId\"], \"evt-1\");\n        assert_eq!(parked[\"dsh\"][\"request\"][\"questions\"][0][\"id\"], \"q1\");\n    }\n\n    #[tokio::test]\n    async fn waterfall_without_events_channel_warns_and_parks_nothing() {\n        let (core, registry, emitter) = test_core();\n        let mut state = TurnState::new(None);\n        let mut view = TurnView::default(); // no events_client_id\n        let frame = json!({\n            \"type\": \"waterfall\",\n            \"event\": \"user-questions/request\",\n            \"eventId\": \"evt-2\",\n            \"request\": { \"questions\": [{ \"id\": \"q1\", \"question\": \"x\" }] },\n        });\n        handle_events_frame(\n            &core,\n            &mut state,\n            &mut view,\n            &frame,\n            \"http://127.0.0.1:3080\",\n        )\n        .await;\n        core.sink.flush();\n        let kinds = collect_kinds(&emitter.0.lock().unwrap());\n        assert!(kinds.iter().any(|(kind, _)| kind == \"warn\"), \"{kinds:?}\");\n        assert!(\n            !kinds.iter().any(|(kind, _)| kind == \"question\"),\n            \"{kinds:?}\"\n        );\n        let empty = registry\n            .get(\"test-run\")\n            .map(|entry| entry.questions.lock().map(|q| q.is_empty()).unwrap_or(true));\n        assert_eq!(empty, Some(true));\n    }\n\n    #[tokio::test]\n    async fn waterfall_cancel_frame_settles_the_card() {\n        let (core, _registry, emitter) = test_core();\n        let mut state = TurnState::new(None);\n        let mut view = TurnView {\n            events_client_id: Some(\"client-1\".to_string()),\n            ..TurnView::default()\n        };\n        let frame = json!({\n            \"type\": \"waterfall\",\n            \"event\": \"user-questions/request\",\n            \"eventId\": \"evt-3\",\n            \"request\": { \"questions\": [{ \"id\": \"q1\", \"question\": \"x\", \"options\": [{ \"label\": \"A\" }] }] },\n        });\n        handle_events_frame(\n            &core,\n            &mut state,\n            &mut view,\n            &frame,\n            \"http://127.0.0.1:3080\",\n        )\n        .await;\n        handle_events_frame(\n            &core,\n            &mut state,\n            &mut view,\n            &json!({ \"type\": \"cancel\", \"eventId\": \"evt-3\" }),\n            \"http://127.0.0.1:3080\",\n        )\n        .await;\n        core.sink.flush();\n        let kinds = collect_kinds(&emitter.0.lock().unwrap());\n        assert!(\n            kinds\n                .iter()\n                .any(|(kind, data)| kind == \"question_settled\" && data[\"requestId\"] == \"evt-3\"),\n            \"{kinds:?}\"\n        );\n    }\n    /// plan-review intent（P0 取证结构）→ 类型化 PlanReview 记录 + 停车的\n    /// 原生回复帧：批准帧 selected=[intent.approve] 且无 custom 键，反馈帧\n    /// selected:[] + custom 占位符；批准标签来自 intent.approve（这里故意\n    /// 用非英文标签），标题取正文首个 markdown 标题。\n    #[tokio::test]\n    async fn plan_review_intent_builds_record_and_parks_native_frames() {\n        let (core, registry, emitter) = test_core();\n        let mut state = TurnState::new(Some(\"session-1\".to_string()));\n        let mut view = TurnView {\n            events_client_id: Some(\"client-1\".to_string()),\n            workspace: \"/tmp/ws\".to_string(),\n            ..TurnView::default()\n        };\n        let content = \"# 上线计划\\n\\n1. 迁移数据库\\n2. 灰度发布\";\n        let frame = json!({\n            \"type\": \"waterfall\",\n            \"event\": \"user-questions/request\",\n            \"eventId\": \"evt-plan-1\",\n            \"agentId\": \"session-1\",\n            \"request\": {\n                \"questions\": [{\n                    \"id\": \"plan-review\",\n                    \"header\": \"Plan review\",\n                    \"question\": \"Approve this plan and leave plan mode?\",\n                    \"detail\": content,\n                    \"options\": [\n                        { \"label\": \"批准执行\", \"description\": \"Leave plan mode\" },\n                        { \"label\": \"继续规划\", \"description\": \"Stay in plan mode\" },\n                    ],\n                    \"intent\": { \"kind\": \"plan-review\", \"approve\": \"批准执行\" },\n                }]\n            },\n        });\n        handle_events_frame(\n            &core,\n            &mut state,\n            &mut view,\n            &frame,\n            \"http://127.0.0.1:3080\",\n        )\n        .await;\n        core.sink.flush();\n\n        // 走审批主干：有 plan_review 事件，没有普通 question 卡。\n        let kinds = collect_kinds(&emitter.0.lock().unwrap());\n        assert!(\n            !kinds.iter().any(|(kind, _)| kind == \"question\"),\n            \"plan-review 不得走普通问题路径: {kinds:?}\"\n        );\n        let record = kinds\n            .iter()\n            .find(|(kind, _)| kind == \"plan_review\")\n            .map(|(_, data)| data.clone())\n            .expect(\"no plan_review event pushed\");\n        assert_eq!(record[\"planId\"], \"dsh-plan-evt-plan-1\");\n        assert_eq!(record[\"engine\"], \"dsh\");\n        assert_eq!(record[\"sessionId\"], \"session-1\");\n        assert_eq!(record[\"workspacePath\"], \"/tmp/ws\");\n        assert_eq!(record[\"title\"], \"上线计划\");\n        assert_eq!(record[\"content\"], content);\n        assert_eq!(\n            record[\"contentHash\"],\n            crate::engine::plan_review::content_hash(content)\n        );\n        assert_eq!(record[\"complete\"], true);\n        assert_eq!(record[\"reviewKind\"], \"native_request\");\n        assert_eq!(record[\"nativePlanId\"], \"plan-review\");\n        assert_eq!(record[\"status\"], \"awaiting_review\");\n        // 事件载荷永不含原生回复上下文。\n        assert!(record.get(\"frames\").is_none(), \"{record}\");\n        assert!(record.get(\"context\").is_none(), \"{record}\");\n\n        // 停车上下文：{revision, route, origin, path, contentHash, frames}\n        // 顶层平铺（revision 由 dispatch 注入；测试无 db，保持 0）。\n        let parked = registry\n            .get(\"test-run\")\n            .and_then(|entry| {\n                entry\n                    .plans\n                    .lock()\n                    .ok()\n                    .and_then(|plans| plans.get(\"dsh-plan-evt-plan-1\").cloned())\n            })\n            .expect(\"native reply context not parked\");\n        assert_eq!(parked[\"revision\"], 0);\n        assert_eq!(parked[\"route\"], \"http\");\n        assert_eq!(parked[\"origin\"], \"http://127.0.0.1:3080\");\n        assert_eq!(parked[\"path\"], \"$events/result\");\n        assert_eq!(\n            parked[\"contentHash\"],\n            crate::engine::plan_review::content_hash(content)\n        );\n        // 批准帧：$events/result 既有形状，selected=[intent.approve 的真实\n        // 标签]，且绝不携带 custom 键（Host 严格判定 custom===void 0）。\n        let approve = &parked[\"frames\"][\"approve\"];\n        assert_eq!(approve[\"clientId\"], \"client-1\");\n        assert_eq!(approve[\"eventId\"], \"evt-plan-1\");\n        assert_eq!(\n            approve[\"outcome\"],\n            json!({\n                \"kind\": \"result\",\n                \"value\": { \"answers\": [{ \"id\": \"plan-review\", \"selected\": [\"批准执行\"] }] },\n            })\n        );\n        assert!(\n            !approve.to_string().contains(\"custom\"),\n            \"approve frame must not carry a custom key: {approve}\"\n        );\n        // 反馈帧：selected:[] + custom 占位符（发送时替换为用户反馈）。\n        let changes = &parked[\"frames\"][\"changes\"];\n        assert_eq!(\n            changes[\"outcome\"],\n            json!({\n                \"kind\": \"result\",\n                \"value\": { \"answers\": [{\n                    \"id\": \"plan-review\",\n                    \"selected\": [],\n                    \"custom\": crate::engine::PLAN_FEEDBACK_PLACEHOLDER,\n                }] },\n            })\n        );\n    }\n\n    /// 残缺的 plan-review 请求（缺 intent.approve）fail-closed：拒绝\n    /// waterfall + 警告，不落 plan_review 事件、不停车、不降级为问题卡。\n    #[tokio::test]\n    async fn malformed_plan_review_is_rejected_fail_closed() {\n        let (core, registry, emitter) = test_core();\n        let mut state = TurnState::new(Some(\"session-1\".to_string()));\n        let mut view = TurnView {\n            events_client_id: Some(\"client-1\".to_string()),\n            ..TurnView::default()\n        };\n        let frame = json!({\n            \"type\": \"waterfall\",\n            \"event\": \"user-questions/request\",\n            \"eventId\": \"evt-plan-2\",\n            \"request\": {\n                \"questions\": [{\n                    \"id\": \"plan-review\",\n                    \"question\": \"Approve?\",\n                    \"detail\": \"# 计划\\nstep 1\",\n                    \"intent\": { \"kind\": \"plan-review\" },\n                }]\n            },\n        });\n        handle_events_frame(\n            &core,\n            &mut state,\n            &mut view,\n            &frame,\n            \"http://127.0.0.1:3080\",\n        )\n        .await;\n        core.sink.flush();\n        let kinds = collect_kinds(&emitter.0.lock().unwrap());\n        assert!(kinds.iter().any(|(kind, _)| kind == \"warn\"), \"{kinds:?}\");\n        assert!(\n            !kinds\n                .iter()\n                .any(|(kind, _)| kind == \"plan_review\" || kind == \"question\"),\n            \"{kinds:?}\"\n        );\n        let empty = registry\n            .get(\"test-run\")\n            .map(|entry| entry.plans.lock().map(|plans| plans.is_empty()).unwrap_or(true));\n        assert_eq!(empty, Some(true));\n    }\n\n    /// commands 应答分类：undefined（线上 null/缺 commandId）≠ 成功；\n    /// handler 级 error 同样拒绝；commands/list 的 plan 探测。\n    #[test]\n    fn commands_results_are_not_http_success() {\n        // 未知命令 → undefined → 线上 null：HTTP 200 也不算成功。\n        assert!(plan_execute_outcome(&Value::Null).is_err());\n        assert!(plan_execute_outcome(&json!({})).is_err());\n        assert!(plan_execute_outcome(&json!({ \"result\": { \"kind\": \"success\" } })).is_err());\n        // handler 级错误（如 /plan off 携带附件）受控拒绝并带原文。\n        let error = plan_execute_outcome(\n            &json!({ \"commandId\": \"cmd-1\", \"result\": { \"kind\": \"error\", \"text\": \"boom\" } }),\n        )\n        .unwrap_err();\n        assert!(error.contains(\"boom\"), \"{error}\");\n        assert!(plan_execute_outcome(\n            &json!({ \"commandId\": \"cmd-1\", \"result\": { \"kind\": \"success\", \"text\": \"Plan mode on.\" } }),\n        )\n        .is_ok());\n        // commands/list：无 plan = 插件未组合。\n        assert!(plan_command_listed(\n            &json!([{ \"name\": \"plan\", \"description\": \"Enter or leave plan mode\" }])\n        ));\n        assert!(!plan_command_listed(&json!([{ \"name\": \"compact\" }])));\n        assert!(!plan_command_listed(&json!([])));\n        assert!(!plan_command_listed(&Value::Null));\n    }\n\n    /// 标题取正文首个 markdown 标题（与 dsh-plan-mode firstHeading 同\n    /// 规则）；无标题时记录标题回退为「计划评审」。\n    #[test]\n    fn first_heading_matches_the_native_rule() {\n        assert_eq!(first_heading(\"# 标题\\nbody\"), Some(\"标题\".to_string()));\n        assert_eq!(first_heading(\"前言\\n## 二节\"), Some(\"二节\".to_string()));\n        assert_eq!(first_heading(\"###### 六级\"), Some(\"六级\".to_string()));\n        assert_eq!(first_heading(\"####### 七级\"), None);\n        assert_eq!(first_heading(\"#no-space\"), None);\n        assert_eq!(first_heading(\"# \"), None);\n        assert_eq!(first_heading(\"no heading at all\"), None);\n    }\n\n    /// The host announces the request's real window on `request/context`\n    /// (`RequestContext { provider, model, contextWindow? }` — the only carrier\n    /// of a window in DSH's published session events; `session/modelCatalog`\n    /// entries and `TokenUsage` both carry none). Dropping it left the UI on\n    /// the 200k assumed fallback, so a 1M-capable provider (mify's\n    /// `tongyi/deepseek-v4.1-flash`, contextWindow: 1000000) read as 200k.\n    #[tokio::test]\n    async fn request_context_window_reaches_usage_events() {\n        let (core, _registry, emitter) = test_core();\n        let mut state = TurnState::new(None);\n        let mut view = TurnView::default();\n\n        // The host's window announcement, before the turn's usage chunk.\n        handle_session_event(\n            &core,\n            &mut state,\n            &mut view,\n            \"request/context\",\n            &json!({\n                \"provider\": \"mify\",\n                \"model\": \"tongyi/deepseek-v4.1-flash\",\n                \"contextWindow\": 1_000_000\n            }),\n        );\n        handle_assistant_stream(\n            &core,\n            &mut state,\n            &mut view,\n            &json!({\n                \"type\": \"assistant-stream\",\n                \"frame\": {\n                    \"type\": \"chunk\",\n                    \"chunk\": {\n                        \"type\": \"usage\",\n                        \"usage\": { \"inputTokens\": 900_000, \"outputTokens\": 50 }\n                    }\n                }\n            }),\n        );\n        core.sink.flush();\n\n        let events = emitter.0.lock().unwrap().clone();\n        let usage = collect_kinds(&events)\n            .into_iter()\n            .find(|(kind, _)| kind == \"usage\")\n            .map(|(_, data)| data)\n            .expect(\"a usage event must be emitted for the chunk\");\n        assert_eq!(\n            usage.get(\"model_context_window\").and_then(Value::as_i64),\n            Some(1_000_000),\n            \"the window announced by request/context must reach the usage event: {usage}\"\n        );\n    }\n\n    /// Windows pair per request: a `request/context` without a window clears\n    /// the previous announcement instead of lending it to the next request\n    /// (e.g. a subagent on a different model mid-turn).\n    #[tokio::test]\n    async fn request_context_without_window_clears_the_previous_one() {\n        let (core, _registry, emitter) = test_core();\n        let mut state = TurnState::new(None);\n        let mut view = TurnView::default();\n\n        handle_session_event(\n            &core,\n            &mut state,\n            &mut view,\n            \"request/context\",\n            &json!({ \"provider\": \"mify\", \"model\": \"m\", \"contextWindow\": 1_000_000 }),\n        );\n        // The next request announces no window: the cached 1M must not leak.\n        handle_session_event(\n            &core,\n            &mut state,\n            &mut view,\n            \"request/context\",\n            &json!({ \"provider\": \"mify\", \"model\": \"m-small\" }),\n        );\n        handle_assistant_stream(\n            &core,\n            &mut state,\n            &mut view,\n            &json!({\n                \"type\": \"assistant-stream\",\n                \"frame\": {\n                    \"type\": \"chunk\",\n                    \"chunk\": {\n                        \"type\": \"usage\",\n                        \"usage\": { \"inputTokens\": 100, \"outputTokens\": 5 }\n                    }\n                }\n            }),\n        );\n        core.sink.flush();\n\n        let events = emitter.0.lock().unwrap().clone();\n        let usage = collect_kinds(&events)\n            .into_iter()\n            .find(|(kind, _)| kind == \"usage\")\n            .map(|(_, data)| data)\n            .expect(\"a usage event must be emitted for the chunk\");\n        assert_eq!(\n            usage.get(\"model_context_window\"),\n            None,\n            \"a window-less request/context must clear the cached window: {usage}\"\n        );\n    }\n\n    /// Flatten the sink's batched flushes into (kind, data) pairs.\n    fn collect_kinds(events: &[String]) -> Vec<(String, Value)> {\n        let mut kinds = Vec::new();\n        for raw in events {\n            let flushed: Value = serde_json::from_str(raw).expect(\"flushed batch must be JSON\");\n            let batch = flushed.as_array().cloned().unwrap_or_else(|| vec![flushed]);\n            for value in batch {\n                kinds.push((\n                    value\n                        .get(\"kind\")\n                        .and_then(Value::as_str)\n                        .unwrap_or(\"\")\n                        .to_string(),\n                    value.get(\"data\").cloned().unwrap_or(Value::Null),\n                ));\n            }\n        }\n        kinds\n    }\n\n    /// The native session id from the \"session\" event, or the preseeded one\n    /// carried by every payload of a resumed turn.\n    fn announced_session(events: &[String]) -> String {\n        for raw in events {\n            let flushed: Value = serde_json::from_str(raw).expect(\"flushed batch must be JSON\");\n            let batch = flushed.as_array().cloned().unwrap_or_else(|| vec![flushed]);\n            for value in batch {\n                if value.get(\"kind\").and_then(Value::as_str) == Some(\"session\") {\n                    return value\n                        .pointer(\"/data\")\n                        .and_then(Value::as_str)\n                        .unwrap_or(\"\")\n                        .to_string();\n                }\n                if let Some(id) = value.get(\"sessionId\").and_then(Value::as_str) {\n                    return id.to_string();\n                }\n            }\n        }\n        String::new()\n    }\n}\n"
    },
